const fs = require('fs');
const path = require('path');
const os = require('os');
const http = require('http');
const { exec, execSync, spawn } = require('child_process');

const APP_DIR = __dirname;

console.log("================================================");
console.log("===  GESTOR NAVAL OREY TECNICA - Acores  ===");
console.log("================================================");
console.log(`Diretorio: ${APP_DIR}`);
