const { PrismaClient } = require('@prisma/client');
const fs = require('fs');
const path = require('path');
const p = new PrismaClient();

async function main() {
  const hoje = new Date();
  const hojeStr = hoje.toISOString().slice(0, 10);

  // Find jangadas without inspection date or with expired date
  const jangadas = await p.jangada.findMany({
    where: {
      OR: [
        { dataProxInspecao: null },
        { dataProxInspecao: { lt: hojeStr } }
      ]
    },
    select: {
      id: true,
      serial: true,
      brand: true,
      model: true,
      capacity: true,
      shipNameManual: true,
      shipId: true,
    },
    orderBy: { id: 'asc' },
    take: 100
  });

  console.log('Jangadas sem inspecao ou expiradas:', jangadas.length);

  // Check which are already in queue
  const existingQueue = await p.serviceStationQueue.findMany({
    select: { jangadaId: true }
  });
  const existingIds = new Set(existingQueue.map(q => q.jangadaId));

  let added = 0;
  for (const j of jangadas) {
    if (existingIds.has(j.id)) continue;

    await p.serviceStationQueue.create({
      data: {
        serviceStationId: 1,
        jangadaId: j.id,
        dataChegada: new Date(),
        status: 'Aguardando',
        observacoes: `Adicionado automaticamente - ${j.brand || ''} ${j.model || ''} (${j.capacity || '?'}P)`
      }
    });
    added++;
  }

  console.log('Adicionados a fila:', added);
  console.log('Total na fila:', await p.serviceStationQueue.count());
}

main().finally(() => { p.$disconnect().catch(()=>{}).then(()=>process.exit(0)); });

import fs from "fs";
import path from "path";
import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();

async function main() {
  const logsDir = path.join(__dirname, "logs");
  const fuzzyFile = fs
    .readdirSync(logsDir)
    .find((f) => f.startsWith("reassociate_jangadas_fuzzy_") && f.endsWith(".json"));

  if (!fuzzyFile) {
    console.error("Fuzzy log not found in prisma/logs/");
    process.exit(1);
  }

  const fuzzyPath = path.join(logsDir, fuzzyFile);
  const raw = fs.readFileSync(fuzzyPath, "utf8");
  const parsed = JSON.parse(raw);

  // create alias table if missing (use raw SQL so we don't need a prisma schema migration)
  await prisma.$executeRaw`
    CREATE TABLE IF NOT EXISTS "JangadaAlias" (
      id SERIAL PRIMARY KEY,
      "jangadaId" INT REFERENCES "Jangada"(id) ON DELETE CASCADE,
      alias TEXT UNIQUE,
      "createdAt" TIMESTAMP DEFAULT now()
    )`;

  const results: Array<any> = parsed.results || [];
  const accepted: Array<any> = [];
  const skipped: Array<any> = [];

  for (const r of results) {
    const score = typeof r.score === "number" ? r.score : 0;
    if (score < 0.6) {
      skipped.push({ id: r.id, reason: "low-score", score, matchedSerial: r.matchedSerial });
      continue;
    }

    // load certificado to get original raftSerial
    const cert: any[] = await prisma.$queryRaw`
      SELECT "id", "raftSerial" FROM "CertificadoExtraido" WHERE id = ${r.id}`;

    if (!cert || cert.length === 0) {
      skipped.push({ id: r.id, reason: "cert-not-found", score, matchedSerial: r.matchedSerial });
      continue;
    }

    const raftSerial = cert[0].raftSerial;
    if (!raftSerial || raftSerial.trim() === "") {
      skipped.push({ id: r.id, reason: "no-raftSerial", score, matchedSerial: r.matchedSerial });
      continue;
    }

    const matchedSerial = r.matchedSerial;
    // find jangada by serial
    const jangadaRows: any[] = await prisma.$queryRaw`
      SELECT id, serial FROM "Jangada" WHERE serial = ${matchedSerial} LIMIT 1`;

    if (!jangadaRows || jangadaRows.length === 0) {
      skipped.push({ id: r.id, reason: "jangada-not-found", score, matchedSerial, raftSerial });
      continue;
    }

    const jangada = jangadaRows[0];
    if (raftSerial === jangada.serial) {
      skipped.push({ id: r.id, reason: "identical-to-canonical", score, matchedSerial, raftSerial });
      continue;
    }

    // insert alias (idempotent)
    try {
      await prisma.$executeRaw`
        INSERT INTO "JangadaAlias" ("jangadaId", alias) VALUES (${jangada.id}, ${raftSerial}) ON CONFLICT (alias) DO NOTHING`;
      accepted.push({ id: r.id, jangadaId: jangada.id, matchedSerial, raftSerial, score });
    } catch (err: any) {
      skipped.push({ id: r.id, reason: "insert-failed", error: String(err), score, matchedSerial, raftSerial });
    }
  }

  const out = {
    generatedAt: new Date().toISOString(),
    fuzzyFile,
    acceptedCount: accepted.length,
    skippedCount: skipped.length,
    accepted,
    skipped,
  };

  const outPath = path.join(logsDir, `add_jangada_aliases_from_fuzzy_${Date.now()}.json`);
  fs.writeFileSync(outPath, JSON.stringify(out, null, 2), "utf8");
  console.log(`Wrote ${outPath}`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

import fs from 'fs'
import path from 'path'
import { PrismaClient } from '@prisma/client'

const prisma = new PrismaClient()

function normalizeSerial(s?: string) {
  return (s || '').toString().trim().toLowerCase()
}

async function main() {
  const outDir = path.join(process.cwd(), 'prisma', 'logs')
  if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true })

  console.log('Analyzing jangadas for missing fields...')

  const totalRes: any = await prisma.$queryRaw`SELECT COUNT(*)::text AS n FROM "Jangada"`
  const total = Number(totalRes[0]?.n || 0)

  // many important fields are non-nullable in schema; check for empty strings or zero-capacity
  const ms1: any = await prisma.$queryRaw`SELECT COUNT(*)::text AS n FROM "Jangada" WHERE "serial" = ''`
  const missingSerial = Number(ms1[0]?.n || 0)
  const ms2: any = await prisma.$queryRaw`SELECT COUNT(*)::text AS n FROM "Jangada" WHERE "brand" = ''`
  const missingBrand = Number(ms2[0]?.n || 0)
  const ms3: any = await prisma.$queryRaw`SELECT COUNT(*)::text AS n FROM "Jangada" WHERE "model" = ''`
  const missingModel = Number(ms3[0]?.n || 0)
  const ms4: any = await prisma.$queryRaw`SELECT COUNT(*)::text AS n FROM "Jangada" WHERE "capacity" IS NULL OR "capacity" = 0`
  const missingCapacity = Number(ms4[0]?.n || 0)
  const ms5: any = await prisma.$queryRaw`SELECT COUNT(*)::text AS n FROM "Jangada" WHERE "packType" = ''`
  const missingPackType = Number(ms5[0]?.n || 0)

  // count rows where core descriptive fields are all missing/empty
  const am: any = await prisma.$queryRaw`
    SELECT COUNT(*)::text AS n FROM "Jangada" WHERE "brand" = '' AND "model" = '' AND ("capacity" IS NULL OR "capacity" = 0) AND "packType" = ''
  `
  const allMissing = Number(am[0]?.n || 0)

  const result = {
    generatedAt: new Date().toISOString(),
    total,
    missingSerial,
    missingBrand,
    missingModel,
    missingCapacity,
    missingPackType,
    allMissing,
  }

  const outFile = path.join(outDir, `analyze_jangadas_${new Date().toISOString().replace(/[:.]/g,'-')}.json`)
  fs.writeFileSync(outFile, JSON.stringify(result, null, 2))
  console.log(`Analysis written to ${outFile}`)

  await prisma.$disconnect()
}

main().catch(async (e) => { console.error(e); try { await prisma.$disconnect() } catch{}; process.exit(1) })

const { PrismaClient } = require('@prisma/client');
const fs = require('fs');
const path = require('path');
const XLSX = require('xlsx');

const prisma = new PrismaClient();

function norm(value) {
  return String(value ?? '').replace(/\s+/g, '').toUpperCase();
}

function clean(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function parseExcelDate(val) {
  if (val === null || val === undefined || val === '') return null;
  if (!isNaN(val) && String(val).trim() !== '') {
    const num = Number(val);
    const d = new Date(Math.round((num - 25569) * 86400 * 1000));
    if (d && !isNaN(d.getTime())) return d;
  }
  return new Date(String(val).trim());
}

function formatDateToIso(date) {
  if (!date) return '';
  const y = date.getUTCFullYear();
  const m = String(date.getUTCMonth() + 1).padStart(2, '0');
  const d = String(date.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

async function main() {
  console.log("=== ANALISANDO CERTIFICADOS DE 2025 NA BD ===");

  const dir = 'D:\\CERTIFICADOS 2025';
  if (!fs.existsSync(dir)) {
    console.error(`Diretório ${dir} não existe!`);
    await prisma.$disconnect();
    return;
  }

  const files = fs.readdirSync(dir).filter(f => f.toLowerCase().endsWith('.xlsx') && !f.startsWith('~$'));
  console.log(`Encontrados ${files.length} ficheiros no directório de 2025.`);

  let noJangadaCount = 0;
  let noInspecaoCount = 0;
  let matchCount = 0;

  for (const file of files) {
    const filePath = path.join(dir, file);

    let wb;
    try {
      wb = XLSX.readFile(filePath, { cellDates: false });
    } catch (e) {
      console.log(`Erro ao ler ${file}:`, e.message);
      continue;
    }

    const sheetNames = wb.SheetNames.map(s => s.toUpperCase());
    let serial = '';
    let certNo = '';
    let rawDate = null;

    if (sheetNames.includes("QUADRO")) {
      const qSheet = wb.Sheets[wb.SheetNames.find(s => norm(s) === 'QUADRO')];
      const qRows = XLSX.utils.sheet_to_json(qSheet, { header: 1 });

      serial = clean(qRows[6]?.[2]); // C7
      certNo = clean(qRows[4]?.[7]); // H5
      rawDate = qRows[80]?.[5]; // F81
    } else if (sheetNames.includes("CERTIFICADO")) {
      const cSheet = wb.Sheets[wb.SheetNames.find(s => norm(s) === 'CERTIFICADO')];
      const cRows = XLSX.utils.sheet_to_json(cSheet, { header: 1 });

      serial = clean(cRows[11]?.[2] || cRows[11]?.[3]); 
      certNo = clean(cRows[4]?.[7]);
      rawDate = cRows[46]?.[2];
    } else {
      // SOS ou outro layout de aba única
      const sheet = wb.Sheets[wb.SheetNames[0]];
      const rows = XLSX.utils.sheet_to_json(sheet, { header: 1 });
      serial = clean(rows[11]?.[7] || rows[11]?.[8]); // H12/I12
      certNo = file.replace(/\.xlsx$/i, '').split(' ')[0];
    }

    const normSerial = serial.replace(/['"\s]+/g, '').toUpperCase();
    if (!normSerial) {
      console.log(`Ficheiro "${file}": Não conseguiu ler o serial.`);
      continue;
    }

    // Buscar jangada correspondente na BD
    const dbJangada = await prisma.jangada.findUnique({
      where: { serial: normSerial }
    });

    if (!dbJangada) {
      noJangadaCount++;
      console.log(`Ficheiro "${file}": Jangada com serial "${normSerial}" não encontrada na BD.`);
      continue;
