function normalize(str) {
  return (str || '')
    .trim()
    .toUpperCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ');
}

function isND(mat) {
  if (!mat) return true;
  const n = mat.trim().toUpperCase();
  return n === 'N/D' || n === 'ND' || n === 'N.D.' || n === 'N/A' || n === 'NA' || n === '';
}

