}

function digits(s?: string) {
  if (!s) return ''
  const m = s.match(/(\d{3,})/g)
  return m ? m.join('') : ''
}

function latestFile(dir: string, pattern: RegExp) {
  const files = fs.readdirSync(dir).filter(f => pattern.test(f))
