    packType,
    cylinderSerial,
    cylinderPesoBruto,
    cylinderTara,
    cylinderCo2,
    cylinderN2,
    cylinderDataTeste,
    manufDate,
    inspectionDate,
    nextInspectionDate,
  };
}

// Unified parser that auto-detects layout
function parseWorkbook(filePath: string): any {
  const wb = XLSX.readFile(filePath, { cellDates: false });
  const sheets = wb.SheetNames.map(s => s.toUpperCase());

  let res: any = null;
  if (sheets.includes("CERTIFICADO")) {
    res = parseWorkbook2025(wb, filePath);
    res.layout = "CERTIFICADO";
    res.model = res.type;
    res.brand = inferBrand(res.type);
    if (path.basename(filePath).toUpperCase().includes("SOS")) {
      res.model = "SOS";
      if (res.brand === 'N/D') {
        res.brand = inferBrand(path.basename(filePath) + ' ' + res.type);
      }
    }
  } else if (sheets.includes("QUADRO")) {
    res = parseWorkbook2026(wb, filePath);
    res.layout = "QUADRO";
    res.type = res.model;
    if (path.basename(filePath).toUpperCase().includes("SOS")) {
      res.model = "SOS";
    }
  } else {
    res = {
      layout: "UNKNOWN",
      fileName: path.basename(filePath),
      certNo: '',
      shipName: '',
      serial: '',
      owner: '',
      type: '',
      brand: '',
      model: '',
      capacity: 0,
      manufDate: '',
      fabricType: '',
      painterLength: '',
      maxStowageHeight: '',
      cylinderSerial: '',
      cylinderCo2: '',
      cylinderN2: '',
      cylinderDataTeste: '',
      cylinderPesoBruto: '',
      cylinderTara: '',
      inspectionDate: '',
      nextInspectionDate: '',
      packType: '',
      flag: ''
    };
  }
  return res;
}

