              </button>
              <button
                onClick={() => setIsNotifying(false)}
                className="bg-slate-200 hover:bg-slate-300 text-slate-700 font-semibold px-4 py-2 rounded-xl text-xs transition cursor-pointer"
              >
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { NextRequest, NextResponse } from "next/server";
import prisma from "@/lib/prisma";
import { getAccessContext } from "@/lib/access-control";
import type { Prisma } from "@prisma/client";

export async function GET(req: NextRequest) {
  try {
    const access = await getAccessContext();
    if (!access) return NextResponse.json({ error: "Sessão obrigatória." }, { status: 401 });

    const { searchParams } = new URL(req.url);
    const limit = Math.min(500, Math.max(1, Number(searchParams.get("limit") || 100)));
    const query = String(searchParams.get("q") || "").trim();
    const tabela = searchParams.get("tabela");
    const tipoOperacao = searchParams.get("tipoOperacao");
    const startDate = searchParams.get("startDate");
    const endDate = searchParams.get("endDate");

    const andConditions: Prisma.AuditoriaWhereInput[] = [];

    if (query) {
      andConditions.push({
        OR: [
          { tabela: { contains: query, mode: "insensitive" as const } },
          { tipoOperacao: { contains: query, mode: "insensitive" as const } },
          { descricao: { contains: query, mode: "insensitive" as const } },
          { usuario: { contains: query, mode: "insensitive" as const } },
        ],
      });
    }

    if (tabela && tabela !== "TODOS") {
      andConditions.push({ tabela: { equals: tabela } });
    }

    if (tipoOperacao && tipoOperacao !== "TODOS") {
      andConditions.push({ tipoOperacao: { equals: tipoOperacao } });
    }

    if (startDate || endDate) {
      const dateCondition: { gte?: Date; lte?: Date } = {};
      if (startDate) {
        dateCondition.gte = new Date(startDate);
      }
      if (endDate) {
        // Estender até o final do dia
        const end = new Date(endDate);
        end.setHours(23, 59, 59, 999);
        dateCondition.lte = end;
      }
      andConditions.push({ createdAt: dateCondition });
    }

    const where = andConditions.length > 0 ? { AND: andConditions } : undefined;

    const rows = await prisma.auditoria.findMany({
      where,
      orderBy: { createdAt: "desc" },
      take: limit,
    });

    return NextResponse.json(rows);
  } catch (error) {
    return NextResponse.json({ error: "Erro ao carregar auditorias" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import prisma from "@/lib/prisma";
import { getAccessContext } from "@/lib/access-control";
import bcrypt from "bcryptjs";

// Ações que requerem confirmação reforçada
const SENSITIVE_ACTIONS = [
  "aprovar_orcamento",
  "faturar",
  "emitir_recibo",
  "alterar_precos",
  "eliminar_registo",
  "alterar_pagamento",
  "emitir_nota_credito",
] as const;

type SensitiveAction = (typeof SENSITIVE_ACTIONS)[number];

export async function POST(req: NextRequest) {
  try {
    const access = await getAccessContext();
    if (!access) {
      return NextResponse.json({ error: "Sessão obrigatória." }, { status: 401 });
    }

    const body = await req.json().catch(() => ({}));
    const { action, password } = body;

    if (!SENSITIVE_ACTIONS.includes(action)) {
      return NextResponse.json({ error: "Ação não reconhecida como sensível." }, { status: 400 });
    }

    if (!password || String(password).trim().length === 0) {
      return NextResponse.json({ error: "Indique a sua palavra-passe para confirmar." }, { status: 400 });
    }

    // Obter o utilizador atual da sessão
    const user = await prisma.user.findUnique({
      where: { id: access.userId },
      select: { id: true, name: true, email: true, passwordHash: true },
    });

    if (!user) {
      return NextResponse.json({ error: "Utilizador não encontrado." }, { status: 404 });
    }

    if (!user.passwordHash) {
      return NextResponse.json(
        { error: "Esta conta não tem palavra-passe definida (login Google). Use OTP SMS ou contacte o administrador." },
        { status: 400 },
      );
    }

    const valid = await bcrypt.compare(String(password), user.passwordHash);
    if (!valid) {
      return NextResponse.json({ error: "Palavra-passe incorreta. Ação não autorizada." }, { status: 403 });
    }

    await prisma.auditoria.create({
      data: {
        tabela: "ConfirmacaoSensivel",
        tipoOperacao: "AUTHORIZE",
        idRegisto: Number(user.id),
        descricao: `Ação sensível autorizada: ${action}`,
        usuario: user.name || user.email,
      },
    });

    return NextResponse.json({
      success: true,
      authorized: true,
      user: { id: user.id, name: user.name, email: user.email },
      action,
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error("[POST /api/auth/confirmar-acao]", error);
    return NextResponse.json({ error: "Erro ao confirmar ação sensível." }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import bcrypt from "bcryptjs";
import prisma from "@/lib/prisma";

export async function POST(req: NextRequest) {
  try {
    const body = await req.json().catch(() => null);
    if (!body) return NextResponse.json({ error: "Pedido inválido." }, { status: 400 });

    const { email, password, secret } = body as { email?: string; password?: string; secret?: string };

    if (!secret || secret !== "orey-setup-2026") {
      return NextResponse.json({ error: "Não autorizado." }, { status: 403 });
    }

    const normalizedEmail = (email || "").trim().toLowerCase();
    if (!normalizedEmail) return NextResponse.json({ error: "Email obrigatório." }, { status: 400 });
    if (!password || password.length < 6) return NextResponse.json({ error: "Password deve ter pelo menos 6 caracteres." }, { status: 400 });

    const passwordHash = await bcrypt.hash(password, 12);

    const existing = await prisma.user.findUnique({ where: { email: normalizedEmail } });

    if (existing) {
      await prisma.user.update({
        where: { id: existing.id },
        data: { passwordHash },
      });
      return NextResponse.json({ ok: true, message: `Password atualizada para ${normalizedEmail}.` });
    }

    const newUser = await prisma.user.create({
      data: {
        email: normalizedEmail,
        name: "Admin",
        passwordHash,
        role: "ADMIN",
        lastLoginAt: new Date(),
      },
    });

    return NextResponse.json({ ok: true, message: `Utilizador ${normalizedEmail} criado com password definida.`, userId: newUser.id });
  } catch (error: any) {
    console.error("[setup-password] Erro:", error?.message || error);
    return NextResponse.json({ error: error?.message || "Erro interno." }, { status: 500 });
  }
}

