import { NextResponse } from "next/server";
import { getToken } from "next-auth/jwt";
import { getAuthSecret } from "@/lib/auth";

export async function GET(req: Request) {
  const proto = req.headers.get("x-forwarded-proto") || "http";
  const host = req.headers.get("host") || "localhost:3000";

  const secret = process.env.AUTH_SECRET || process.env.NEXTAUTH_SECRET;
  const nextauthUrl = process.env.NEXTAUTH_URL;
  const authUrl = process.env.AUTH_URL;

  const isSecureEnv = !!(nextauthUrl ?? authUrl ?? "").startsWith("https");
  const isSecureHeader = proto === "https";

  const token1 = await getToken({ req, secret: secret || "" });
  const token2 = await getToken({ req, secret: secret || "", secureCookie: true, cookieName: "__Secure-next-auth.session-token" });
  const token3 = await getToken({ req, secret: secret || "", secureCookie: false, cookieName: "next-auth.session-token" });

  const cookieHeader = req.headers.get("cookie") || "";
  const hasSecureCookie = cookieHeader.includes("__Secure-next-auth.session-token");
  const hasInsecureCookie = cookieHeader.includes("next-auth.session-token=") && !hasSecureCookie;

  return NextResponse.json({
    proto,
    host,
    nextauthUrl,
    authUrl,
    authSecretSet: !!process.env.AUTH_SECRET,
    nextauthSecretSet: !!process.env.NEXTAUTH_SECRET,
    isSecureEnv,
    isSecureHeader,
    tokenAutoDetect: token1 ? { sub: token1.sub, role: token1.role } : null,
    tokenSecure: token2 ? { sub: token2.sub, role: token2.role } : null,
    tokenInsecure: token3 ? { sub: token3.sub, role: token3.role } : null,
    hasSecureCookie,
    hasInsecureCookie,
    cookieHeaderLength: cookieHeader.length,
  });
}

import { NextRequest, NextResponse } from "next/server";
import prisma from "@/lib/prisma";
import { getAccessContext } from "@/lib/access-control";
import { logAuditoria } from "@/lib/auditoria";

export async function POST(req: NextRequest, context: { params: Promise<{ id: string }> }) {
  try {
    const access = await getAccessContext();
    if (!access) {
      return NextResponse.json({ error: "Sessão obrigatória." }, { status: 401 });
    }

    const { id: rawId } = await context.params;
    const jangadaId = Number(rawId);
    if (!Number.isFinite(jangadaId) || jangadaId <= 0) {
      return NextResponse.json({ error: "ID de jangada inválido." }, { status: 400 });
    }

    const body = await req.json().catch(() => ({}));
    const acao = String(body?.acao || "aprovar").toLowerCase(); // "aprovar" | "rejeitar"
    const novoStatus = acao === "rejeitar" ? "Rejeitado" : "Aprovado";

    // Encontrar ordem de serviço ativa ou mais recente ligada à jangada
    const ordem = await prisma.ordemServico.findFirst({
      where: {
        jangadaId,
        status: { notIn: ["concluida", "cancelada"] },
      },
      orderBy: { createdAt: "desc" },
    });

    if (!ordem) {
      return NextResponse.json({ error: "Nenhuma Ordem de Serviço ativa encontrada para esta jangada." }, { status: 404 });
    }

    const atualizada = await prisma.$transaction(async (tx) => {
      const saved = await tx.ordemServico.update({
        where: { id: ordem.id },
        data: {
          orcamentoStatus: novoStatus,
          updatedAt: new Date(),
        },
      });

      // Se aprovado, converter eventuais reservas em saídas definitivas de stock se aplicável
      if (novoStatus === "Aprovado" && ordem.inspecaoId) {
        const reservas = await tx.movimentacaoStock.findMany({
          where: { inspecaoId: ordem.inspecaoId, tipo: "reserva" },
        });

        for (const resv of reservas) {
          const st = await tx.stock.findUnique({ where: { id: resv.stockId } });
          if (!st) continue;

          // Deduzir quantidade real e libertar reserva
          const novaQtde = Math.max(0, st.quantidade - resv.quantidade);
          const novaReserva = Math.max(0, (st.quantidadeReservada || 0) - resv.quantidade);

          await tx.stock.update({
            where: { id: st.id },
            data: {
              quantidade: novaQtde,
              quantidadeReservada: novaReserva,
            },
          });

          await tx.movimentacaoStock.create({
            data: {
              stockId: st.id,
              tipo: "saida",
              quantidade: resv.quantidade,
              quantidadeAntes: st.quantidade,
              quantidadeDepois: novaQtde,
              motivo: `Consumo definitivo por orçamento aprovado (OT ${ordem.numeroOrdem})`,
              usuario: access.email || "sistema",
              ordemServicoId: ordem.id,
            },
          });
        }
      }

      return saved;
    });

    await logAuditoria({
      tabela: "OrdemServico",
      tipoOperacao: "UPDATE",
      idRegisto: ordem.id,
      descricao: `Orçamento da OT ${ordem.numeroOrdem} marcado como ${novoStatus} para a jangada ${jangadaId}.`,
      usuario: access.email || "sistema",
    });

    return NextResponse.json({ success: true, ordemServicoId: ordem.id, orcamentoStatus: novoStatus });
  } catch (error: unknown) {
    console.error("Erro ao aprovar/rejeitar orçamento:", error);
    return NextResponse.json({ error: error instanceof Error ? error.message : "Erro interno ao atualizar orçamento." }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import prisma from "@/lib/prisma";
import { getAccessContext } from "@/lib/access-control";
import { logAuditoria } from "@/lib/auditoria";
import { getIvaRate, calcTotal, round2 } from "@/lib/iva";
import { parseOrdemServicoMeta, toOrdemServicoMetaJson } from "@/lib/ordens-servico";

export async function PUT(req: NextRequest, context: { params: Promise<{ id: string }> }) {
  try {
    const access = await getAccessContext();
    if (!access) {
      return NextResponse.json({ error: "Sessão obrigatória." }, { status: 401 });
    }

    const { id: rawId } = await context.params;
    const jangadaId = Number(rawId);
    if (!Number.isFinite(jangadaId) || jangadaId <= 0) {
      return NextResponse.json({ error: "ID de jangada inválido." }, { status: 400 });
    }

    const body = await req.json().catch(() => ({}));
    const linhas = Array.isArray(body?.linhas) ? body.linhas : [];
    const valorDesconto = Number(body?.valorDesconto || 0);
    const isIsentoIva = Boolean(body?.isIsentoIva);

    const ordem = await prisma.ordemServico.findFirst({
      where: {
        jangadaId,
        status: { notIn: ["concluida", "cancelada"] },
      },
      orderBy: { createdAt: "desc" },
    });

    if (!ordem) {
      return NextResponse.json({ error: "Nenhuma Ordem de Serviço ativa encontrada para esta jangada." }, { status: 404 });
    }

    const orderMeta = parseOrdemServicoMeta(ordem.metadados);

    const nextMaterials = linhas.map((linha: Record<string, unknown>, index: number) => {
      const stockIdNum = linha.stockId != null && linha.stockId !== "" ? Number(linha.stockId) : null;
      const qty = Number(linha.quantidade ?? linha.quantidadeUsada ?? 1) || 0;
      const preco = Number(linha.precoUnitario ?? linha.unitPrice ?? 0) || 0;
      return {
        id: linha.id || `orcamento-edit-${index}`,
        stockId: Number.isFinite(stockIdNum) ? stockIdNum : null,
        referencia: linha.referencia || "SEM-REF",
        descricao: linha.descricao || "Artigo",
        quantidadePrevista: qty,
        quantidadeUsada: qty,
        precoUnitario: preco,
        disponibilidade: 0,
        reservado: false,
        consumido: true,
        origem: "orcamento",
      };
    });

    const valorPecas = nextMaterials.reduce(
      (acc: number, item: Record<string, unknown>) => acc + Math.max(0, Number(item.quantidadeUsada || 0)) * Math.max(0, Number(item.precoUnitario || 0)),
      0
    );

    const valorTotal = calcTotal(valorPecas, 0, valorDesconto, isIsentoIva);
    const subtotal = Math.max(0, valorPecas - valorDesconto);
    const iva = isIsentoIva ? 0 : round2(subtotal * getIvaRate());

    const updated = await prisma.ordemServico.update({
      where: { id: ordem.id },
      data: {
        valorPecas: round2(valorPecas),
        valorDesconto: round2(valorDesconto),
        isIsentoIva,
        valorTotal,
        metadados: toOrdemServicoMetaJson({
          ...orderMeta,
          materials: nextMaterials,
        }),
        updatedAt: new Date(),
      },
    });

    await logAuditoria({
      tabela: "OrdemServico",
      tipoOperacao: "UPDATE",
      idRegisto: ordem.id,
      descricao: `Orçamento da OT ${ordem.numeroOrdem} atualizado manualmente na ficha da jangada.`,
      usuario: access.email || "sistema",
    });

    return NextResponse.json({ success: true, ordemServicoId: updated.id, valorTotal, valorPecas });
  } catch (error: unknown) {
    console.error("Erro ao atualizar orçamento:", error);
    return NextResponse.json({ error: error instanceof Error ? error.message : "Erro interno ao atualizar orçamento." }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import prisma from "@/lib/prisma";
import { getAccessContext } from "@/lib/access-control";

export async function GET(req: NextRequest) {
  try {
    const access = await getAccessContext();
    if (!access) return NextResponse.json({ error: "Sessão obrigatória." }, { status: 401 });

    const orders = await prisma.ordemServico.findMany({
      where: {
        status: "concluida",
        faturaOrdemServicos: { some: { fatura: { is: { cancelada: false } } } },
      },
      include: {
        tecnico: { select: { id: true, nome: true } },
        serviceStation: { select: { id: true, nome: true, codigo: true } },
      },
    });

    const tecnicoMap = new Map<string, { nome: string; count: number; total: number; maoObra: number; pecas: number }>();
    const stationMap = new Map<string, { nome: string; count: number; total: number; maoObra: number; pecas: number }>();

    orders.forEach((o) => {
      const tecName = o.tecnico?.nome || o.tecnicoResponsavel || "Técnico Geral";
      const stationName = o.serviceStation?.nome || "Orey Açores (Sede)";

      const tot = Number(o.valorTotal || 0);
      const mo = Number(o.valorMaoObra || 0);
      const pc = Number(o.valorPecas || 0);

      const tCurr = tecnicoMap.get(tecName) || { nome: tecName, count: 0, total: 0, maoObra: 0, pecas: 0 };
      tCurr.count += 1;
      tCurr.total += tot;
      tCurr.maoObra += mo;
      tCurr.pecas += pc;
      tecnicoMap.set(tecName, tCurr);

      const sCurr = stationMap.get(stationName) || { nome: stationName, count: 0, total: 0, maoObra: 0, pecas: 0 };
      sCurr.count += 1;
      sCurr.total += tot;
      sCurr.maoObra += mo;
      sCurr.pecas += pc;
      stationMap.set(stationName, sCurr);
    });

    return NextResponse.json({
      tecnicos: Array.from(tecnicoMap.values()).sort((a, b) => b.total - a.total),
      estacoes: Array.from(stationMap.values()).sort((a, b) => b.total - a.total),
    });
  } catch (error) {
    console.error("[GET /api/kpis/rentabilidade]", error);
    return NextResponse.json({ error: "Erro ao calcular KPIs de rentabilidade." }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import prisma from "@/lib/prisma";
import ExcelJS from "exceljs";
import { getAccessContext } from "@/lib/access-control";
import { carregarFaturaPorOrdemServico, resumoFatura } from "@/lib/faturamento";
import { formatIsencaoIva } from "@/lib/iva-isencao-codes";

const ISSUER_NAME = "Orey Técnica - Serviços Navais";

function formatEuro(value: number) {
  return new Intl.NumberFormat("pt-PT", {
    style: "currency",
    currency: "EUR",
  }).format(value || 0);
}

function formatDate(value: Date | null | undefined) {
  if (!value) return "";
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return "";
  return `${String(d.getDate()).padStart(2, "0")}/${String(d.getMonth() + 1).padStart(2, "0")}/${d.getFullYear()}`;
}

export async function GET(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const access = await getAccessContext();
    if (!access) return NextResponse.json({ error: "Sessão obrigatória." }, { status: 401 });

    const { id: rawId } = await params;
    const id = Number(rawId);
    if (!Number.isFinite(id) || id <= 0) {
      return NextResponse.json({ error: "ID inválido." }, { status: 400 });
    }

    const order = await prisma.ordemServico.findUnique({
      where: { id },
      include: {
        jangada: {
          select: { serial: true, brand: true, model: true, owner: true, shipNameManual: true },
        },
        cliente: {
          select: { nome: true, numeroCliente: true, nif: true, morada: true, localidade: true, ilha: true },
        },
        serviceStation: { select: { codigo: true, nome: true } },
        tecnico: { select: { nome: true } },
      },
    });

    if (!order) {
      return NextResponse.json({ error: "Ordem de serviço não encontrada." }, { status: 404 });
    }

    if (order.status !== "concluida") {
      return NextResponse.json(
        { error: "A fatura só pode ser gerada para ordens de serviço concluídas." },
        { status: 400 },
      );
    }

    const link = await carregarFaturaPorOrdemServico(id);
    const fatura = link?.fatura ?? null;

    const resumo = resumoFatura(link ?? null);
    const ordens = (fatura ? resumo.ordens : [order]) as Array<typeof order>;

    const pecas = Number(order.valorPecas || 0);
    const maoObra = Number(order.valorMaoObra || 0);
    const desconto = Number(order.valorDesconto || 0);
    const subtotal = fatura ? resumo.subtotal : pecas + maoObra - desconto;
    const iva = fatura ? resumo.iva : resumo.isentoIva ? 0 : subtotal * 0.16;
    const total = fatura ? resumo.total : subtotal + iva;

    const clienteNome = resumo.clienteNome;
    const nif = resumo.cliente?.nif || null;
    const morada = resumo.cliente?.morada || null;
    const localidade = resumo.cliente?.localidade || null;
    const ilha = resumo.cliente?.ilha || null;
    const navio = resumo.navio;
    const jangadaLabel = resumo.jangadaLabel;
    const serial = resumo.jangada?.serial || null;
    const issuer = resumo.issuer;
    const emissao = resumo.emissao;
    const numeroFatura = resumo.numeroFatura;
    const dataTrabalho = resumo.dataTrabalho || order.dataConclusao || order.dataAbertura || order.createdAt || null;
    const tecnicoNome = resumo.tecnico || order.tecnico?.nome || null;
    const pagamentoStatus = resumo.pagamentoStatus;

    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet("Fatura");

    worksheet.columns = [
      { header: "", key: "a", width: 34 },
      { header: "", key: "b", width: 56 },
      { header: "", key: "c", width: 12 },
      { header: "", key: "d", width: 16 },
    ];

    worksheet.mergeCells("A1:D1");
    worksheet.getCell("A1").value = "FATURA";
    worksheet.getCell("A1").font = { bold: true, size: 18, color: { argb: "FFFFFF" } };
    worksheet.getCell("A1").fill = {
      type: "pattern",
      pattern: "solid",
      fgColor: { argb: "0F766E" },
    };
    worksheet.getRow(1).height = 30;
    worksheet.getCell("A1").alignment = { vertical: "middle", horizontal: "left" };

    let rowIndex = 2;
    const issuerRows: Array<[string, string]> = [
      ["Fornecedor", issuer],
      ["Cliente", clienteNome],
    ];
    if (nif) issuerRows.push(["NIF Cliente", nif]);
    if (morada) issuerRows.push(["Morada", morada]);
    if (localidade || ilha) issuerRows.push(["Localidade / Ilha", `${localidade || ""} ${ilha || ""}`.trim()]);
    issuerRows.push(["Fatura Nº", numeroFatura]);
    issuerRows.push(["Data de emissão", formatDate(emissao)]);
    issuerRows.push(["Data de trabalho", formatDate(dataTrabalho)]);
    issuerRows.push(["Embarcação", navio]);
    issuerRows.push(["Jangada", jangadaLabel]);
    if (serial) issuerRows.push(["Nº Série Jangada", serial]);
    if (tecnicoNome) issuerRows.push(["Técnico responsável", tecnicoNome]);
    issuerRows.push(["Estado de Pagamento", pagamentoStatus]);

    issuerRows.forEach(([label, value]) => {
      worksheet.getCell(`A${rowIndex}`).value = label;
      worksheet.getCell(`A${rowIndex}`).font = { bold: true };
      worksheet.getCell(`B${rowIndex}`).value = value;
      rowIndex += 1;
    });

    rowIndex += 1;
    worksheet.getCell(`A${rowIndex}`).value = "Referência";
    worksheet.getCell(`B${rowIndex}`).value = "Descrição";
    worksheet.getCell(`C${rowIndex}`).value = "Qtd";
    worksheet.getCell(`D${rowIndex}`).value = "Valor";
    worksheet.getRow(rowIndex).font = { bold: true };
    worksheet.getRow(rowIndex).fill = {
      type: "pattern",
      pattern: "solid",
      fgColor: { argb: "CCFBF1" },
    };
    const headerRow = rowIndex;
    rowIndex += 1;

    const lineRows: Array<string[]> = [];
    for (const ot of ordens) {
      const otPecas = Number(ot.valorPecas || 0);
      const otMaoObra = Number(ot.valorMaoObra || 0);
      const otDesconto = Number(ot.valorDesconto || 0);
      const referencia = ot.numeroOrdem || `#${ot.id}`;
      lineRows.push([referencia, `Mão-de-obra (trabalhos executados)`, "1", formatEuro(otMaoObra)]);
      lineRows.push([referencia, "Peças / materiais", "1", formatEuro(otPecas)]);
      if (otDesconto > 0) {
        lineRows.push([referencia, "Desconto", "1", `-${formatEuro(otDesconto)}`]);
      }
    }
    if (lineRows.length === 0) {
      lineRows.push([order.numeroOrdem || `#${order.id}`, "Serviços prestados", "1", formatEuro(total)]);
    }

    lineRows.forEach((row) => {
      row.forEach((value, colIndex) => {
        worksheet.getCell(`${String.fromCharCode(65 + colIndex)}${rowIndex}`).value = value;
      });
      rowIndex += 1;
    });

    const totalRows: Array<{ label: string; value: string; bold?: boolean }> = [
      { label: "Subtotal", value: formatEuro(subtotal) },
      { label: "IVA", value: resumo.isentoIva ? formatIsencaoIva(true, resumo.codigoIsencaoIva) : `16%  ${formatEuro(iva)}` },
      { label: "TOTAL", value: formatEuro(total), bold: true },
      ...(resumo.isentoIva
        ? [{ label: "Motivo isenção IVA", value: formatIsencaoIva(true, resumo.codigoIsencaoIva), bold: false }]
        : []),
    ];
    totalRows.forEach((entry) => {
      worksheet.getCell(`A${rowIndex}`).value = "";
      worksheet.getCell(`B${rowIndex}`).value = entry.label;
      worksheet.getCell(`D${rowIndex}`).value = entry.value;
      if (entry.bold) {
        worksheet.getCell(`B${rowIndex}`).font = { bold: true };
        worksheet.getCell(`D${rowIndex}`).font = { bold: true };
        worksheet.getCell(`B${rowIndex}`).fill = {
          type: "pattern",
          pattern: "solid",
          fgColor: { argb: "CCFBF1" },
        };
        worksheet.getCell(`D${rowIndex}`).fill = {
          type: "pattern",
          pattern: "solid",
          fgColor: { argb: "CCFBF1" },
        };
      }
      rowIndex += 1;
    });

    worksheet.eachRow((row, rowNumber) => {
      if (rowNumber === headerRow) return;
      if (rowNumber > 1) {
        row.eachCell((cell) => {
          cell.border = {
            top: { style: "thin", color: { argb: "E5E7EB" } },
            left: { style: "thin", color: { argb: "E5E7EB" } },
            bottom: { style: "thin", color: { argb: "E5E7EB" } },
            right: { style: "thin", color: { argb: "E5E7EB" } },
          };
        });
      }
    });

    const buffer = await workbook.xlsx.writeBuffer();

    return new NextResponse(buffer, {
      status: 200,
      headers: {
        "Content-Disposition": `attachment; filename=fatura-${numeroFatura}.xlsx`,
        "Content-Type": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      },
    });
  } catch (error: unknown) {
    console.error("Erro ao gerar fatura Excel:", error);
    const message = error instanceof Error ? error.message : "Erro ao gerar a fatura Excel.";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

