    const mmYyyy = dateStr.match(/^(\d{1,2})\/(\d{4})$/);
    if (mmYyyy) {
      return `${mmYyyy[2]}-${mmYyyy[1].padStart(2, '0')}`;
    }
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return '';
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    return `${yyyy}-${mm}`;
