                      </select>
                      {editForm.cylinderTuboCamaraInferiorRef && (
                        <button
                          type="button"
                          onClick={() => {
                            const si = stockItems.find((s) => s.referencia === editForm.cylinderTuboCamaraInferiorRef);
                            if (!si) return;
                            const qty = prompt('Quantidade a adicionar ao stock:', '1');
                            if (!qty) return;
                            fetch(`/api/stock/${si.id}`, {
