                    </>
                  ) : (
                    <p className="font-semibold text-slate-800">{data.cylinderTuboCamaraInferiorRef || '—'}</p>
                  )}
                </div>

                <div className="space-y-1">
                  <span className="text-xs font-bold uppercase tracking-wider text-slate-400">Válvulas de Alívio</span>
