                  disabled={saving}
                >
                  {saving ? "A guardar..." : "Guardar"}
                </button>
                <button
                  className="bg-gray-200 hover:bg-gray-300 text-gray-900 font-semibold px-4 py-1 rounded text-sm shadow transition"
