          ...prev,
          itemsInAlert: Number(needs.summary?.itemsInAlert || negativos || topBuy.length),
          reorderCost: Number(needs.summary?.totalReorderCost || 0),
          coveragePercent: Number(needs.summary?.coveragePercent ?? 100),
