                        style={{ width: `${Math.min(100, ((stats?.certificadosAte60d ?? 0) / (stats?.jangadas || 1)) * 100)}%` }}
                      />
                    </div>
                  </div>

                  <div>
                    <div className="flex justify-between text-xs font-semibold text-slate-600 mb-1">
