                      <div 
                        className="bg-blue-500 h-full rounded-full transition-all duration-500"
                        style={{ width: `${Math.min(100, ((stats?.certificadosAte90d ?? 0) / (stats?.jangadas || 1)) * 100)}%` }}
                      />
