                                  className={`rounded-md px-2 py-0.5 text-[10px] font-bold ${
                                    a.referenciaExibida.trim()
                                      ? "bg-blue-600 hover:bg-blue-700 text-white cursor-pointer"
                                      : "bg-slate-200 text-slate-400 cursor-not-allowed"
                                  }`}
                                >
                                  Adicionar
                                </button>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                )}

                {budgetError && (
                  <div className="rounded-xl bg-rose-50 border border-rose-200 p-3 text-sm text-rose-700">
                    {budgetError}
                  </div>
                )}

                {/* Actions */}
                <div className="flex items-center justify-between gap-2 pt-2 border-t border-slate-100">
                  <div className="text-[11px] text-slate-400">
                    {budgetAutosaving ? (
                      <span className="inline-flex items-center gap-1 text-blue-600">
                        <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-blue-500" />
                        A guardar automaticamente…
                      </span>
                    ) : budgetAutoError ? (
                      <span className="text-rose-600" title={budgetAutoError}>
                        Guarda automática falhou — use "Guardar Orçamento"
                      </span>
                    ) : budgetLastSavedAt ? (
                      <span>
                        Guardado automaticamente às{" "}
                        {String(budgetLastSavedAt.getHours()).padStart(2, "0")}:
                        {String(budgetLastSavedAt.getMinutes()).padStart(2, "0")}
                      </span>
                    ) : (
                      <span>As alterações são guardadas automaticamente</span>
                    )}
                  </div>
                  <div className="flex gap-2">
                    <button
                      type="button"
                      onClick={closeBudgetEditor}
                      className="rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 px-4 py-2 text-xs font-bold transition-colors cursor-pointer"
                    >
                      Cancelar
                    </button>
                    <button
                      type="button"
                      onClick={handleSaveBudget}
                      disabled={budgetSaving}
                      className="rounded-xl bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 text-xs font-bold transition-colors cursor-pointer shadow-sm disabled:opacity-50"
                    >
                      {budgetSaving ? "A guardar…" : "Guardar Orçamento"}
                    </button>
                  </div>
                </div>
              </>
            )}
          </div>
        </div>
      )}

      {/* Request Inspection Modal */}
      {isRequestModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 p-4 backdrop-blur-sm animate-fade-in">
          <div className="w-full max-w-lg rounded-3xl border border-slate-200 bg-white p-6 shadow-2xl space-y-4 max-h-[90vh] overflow-y-auto">
            {/* Header */}
            <div>
              <span className="text-[10px] uppercase font-black text-blue-600 tracking-wider">
                Solicitar Serviço
              </span>
              <h2 className="text-xl font-black text-slate-800 tracking-tight mt-0.5">
                Pedir Assistência / Inspeção
              </h2>
              <p className="text-xs text-slate-400 mt-1">
                Submeta um pedido de inspeção obrigatória ou manutenção. A nossa equipa entrará em contacto para agendar.
              </p>
            </div>

            <form onSubmit={handleRequestSubmit} className="space-y-4">
              {submitError && (
                <div className="rounded-xl bg-red-50 border border-red-200 p-3 text-xs text-red-800">
                  {submitError}
                </div>
              )}

              {/* Vessel Select */}
              <div className="space-y-1">
                <label className="block text-xs font-bold text-slate-600">
                  Embarcação / Navio <span className="text-rose-500">*</span>
                </label>
                <div className="relative" ref={shipComboboxRef}>
                <input
                  type="text"
                  value={shipSearch}
                  onFocus={() => setShipDropdownOpen(true)}
                  onChange={(e) => {
                    setShipSearch(e.target.value);
                    setShipDropdownOpen(true);
                  }}
                  placeholder={selectedShipId ? (navios.find((n) => String(n.id) === selectedShipId)?.nome || "Pesquisar navio...") : "Pesquisar navio..."}
                  className="w-full rounded-xl border border-slate-200 bg-white p-2.5 pr-9 text-xs text-slate-700 focus:outline-none focus:border-blue-500"
                />
                {selectedShipId ? (
                  <button
                    type="button"
                    onClick={() => {
                      setSelectedShipId("");
                      setShipSearch("");
                      setShipDropdownOpen(true);
                    }}
                    tabIndex={-1}
                    className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                    title="Limpar seleção"
                  >
                    <X className="h-4 w-4" />
                  </button>
                ) : (
                  <ChevronDown
                    className="pointer-events-none absolute right-2.5 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400"
                  />
                )}
                {shipDropdownOpen && (
                  <div className="absolute z-20 mt-1 max-h-56 w-full overflow-auto rounded-xl border border-slate-200 bg-white shadow-lg">
                    {filteredShips.length === 0 ? (
                      <div className="px-3 py-2.5 text-xs text-slate-500">Nenhum navio encontrado.</div>
                    ) : (
                      filteredShips.map((n) => (
                        <button
                          type="button"
                          key={n.id}
                          onClick={() => {
                            setSelectedShipId(String(n.id));
                            setShipSearch("");
                            setShipDropdownOpen(false);
                          }}
                          className={`flex w-full items-center justify-between px-3 py-2.5 text-left text-xs transition hover:bg-blue-50 ${
                            String(n.id) === selectedShipId ? "bg-blue-50 text-blue-700" : "text-slate-700"
                          }`}
                        >
                          <span>{n.nome}</span>
                          {n.ilha ? <span className="text-[10px] text-slate-400">{n.ilha}</span> : null}
                        </button>
                      ))
                    )}
                  </div>
                )}
              </div>
            </div>

            {/* Liferaft Select (Conditional on ship select) */}
              {selectedShipId && (
                <div className="space-y-1">
                  <label className="block text-xs font-bold text-slate-600">
                    Jangada Salva-vidas <span className="text-rose-500">*</span>
                  </label>
                  {filteredJangadas.length === 0 ? (
                    <div className="text-xs text-rose-600 font-semibold p-1">
                      Este navio não tem jangadas registadas. Por favor contacte o suporte.
                    </div>
                  ) : (
                    <select
                      required
                      value={selectedJangadaId}
                      onChange={(e) => setSelectedJangadaId(e.target.value)}
                      className="w-full rounded-xl border border-slate-200 bg-white p-2.5 text-xs text-slate-700 focus:outline-none focus:border-blue-500"
                    >
                      {filteredJangadas.map((j) => (
                        <option key={j.id} value={j.id}>
                          {j.brand} {j.model} (S/N: {j.serial})
                        </option>
                      ))}
                    </select>
                  )}
                </div>
              )}

              <div className="grid grid-cols-2 gap-4">
                {/* Port Select */}
                <div className="space-y-1">
                  <label className="block text-xs font-bold text-slate-600">
                    Porto de Assistência (S. Miguel) <span className="text-rose-500">*</span>
                  </label>
                  <select
                    required
                    value={porto}
                    onChange={(e) => setPorto(e.target.value)}
                    className="w-full rounded-xl border border-slate-200 bg-white p-2.5 text-xs text-slate-700 focus:outline-none focus:border-blue-500"
                  >
                    <option value="Ponta Delgada">Ponta Delgada</option>
                    <option value="Rabo de Peixe">Rabo de Peixe</option>
                    <option value="Lagoa">Lagoa</option>
                    <option value="Vila Franca do Campo">Vila Franca do Campo</option>
                    <option value="Ribeira Grande">Ribeira Grande</option>
                    <option value="Nordeste">Nordeste</option>
                    <option value="Povoação">Povoação</option>
                    <option value="Outro (S. Miguel)">Outro (S. Miguel)</option>
                  </select>
                  <p className="text-[10px] text-amber-600 font-semibold mt-0.5 leading-tight">
                    A assistência está disponível exclusivamente na ilha de São Miguel.
                  </p>
                </div>

                <div className="space-y-2">
                  {/* Preferred Date */}
                  <div className="space-y-1">
                    <label className="block text-xs font-bold text-slate-600">
                      Data Pretendida <span className="text-rose-500">*</span>
                    </label>
                    <input
                      type="date"
                      required
                      value={dataPretendida}
                      onChange={(e) => setDataPretendida(e.target.value)}
                      className="w-full rounded-xl border border-slate-200 bg-white p-2 text-xs text-slate-700 focus:outline-none focus:border-blue-500"
                    />
                  </div>

                  {/* Preferred Time */}
                  <div className="space-y-1">
                    <label className="block text-xs font-bold text-slate-600">
                      Hora Pretendida <span className="text-rose-500">*</span>
                    </label>
                    <input
                      type="time"
                      required
                      value={horaPretendida}
                      onChange={(e) => setHoraPretendida(e.target.value)}
                      className="w-full rounded-xl border border-slate-200 bg-white p-2 text-xs text-slate-700 focus:outline-none focus:border-blue-500"
                    />
                  </div>
                </div>
              </div>

              {/* Shipment Info for other islands */}
              {isOtherIsland && (
                <div className="rounded-xl border border-blue-100 bg-blue-50/40 p-3.5 space-y-3">
                  <div className="flex items-center gap-2 text-xs font-bold text-blue-800 uppercase tracking-wider">
                    <span>📦</span> Detalhes do Envio (Transitário)
                  </div>
                  <p className="text-[10px] text-blue-600 leading-normal">
                    Como a sua embarcação pertence à ilha de <strong>{selectedShipObject?.ilha}</strong>, a assistência requer o envio do equipamento para a nossa estação em São Miguel. Por favor, preencha os dados do envio.
                  </p>

                  <div className="space-y-1">
                    <label className="block text-[11px] font-bold text-slate-600">
                      Transitário / Transportadora <span className="text-rose-500">*</span>
                    </label>
                    <input
                      type="text"
                      required
                      placeholder="Ex: Transitário Açoreano, Bensaude, etc."
                      value={transitario}
                      onChange={(e) => setTransitario(e.target.value)}
                      className="w-full rounded-lg border border-slate-200 bg-white p-2 text-xs text-slate-700 focus:outline-none focus:border-blue-500"
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    <div className="space-y-1">
                      <label className="block text-[11px] font-bold text-slate-600">
                        Data de Entrega / Envio <span className="text-rose-500">*</span>
                      </label>
                      <input
                        type="date"
                        required
                        value={dataEntrega}
                        onChange={(e) => setDataEntrega(e.target.value)}
                        className="w-full rounded-lg border border-slate-200 bg-white p-2 text-xs text-slate-700 focus:outline-none focus:border-blue-500"
                      />
                    </div>

                    <div className="space-y-1">
                      <label className="block text-[11px] font-bold text-slate-600">
                        Código de Rastreio <span className="text-slate-400 font-normal">(Opcional)</span>
                      </label>
                      <input
                        type="text"
                        placeholder="Nº Guia / Rastreio"
                        value={trackingCode}
                        onChange={(e) => setTrackingCode(e.target.value)}
                        className="w-full rounded-lg border border-slate-200 bg-white p-2 text-xs text-slate-700 focus:outline-none focus:border-blue-500"
                      />
                    </div>
                  </div>
                </div>
              )}

              {/* New HRU Checkbox */}
              <div className="rounded-xl border border-slate-100 bg-slate-50/70 p-3.5 flex items-start gap-3">
                <input
                  type="checkbox"
                  id="hru_checkbox"
                  checked={necessitaHRU === "yes"}
                  onChange={(e) => setNecessitaHRU(e.target.checked ? "yes" : "no")}
                  className="mt-0.5 rounded border-slate-300 text-blue-600 focus:ring-blue-500"
                />
                <label htmlFor="hru_checkbox" className="text-xs text-slate-600 cursor-pointer select-none">
                  <span className="font-bold text-slate-700 block">Necessita de Novo HRU?</span>
                  Assinale se necessita de fornecimento e instalação de um novo Dispositivo de Libertação Hidrostática (HRU) para a jangada.
                </label>
              </div>

              {/* Observations */}
              <div className="space-y-1">
                <label className="block text-xs font-bold text-slate-600">
                  Observações / Instruções Adicionais
                </label>
                <textarea
                  value={observacoes}
                  onChange={(e) => setObservacoes(e.target.value)}
                  placeholder="Ex: Porto alternativo, detalhes da urgência ou outros equipamentos a verificar..."
                  rows={3}
                  className="w-full rounded-xl border border-slate-200 bg-white p-2.5 text-xs text-slate-700 focus:outline-none focus:border-blue-500"
                />
              </div>

              {/* Footer Buttons */}
              <div className="pt-2 flex justify-end gap-2.5">
                <button
                  type="button"
                  onClick={() => setIsRequestModalOpen(false)}
                  className="rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 px-4 py-2 text-xs font-bold transition-colors cursor-pointer"
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  disabled={!!(isSubmitting || !selectedShipId || (selectedShipId && filteredJangadas.length === 0))}
                  className="rounded-xl bg-blue-600 hover:bg-blue-700 text-white px-5 py-2 text-xs font-bold transition-colors disabled:opacity-50 cursor-pointer"
                >
                  {isSubmitting ? "A enviar..." : "Submeter Pedido"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState, use } from "react";
import { CheckCircle2, XCircle, Loader2, ShieldCheck, FileText, AlertCircle, CreditCard } from "lucide-react";

const PAGAMENTO_BADGE_CLASSES: Record<string, string> = {
  Pendente: "bg-amber-500/20 text-amber-300 border-amber-500/30",
  "Pago Parcialmente": "bg-blue-500/20 text-blue-300 border-blue-500/30",
  Pago: "bg-emerald-500/20 text-emerald-300 border-emerald-500/30",
  Vencido: "bg-rose-500/20 text-rose-300 border-rose-500/30",
};

type PublicOrder = {
  id: number;
  numeroOrdem?: string | null;
  status?: string | null;
  orcamentoStatus?: string | null;
  valorPecas?: number | null;
  valorMaoObra?: number | null;
  valorDesconto?: number | null;
  isIsentoIva?: boolean | null;
  valorTotal?: number | null;
  metadados?: any;
  createdAt?: string | null;
  jangada?: { serial?: string | null; brand?: string | null; model?: string | null; owner?: string | null; shipNameManual?: string | null } | null;
  cliente?: { nome?: string | null; nif?: string | null; morada?: string | null; localidade?: string | null; ilha?: string | null } | null;
  serviceStation?: { nome?: string | null } | null;
};

export default function PublicOrcamentoPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  const [loading, setLoading] = useState(true);
  const [order, setOrder] = useState<PublicOrder | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [actionDone, setActionDone] = useState<string | null>(null);

  useEffect(() => {
    async function loadOrder() {
      try {
        const res = await fetch(`/api/ordens-servico/${id}`, { cache: "no-store" });
        if (!res.ok) throw new Error("Orçamento não encontrado.");
        const data = await res.json();
        setOrder(data);
        if (data.orcamentoStatus) {
          setActionDone(data.orcamentoStatus);
        }
      } catch (err: any) {
        setError(err?.message || "Erro ao carregar orçamento.");
      } finally {
        setLoading(false);
      }
    }
    loadOrder();
  }, [id]);

  const handleDecision = async (decision: "Aprovado" | "Rejeitado") => {
    if (!order) return;
    setSubmitting(true);
    setError(null);

    try {
      const res = await fetch(`/api/ordens-servico/${order.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          orcamentoStatus: decision,
          status: decision === "Aprovado" ? "concluida" : order.status,
        }),
      });

      if (!res.ok) {
        const body = await res.json().catch(() => null);
        throw new Error(body?.error || "Falha ao registrar resposta.");
      }

      setActionDone(decision);
    } catch (err: any) {
      setError(err?.message || "Erro ao atualizar estado.");
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-slate-950 text-slate-100 flex items-center justify-center">
        <div className="flex items-center gap-2 text-teal-400">
          <Loader2 className="animate-spin" size={24} /> A carregar orçamento...
        </div>
      </div>
    );
  }

  if (error || !order) {
    return (
      <div className="min-h-screen bg-slate-950 text-slate-100 flex items-center justify-center p-6">
        <div className="max-w-md w-full bg-slate-900 border border-slate-800 rounded-2xl p-6 text-center space-y-4">
          <AlertCircle className="mx-auto text-rose-500" size={48} />
          <h1 className="text-lg font-bold text-white">Orçamento Indisponível</h1>
          <p className="text-sm text-slate-400">{error || "Não foi possível encontrar este orçamento."}</p>
        </div>
      </div>
    );
  }

  const pecas = Number(order.valorPecas || 0);
  const maoObra = Number(order.valorMaoObra || 0);
  const desconto = Number(order.valorDesconto || 0);
  const subtotal = Math.max(0, pecas + maoObra - desconto);
  const iva = order.isIsentoIva ? 0 : subtotal * 0.16;
  const total = subtotal + iva;

  const meta = order.metadados || {};
  const pagamentoStatus = meta.pagamentoStatus || "Pendente";

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 py-10 px-4">
      <div className="max-w-3xl mx-auto space-y-6">
        {/* Header */}
        <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <div>
            <div className="flex items-center gap-2 text-teal-400 font-bold text-sm mb-1">
              <ShieldCheck size={18} /> Orçamento de Inspeção / Serviço
            </div>
            <h1 className="text-2xl font-black text-white">Ordem #{order.numeroOrdem || order.id}</h1>
            <p className="text-xs text-slate-400 mt-1">Emitido por: {order.serviceStation?.nome || "Orey Técnica"}</p>
          </div>
          <div className="flex flex-col sm:flex-row items-start sm:items-center gap-2">
            <div className={`px-4 py-1.5 rounded-full text-xs font-bold border ${
              actionDone === "Aprovado" ? "bg-emerald-500/20 text-emerald-300 border-emerald-500/30" :
              actionDone === "Rejeitado" ? "bg-rose-500/20 text-rose-300 border-rose-500/30" :
              "bg-amber-500/20 text-amber-300 border-amber-500/30"
            }`}>
              Estado: {actionDone || "Pendente de Aprovação"}
            </div>
            <span className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold border ${PAGAMENTO_BADGE_CLASSES[pagamentoStatus] || PAGAMENTO_BADGE_CLASSES.Pendente}`}>
              <CreditCard size={12} /> Pagamento: {pagamentoStatus}
            </span>
          </div>
        </div>

        {/* Client & Equipment info */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <div className="bg-slate-900 border border-slate-800 rounded-2xl p-5 space-y-2">
            <div className="text-xs font-semibold text-slate-400 uppercase">Cliente</div>
            <div className="font-bold text-white text-base">{order.cliente?.nome || order.jangada?.owner || "Cliente Particular"}</div>
            <div className="text-xs text-slate-400">NIF: <span className="text-slate-200 font-mono">{order.cliente?.nif || "—"}</span></div>
            <div className="text-xs text-slate-400">Morada: <span className="text-slate-200">{order.cliente?.morada || "—"}</span></div>
          </div>

          <div className="bg-slate-900 border border-slate-800 rounded-2xl p-5 space-y-2">
            <div className="text-xs font-semibold text-slate-400 uppercase">Equipamento / Embarcação</div>
            <div className="font-bold text-white text-base">{order.jangada?.shipNameManual || "Embarcação Geral"}</div>
            <div className="text-xs text-slate-400">Jangada: <span className="text-slate-200">{order.jangada?.brand || ""} {order.jangada?.model || ""}</span></div>
            <div className="text-xs text-slate-400">Nº de Série: <span className="text-teal-300 font-mono">{order.jangada?.serial || "—"}</span></div>
          </div>
        </div>

        {/* Costs Table */}
        <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 space-y-4">
          <h2 className="text-sm font-bold uppercase tracking-wider text-teal-400">Detalhe de Custos</h2>
          <div className="border border-slate-800 rounded-xl overflow-hidden">
            <table className="w-full text-left text-sm">
              <thead>
                <tr className="bg-slate-800/80 text-xs font-semibold text-slate-300 uppercase">
                  <th className="p-3">Descrição</th>
                  <th className="p-3 text-center">Qtd</th>
                  <th className="p-3 text-right">Valor</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800 font-mono text-xs">
                <tr>
                  <td className="p-3 text-slate-200 font-sans">Mão-de-obra (serviços técnicos)</td>
                  <td className="p-3 text-center">1</td>
                  <td className="p-3 text-right font-bold">€ {maoObra.toFixed(2)}</td>
                </tr>
                <tr>
                  <td className="p-3 text-slate-200 font-sans">Peças e Materiais aplicados</td>
                  <td className="p-3 text-center">1</td>
                  <td className="p-3 text-right font-bold">€ {pecas.toFixed(2)}</td>
                </tr>
                {desconto > 0 && (
                  <tr className="text-rose-400">
                    <td className="p-3 font-sans">Desconto Comercial</td>
                    <td className="p-3 text-center">1</td>
                    <td className="p-3 text-right font-bold">- € {desconto.toFixed(2)}</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>

          <div className="bg-slate-950 p-4 rounded-xl border border-slate-800 flex flex-col items-end space-y-1.5 font-mono text-sm">
            <div className="flex justify-between w-64 text-slate-400 text-xs">
              <span>Subtotal:</span>
              <span>€ {subtotal.toFixed(2)}</span>
            </div>
            <div className="flex justify-between w-64 text-slate-400 text-xs">
              <span>IVA ({order.isIsentoIva ? "Isento" : "16%"}):</span>
              <span>€ {iva.toFixed(2)}</span>
            </div>
            <div className="flex justify-between w-64 text-teal-400 font-bold text-base pt-2 border-t border-slate-800">
              <span>TOTAL:</span>
              <span>€ {total.toFixed(2)}</span>
            </div>
          </div>
        </div>

        {/* Action Buttons */}
        <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 text-center space-y-4">
          <h2 className="text-sm font-bold text-slate-200">Deseja aprovar ou rejeitar este orçamento?</h2>
          <div className="flex flex-wrap justify-center gap-4">
            <button
              onClick={() => handleDecision("Aprovado")}
              disabled={submitting || actionDone === "Aprovado"}
              className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-500 text-white px-6 py-3 rounded-xl font-bold text-sm transition disabled:opacity-50 shadow-lg shadow-emerald-900/30"
            >
              {submitting ? <Loader2 className="animate-spin" size={16} /> : <CheckCircle2 size={18} />}
              {actionDone === "Aprovado" ? "Orçamento Aprovado ✓" : "Aprovar Orçamento"}
            </button>
            <button
              onClick={() => handleDecision("Rejeitado")}
              disabled={submitting || actionDone === "Rejeitado"}
              className="flex items-center gap-2 bg-rose-600 hover:bg-rose-500 text-white px-6 py-3 rounded-xl font-bold text-sm transition disabled:opacity-50 shadow-lg shadow-rose-900/30"
            >
              {submitting ? <Loader2 className="animate-spin" size={16} /> : <XCircle size={18} />}
              {actionDone === "Rejeitado" ? "Orçamento Rejeitado" : "Rejeitar Orçamento"}
            </button>
          </div>
          {actionDone && (
            <p className="text-xs text-emerald-400 pt-2 font-medium">
              A sua resposta foi registada com sucesso. Obrigado!
            </p>
          )}
        </div>
      </div>
    </div>
  );
}

