function configureCertificatePrintLayout(worksheet: ExcelJS.Worksheet) {
  worksheet.pageSetup = {
    paperSize: 9, // A4
    orientation: 'portrait',
    fitToPage: true,
    fitToHeight: 1,
    fitToWidth: 1,
    horizontalCentered: true,
