    margins: {
      left: 0.3,
      right: 0.3,
      top: 0.4,
      bottom: 0.4,
      header: 0.2,
      footer: 0.2,
    },
  };
}

export async function buildOreyCertificateArtifacts(input: OreyCertificateTemplateInput) {
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.readFile(TEMPLATE_PATH);

  const worksheet = workbook.getWorksheet('CERTIFICADO') || workbook.worksheets[0];
  if (!worksheet) {
    throw new Error('Folha CERTIFICADO não encontrada no template Orey.');
  }

  applyCertificateMerges(worksheet);
  fillTemplate(worksheet, input);

  // Pedido operacional: gerar o certificado Excel sem o logo da marca da jangada.
  // Mantemos os dados técnicos e layout original, apenas sem inserir imagem de marca.

  // Remove green fills from all cells
  worksheet.eachRow({ includeEmpty: true }, (row) => {
    row.eachCell({ includeEmpty: true }, (cell) => {
      if (isGreenLikeFill(cell.fill)) {
        cell.fill = { type: 'pattern', pattern: 'none' };
      }
    });
  });

  // Configure page setup for A4 printing
  configureCertificatePrintLayout(worksheet);

  const written = await workbook.xlsx.writeBuffer();
  const buffer = Buffer.isBuffer(written) ? written : Buffer.from(written as ArrayBuffer);
  const previewWorkbook = XLSX.read(buffer, { type: 'buffer', cellStyles: true });
  const previewSheet = previewWorkbook.Sheets[previewWorkbook.SheetNames[0]];
  const html = wrapPreviewHtml(XLSX.utils.sheet_to_html(previewSheet, { editable: false }));
  const certificateNumber = sanitizeFileNameSegment(input.certNumber, 'SEM-NUMERO');
  const shipName = sanitizeFileNameSegment(asString(input.shipName).toUpperCase(), 'SEM NAVIO');
  const fileName = `${certificateNumber} ${shipName}.xlsx`;

  return {
    buffer,
    html,
    fileName,
  };
}

export type PressureUnit = 'hpa' | 'inh2o' | 'inhg' | 'mbar';

export type ChamberAnalysis = {
  startRaw: number;
  endRaw: number;
  startMb: number;
  endMb: number;
  correctedEndMb: number;
  dropMb: number;
  percent: number;
  passes: boolean;
};

export type PressureCalculationResult = {
  tempDelta: number;
  baroDelta: number;
  correctionTempMb: number;
  correctionBaroMb: number;
  totalCorrectionMb: number;
  tempValid: boolean;
  supAnalysis: ChamberAnalysis | null;
  infAnalysis: ChamberAnalysis | null;
};

export function parsePressureValue(v: any): number {
  const val = parseFloat(String(v || "").replace(",", "."));
  return isNaN(val) ? NaN : val;
}

export function toMbar(val: number, unit: PressureUnit): number {
  if (isNaN(val)) return NaN;
  if (unit === "inhg") return val * 33.8638866667;
  if (unit === "inh2o") return val * 2.490889;
  return val;
}

export function fromMbar(val: number, unit: PressureUnit): number {
  if (isNaN(val)) return NaN;
  if (unit === "inhg") return val / 33.8638866667;
  if (unit === "inh2o") return val / 2.490889;
  return val;
}

export function analyzeChamber(
  startRaw: number,
  endRaw: number,
  unit: PressureUnit,
  totalCorrectionMb: number
): ChamberAnalysis | null {
  if (isNaN(startRaw) || isNaN(endRaw)) return null;

  const startMb = toMbar(startRaw, unit);
  const endMb = toMbar(endRaw, unit);

  const correctedEndMb = endMb + totalCorrectionMb;
  const dropMbRaw = startMb - correctedEndMb;
  const dropMb = Math.max(0, dropMbRaw);
  const percent = startMb > 0 ? (dropMb / startMb) * 100 : 0;
  const passes = percent <= 5;

  return { 
    startRaw, endRaw, startMb, endMb,
    correctedEndMb: fromMbar(correctedEndMb, unit), 
    dropMb: fromMbar(dropMb, unit), 
    percent, 
    passes 
  };
}

export function calculatePressureTest(
  tempInicio: any,
  tempFim: any,
  pressaoAtmInicio: any,
  pressaoAtmFim: any,
  camaraSupInicio: any,
  camaraSupFim: any,
  camaraInfInicio: any,
  camaraInfFim: any,
  unit: PressureUnit = 'hpa'
): PressureCalculationResult | null {
  const tIn = parsePressureValue(tempInicio);
  const tOut = parsePressureValue(tempFim);
  const pAtmIn = parsePressureValue(pressaoAtmInicio);
  const pAtmOut = parsePressureValue(pressaoAtmFim);

  if (isNaN(tIn) || isNaN(tOut) || isNaN(pAtmIn) || isNaN(pAtmOut)) {
    return null;
  }

  const tempDelta = tOut - tIn;
  const baroDelta = pAtmOut - pAtmIn;
  const correctionTempMb = -(tempDelta * 4);
  const correctionBaroMb = baroDelta;
  const totalCorrectionMb = correctionTempMb + correctionBaroMb;
  const tempValid = Math.abs(tempDelta) <= 3.5;

  const supIn = parsePressureValue(camaraSupInicio);
  const supOut = parsePressureValue(camaraSupFim);
  const infIn = parsePressureValue(camaraInfInicio);
  const infOut = parsePressureValue(camaraInfFim);

  const supAnalysis = analyzeChamber(supIn, supOut, unit, totalCorrectionMb);
  const infAnalysis = analyzeChamber(infIn, infOut, unit, totalCorrectionMb);

  return {
    tempDelta,
    baroDelta,
    correctionTempMb,
    correctionBaroMb,
    totalCorrectionMb,
    tempValid,
    supAnalysis,
    infAnalysis,
  };
}

export function formatPressureValue(value: number, unit: PressureUnit, decimals = 2): string {
  return `${value.toFixed(decimals)} ${unit.toUpperCase()}`;
}

export function formatPercentDrop(percent: number): string {
  return `${percent.toFixed(2)}%`;
}

import { PrismaClient } from "@prisma/client";
import { resolveRuntimeDatabaseUrl } from "@/lib/resolve-database-url";
import {
  syncClienteNumeroFromExterno,
  extractNumeroClienteExterno,
} from "@/lib/sync-cliente-numero";

if (process.env.NODE_ENV === "production" && !process.env.PRISMA_DISABLE_WARNINGS) {
  process.env.PRISMA_DISABLE_WARNINGS = "1";
}

type GlobalWithPrisma = typeof globalThis & {
  prisma?: PrismaClient;
  prismaConnectPromise?: Promise<void>;
};
const globalForPrisma = globalThis as GlobalWithPrisma;

const { connectionString: resolvedUrl } = resolveRuntimeDatabaseUrl();
const activeUrl = resolvedUrl || process.env.DATABASE_URL || "";
const isSQLite = activeUrl.startsWith("file:");

function stripInsensitiveMode(obj: any): any {
  if (obj === null || typeof obj !== "object") {
    return obj;
  }
  if (Array.isArray(obj)) {
    return obj.map(stripInsensitiveMode);
  }
  if (obj instanceof Date) {
    return obj;
  }
  const cleaned: any = {};
  for (const key of Object.keys(obj)) {
    if (key === "mode" && (obj[key] === "insensitive" || obj[key] === "default")) {
      continue;
    }
    cleaned[key] = stripInsensitiveMode(obj[key]);
  }
  return cleaned;
}

function wrapWithSQLiteProxy(rawClient: PrismaClient): PrismaClient {
  return new Proxy(rawClient as object, {
    get(target: any, prop: string | symbol) {
      const origValue = target[prop];
      if (origValue === null || origValue === undefined) {
        return origValue;
      }

      // Interceptar os delegados dos modelos (como prisma.navio, prisma.inspecao, etc.)
      if (typeof origValue === "object" && typeof prop === "string" && !prop.startsWith("$")) {
        return new Proxy(origValue, {
          get(modelTarget: any, modelProp: string | symbol) {
            const origMethod = modelTarget[modelProp];
            if (typeof origMethod === "function") {
              return function (...args: any[]) {
                const cleanedArgs = args.map(stripInsensitiveMode);
                return origMethod.apply(modelTarget, cleanedArgs);
              };
            }
            return origMethod;
          },
        });
      }

      if (typeof origValue === "function") {
        return origValue.bind(target);
      }

      return origValue;
    },
  }) as unknown as PrismaClient;
}

function attachClienteNumeroSync(rawClient: PrismaClient): PrismaClient {
  async function afterWrite(row: any, dataClienteId?: any): Promise<any> {
    try {
      if (row && typeof row === "object") {
        const externo = extractNumeroClienteExterno(row["metadados"]);
        const clienteId = row["clienteId"] ?? dataClienteId;
        if (externo && clienteId) {
          await syncClienteNumeroFromExterno(rawClient, clienteId, externo);
        }
      }
    } catch {
      // não deve interromper a escrita principal
    }
    return row;
  }

  const extended = rawClient.$extends({
    query: {
      ordemServico: {
        async create({ args, query }: any) {
          return afterWrite(await query(args), args?.data?.clienteId);
        },
        async update({ args, query }: any) {
          return afterWrite(await query(args), args?.data?.clienteId);
        },
        async upsert({ args, query }: any) {
          return afterWrite(await query(args), args?.data?.clienteId);
        },
      },
      fatura: {
        async create({ args, query }: any) {
          return afterWrite(await query(args), args?.data?.clienteId);
        },
        async update({ args, query }: any) {
          return afterWrite(await query(args), args?.data?.clienteId);
        },
        async upsert({ args, query }: any) {
          return afterWrite(await query(args), args?.data?.clienteId);
        },
      },
    },
  });
  return extended as unknown as PrismaClient;
}

function createPrismaClient(): PrismaClient {
  const client = new PrismaClient({
    log: process.env.NODE_ENV === "production" ? [] : ["error"],
    datasources: {
      db: {
        url: activeUrl,
      },
    },
  }) as unknown as PrismaClient;
  return attachClienteNumeroSync(client);
}

function getPrismaSingleton(): PrismaClient {
  if (globalForPrisma.prisma) {
    return globalForPrisma.prisma;
  }

  const rawClient = createPrismaClient();
  const client = isSQLite ? wrapWithSQLiteProxy(rawClient) : rawClient;
  globalForPrisma.prisma = client;
  return client;
}

// Singleton global para evitar múltiplos motores Prisma no Next.js
const prisma = getPrismaSingleton();

export async function ensurePrismaConnected(): Promise<PrismaClient> {
  if (globalForPrisma.prismaConnectPromise) {
    await globalForPrisma.prismaConnectPromise;
  } else if (globalForPrisma.prisma) {
    await globalForPrisma.prisma.$connect();
  }
  return globalForPrisma.prisma ?? prisma;
}

