            }`}>
              {scanMessage.text}
              {suggestedReplacementFieldName && pendingReplacementFieldName && (
                <button
                  onClick={applySuggestedReplacementTarget}
                  className="ml-3 rounded-lg bg-white/20 px-3 py-1 hover:bg-white/30"
                >
                  Usar sugest�o
                </button>
              )}
            </div>
          )}
        </div>
      )}

      {/* Main card � one item at a time */}
      <div className="flex-1 flex flex-col items-center justify-center px-6 py-8 overflow-y-auto">
        <div className="w-full max-w-sm space-y-5">

          {/* Section badge */}
          <div className="flex items-center justify-center">
            <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 bg-slate-100 px-3 py-1 rounded-full">
              {(current as any).sectionTitle} � {itemInSection}/{sectionTotal}
            </span>
          </div>

          {/* Item name */}
          <div className="text-center space-y-1.5">
            <h2 className="text-[1.6rem] font-black text-slate-900 leading-tight">{current.label}</h2>
            {current.englishLabel && (
              <p className="text-sm text-slate-400 italic font-serif">{current.englishLabel}</p>
            )}
            {current.packItem?.quantityLabel && (
              <span className="inline-block text-xs font-bold text-slate-500 bg-slate-50 border border-slate-200 rounded-lg px-3 py-1 mt-1">
                Requisito: {current.packItem.quantityLabel}
              </span>
            )}
          </div>

          {/* Checkbox � OK / Falha */}
          {isCheckbox && (
            <div className="flex gap-3 pt-2">
              <button
                onClick={() => { handleFieldChange(current.name, true); setTimeout(goNext, 220); }}
                className={`flex-1 py-6 rounded-2xl text-lg font-black uppercase tracking-wide transition-all active:scale-95 ${
                  currentValue === true
                    ? "bg-emerald-500 text-white shadow-xl shadow-emerald-500/25"
                    : "bg-emerald-50 text-emerald-700 border-2 border-emerald-200 hover:bg-emerald-100"
                }`}
              >
                ? OK
              </button>
              <button
                onClick={() => { handleFieldChange(current.name, false); startReplacementScan(current.name); }}
                className={`flex-1 py-6 rounded-2xl text-lg font-black uppercase tracking-wide transition-all active:scale-95 ${
                  currentValue === false
                    ? "bg-rose-500 text-white shadow-xl shadow-rose-500/25"
                    : "bg-rose-50 text-rose-700 border-2 border-rose-200 hover:bg-rose-100"
                }`}
              >
                ? Falha
              </button>
            </div>
          )}

          {/* Date field */}
          {isDate && (
            <div className="space-y-3">
              <input
                type="date"
                value={String(values[current.name] ?? "")}
                onChange={(e) => handleFieldChange(current.name, e.target.value)}
                className="w-full rounded-xl border-2 border-slate-200 px-4 py-3 text-center text-base font-medium focus:border-sky-400 outline-none"
                autoFocus
              />
              <button
                onClick={goNext}
                disabled={!values[current.name]}
                className="w-full py-4 rounded-2xl bg-sky-600 text-white font-black uppercase tracking-wide text-sm disabled:opacity-30 active:scale-95 transition-all"
              >
                Confirmar ?
              </button>
            </div>
          )}

          {/* Text / number field */}
          {!isCheckbox && !isDate && (
            <div className="space-y-3">
              <input
                type={current.type === "number" ? "number" : "text"}
                value={String(values[current.name] ?? "")}
                onChange={(e) => handleFieldChange(current.name, e.target.value)}
                className="w-full rounded-xl border-2 border-slate-200 px-4 py-3 text-base focus:border-sky-400 outline-none"
                autoFocus
              />
              <button
                onClick={goNext}
                className="w-full py-4 rounded-2xl bg-sky-600 text-white font-black uppercase tracking-wide text-sm active:scale-95 transition-all"
              >
                Confirmar ?
              </button>
            </div>
          )}

          {/* Skip */}
          <button
            onClick={goNext}
            className="w-full text-xs text-slate-300 hover:text-slate-500 py-1 transition-colors"
          >
            Saltar ?
          </button>

          {/* Dot navigation � sliding window */}
          <div className="flex items-center justify-center gap-1.5 pt-2">
            {allFields.slice(Math.max(0, currentIndex - 4), currentIndex + 6).map((f, dotIdx) => {
              const realIdx = Math.max(0, currentIndex - 4) + dotIdx;
              const isCurrent = realIdx === currentIndex;
              const val = values[f.name];
              return (
                <button
                  key={f.name}
                  onClick={() => setCurrentIndex(realIdx)}
                  className={`rounded-full transition-all ${
                    isCurrent ? "w-6 h-3 bg-sky-500" :
                    val === true ? "w-2.5 h-2.5 bg-emerald-400" :
                    val === false ? "w-2.5 h-2.5 bg-rose-400" :
                    val !== undefined && val !== "" ? "w-2.5 h-2.5 bg-slate-400" :
                    "w-2.5 h-2.5 bg-slate-200 hover:bg-slate-300"
                  }`}
                />
              );
            })}
          </div>
          <p className="text-center text-[10px] text-slate-400">{currentIndex + 1} / {total}</p>

        </div>
      </div>

      {/* Footer */}
      <div className="flex items-center justify-between px-4 py-3 border-t border-slate-100 bg-white shrink-0">
        <button
          onClick={goPrev}
          disabled={currentIndex === 0}
          className="flex items-center gap-1 px-4 py-2.5 rounded-xl text-sm font-bold text-slate-500 hover:bg-slate-100 disabled:opacity-20 transition-all"
        >
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
          </svg>
          Anterior
        </button>
        <button
          onClick={currentIndex >= total - 1 ? () => onSave(values) : goNext}
          className="flex items-center gap-1 px-6 py-2.5 rounded-xl bg-slate-900 text-white text-sm font-black uppercase tracking-wide hover:bg-slate-700 active:scale-95 transition-all"
        >
          {currentIndex >= total - 1 ? "Concluir" : "Pr�ximo"}
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
          </svg>
        </button>
      </div>

    </div>
  );
}

"use client";
import React, { useState } from "react";
import { uuidv4 } from "../utils/uuid";


// Gestão de Clientes
export default function Clients() {
  const [search, setSearch] = useState("");
  const [showModal, setShowModal] = useState(false);
  const [quickClient, setQuickClient] = useState({ name: "", email: "", phone: "" });
  const [clients, setClients] = useState(() => {
    try {
      const stored = localStorage.getItem("clients");
      if (stored && JSON.parse(stored).length > 0) {
        return JSON.parse(stored);
      }
      // Seed automático: operadores e armadores de pesca
      // Importa navios e armadores
      // (Ajuste os imports conforme necessário)
      let navios: any[] = [];
      try {
        navios = [
          ...(require('../database/navios_sao_miguel').naviosSaoMiguel || []),
          ...(require('../database/navios_sao_miguel').naviosCorvo || []),
          ...(require('../database/navios_sao_miguel').naviosFlores || []),
          ...(require('../database/navios_sao_miguel').naviosTerceira || []),
          ...(require('../database/navios_sao_miguel').naviosFaial || []),
          ...(require('../database/navios_sao_miguel').naviosPico || []),
          ...(require('../database/navios_sao_miguel').naviosSaoJorge || []),
          ...(require('../database/navios_sao_miguel').naviosGraciosa || []),
          ...(require('../database/navios_sao_miguel').naviosSantaMaria || [])
        ];
      } catch {}
      // Extrai proprietários dos navios
      const owners = Array.from(new Set(navios.map((n: any) => n.proprietario).filter(Boolean)));
      // Armadores de pesca (exemplo, ajuste para importar de fonte real)
      const armadores = [
        "ABEL VITORINO SEQUEIRA DE MELO",
        "ALBERTO FERNANDO MONIZ DA CAMARA ROSA",
        "ALEXANDRE DOS SANTOS PACHECO",
        "ALEXANDRINO DE ASCENSÃO MENDES NARCISO",
        "ALVARO MIGUEL DA COSTA CABRAL",
        "AMARO RUI MACHADO SOARES",
        "ANA MARIA CABRAL VIEIRA",
        "ANDRÉ AGUIAR ALMEIDA",
        "ANTÓNIO ALBERTO PONTE DOS SANTOS ARRAIAL",
        "ANTÓNIO FERNANDO BEZERRA FLORES",
        "ANTÓNIO JORGE DA SILVA",
        "ANTÓNIO MANUEL CABRAL ANDRADE",
        "ANTÓNIO MANUEL VALENTE BAGARRÃO",
        "ANTÓNIO MANUEL VIEGAS DE AZEVEDO",
        "ANTÓNIO SALVADOR FERREIRA VIEIRA"
      ];
      // Monta lista única de clientes
      const allClients = [
        ...owners.map(name => ({ id: uuidv4(), name })),
        ...armadores.map(name => ({ id: uuidv4(), name }))
      ];
      localStorage.setItem("clients", JSON.stringify(allClients));
      return allClients;
    } catch { return []; }
  });
  const [auditLog, setAuditLog] = useState(() => {
    try {
      return JSON.parse(localStorage.getItem("auditClients") || "[]");
    } catch { return []; }
  });
  

  const handleQuickClientChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setQuickClient({ ...quickClient, [e.target.name]: e.target.value });
  };

  const handleQuickClientSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!quickClient.name) return;
    const newClient = {
      id: uuidv4(),
      ...quickClient,
    };
    const updatedClients = [...clients, newClient];
    setClients(updatedClients);
    localStorage.setItem("clients", JSON.stringify(updatedClients));
    addAudit("Cadastro rápido", newClient);
    setShowModal(false);
    setQuickClient({ name: "", email: "", phone: "" });
  };

  const addAudit = (action: string, client: any) => {
    const entry = {
      timestamp: new Date().toISOString(),
      action,
      client,
    };
    const updatedLog = [entry, ...auditLog];
    setAuditLog(updatedLog);
    localStorage.setItem("auditClients", JSON.stringify(updatedLog));
  };

  // Funções de backup/restauração
  const handleBackup = () => {
    const data = {
      clients,
      auditLog,
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `backup_clientes_${Date.now()}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleRestore = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const data = JSON.parse(ev.target?.result as string);
        if (data.clients) {
          setClients(data.clients);
          localStorage.setItem("clients", JSON.stringify(data.clients));
        }
        if (data.auditLog) {
          setAuditLog(data.auditLog);
          localStorage.setItem("auditClients", JSON.stringify(data.auditLog));
        }
      } catch {}
    };
    reader.readAsText(file);
  };

  // Função para importar CSV
  const handleImportCSV = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const XLSX = await import("xlsx");
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      const data = XLSX.read(ev.target?.result, { type: "binary" });
      const sheet = data.Sheets[data.SheetNames[0]];
      const rows = XLSX.utils.sheet_to_json(sheet);
      const importedClients = rows.map((r: any) => ({
        id: uuidv4(),
        name: r.name || r.Nome || "",
        email: r.email || r.Email || "",
        phone: r.phone || r.Telefone || "",
      }));
      const updatedClients = [...clients, ...importedClients];
      setClients(updatedClients);
      localStorage.setItem("clients", JSON.stringify(updatedClients));
    };
    reader.readAsBinaryString(file);
  };

  return (
    <div className="max-w-2xl mx-auto px-2 sm:px-4">
      <h2 className="text-2xl font-bold mb-4">Lista de Clientes</h2>
      <button
        className="bg-blue-600 text-white px-4 py-2 rounded mb-4"
        onClick={() => setShowModal(true)}
      >
        Cadastro rápido
      </button>
      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-40 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded shadow-lg w-full max-w-md">
            <h3 className="text-lg font-bold mb-4">Cadastro rápido de Cliente</h3>
            <form onSubmit={handleQuickClientSubmit} className="space-y-3">
              <input
                name="name"
                value={quickClient.name}
                onChange={handleQuickClientChange}
                placeholder="Nome do cliente"
                className="border rounded px-2 py-1 w-full"
                required
              />
              <input
                name="email"
                value={quickClient.email}
                onChange={handleQuickClientChange}
                placeholder="Email (opcional)"
                className="border rounded px-2 py-1 w-full"
              />
              <input
                name="phone"
                value={quickClient.phone}
                onChange={handleQuickClientChange}
                placeholder="Telefone (opcional)"
                className="border rounded px-2 py-1 w-full"
              />
              <div className="flex gap-2 justify-end">
                <button type="button" className="px-4 py-2 bg-gray-300 rounded" onClick={() => setShowModal(false)}>Cancelar</button>
                <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded">Salvar</button>
              </div>
            </form>
          </div>
        </div>
      )}
      <div className="mb-4">
        <input
          type="text"
          value={search}
          onChange={e => setSearch(e.target.value)}
          placeholder="Buscar nome, email, telefone..."
          className="border rounded px-2 py-1 w-full"
        />
      </div>
      <h3 className="text-xl font-semibold mb-2">Clientes</h3>
      <div className="overflow-x-auto">
        <table className="min-w-full bg-white rounded shadow mb-2 text-xs sm:text-sm">
          <thead>
            <tr className="bg-blue-100">
              <th className="p-2 whitespace-nowrap">Nome</th>
              <th className="p-2 whitespace-nowrap">Email</th>
              <th className="p-2 whitespace-nowrap">Telefone</th>
            </tr>
          </thead>
          <tbody>
            {clients.filter((c: any) =>
              !search ||
              c.name.toLowerCase().includes(search.toLowerCase()) ||
              (c.email && c.email.toLowerCase().includes(search.toLowerCase())) ||
              (c.phone && c.phone.toLowerCase().includes(search.toLowerCase()))
            ).map((c: any) => (
              <tr key={c.id} className="border-t align-top">
                <td className="p-2 whitespace-nowrap">{c.name}</td>
                <td className="p-2 whitespace-nowrap">{c.email}</td>
                <td className="p-2 whitespace-nowrap">{c.phone}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="mt-8">
        <h3 className="text-lg font-bold mb-2">Histórico de alterações</h3>
        <ul className="bg-gray-50 rounded p-2 max-h-48 overflow-auto text-xs">
          {auditLog.map((entry: any, idx: number) => (
            <li key={idx} className="mb-1">
              <span className="font-semibold">{entry.action}</span> - {entry.client.name} em {new Date(entry.timestamp).toLocaleString()}
            </li>
          ))}
          {auditLog.length === 0 && <li className="text-gray-400">Nenhuma alteração registrada.</li>}
        </ul>
      </div>
      <div className="flex gap-2 mb-4">
        <button className="bg-green-600 text-white px-3 py-1 rounded" onClick={handleBackup}>Backup</button>
        <label className="bg-yellow-500 text-white px-3 py-1 rounded cursor-pointer">
          Restaurar
          <input type="file" accept="application/json" className="hidden" onChange={handleRestore} />
        </label>
      </div>
      <div className="mb-4">
        <label className="bg-blue-600 text-white px-3 py-1 rounded cursor-pointer">
          Importar CSV
          <input type="file" accept=".csv,.xlsx" className="hidden" onChange={handleImportCSV} />
        </label>
      </div>
    </div>
  );
}

"use client";
import React, { useState, useEffect } from "react";
import WizardRouter from "./WizardRouter";
import { CheckCircle, Info, Stethoscope, AlertTriangle, Flag, ArrowLeft } from "lucide-react";
import Link from "next/link";
import { useColeteWizardStore } from "./store/useColeteWizardStore";

const WIZARD_STEPS = [
  { id: 1, title: "Identificação", icon: Info },
  { id: 2, title: "Inspeção Visual", icon: Stethoscope },
  { id: 3, title: "Componentes", icon: AlertTriangle },
  { id: 4, title: "Testes", icon: Flag },
  { id: 5, title: "Resumo e Emissão", icon: CheckCircle },
];

function useStepValidation(): Record<number, boolean> {
  const { inspectionData } = useColeteWizardStore();

  const isStep1Valid = Boolean(inspectionData.serial);
  const isStep2Valid = Boolean(inspectionData.mecanismoInflacao);
  const isStep3Valid = true;
  const isStep4Valid = Boolean(inspectionData.testePressao || inspectionData.testeInsuflacao);

  return {
    1: isStep1Valid,
    2: isStep2Valid,
    3: isStep3Valid,
    4: isStep4Valid,
    5: true,
  };
}

export default function ColeteWizard() {
  const [step, setStep] = useState(1);
  const [highestReached, setHighestReached] = useState(1);
  const { coleteId, isDirty } = useColeteWizardStore();
  const validation = useStepValidation();

  useEffect(() => {
    const handler = (e: BeforeUnloadEvent) => {
      if (isDirty) {
        e.preventDefault();
      }
    };
    window.addEventListener("beforeunload", handler);
    return () => window.removeEventListener("beforeunload", handler);
  }, [isDirty]);

  const handleStepChange = (nextStep: number) => {
    if (nextStep > step && !validation[step]) return;
    if (nextStep > highestReached) {
      setHighestReached(nextStep);
    }
    setStep(nextStep);
  };

  return (
    <div className="text-slate-800 dark:text-slate-200">
      <div className="flex flex-col lg:flex-row gap-8">
        {/* Sidebar / Progress */}
        <div className="w-full lg:w-72 shrink-0">
          <div className="bg-white/70 dark:bg-slate-800/70 backdrop-blur-lg rounded-2xl p-6 shadow-md border border-slate-200/50 sticky top-8">
            <h3 className="font-bold text-slate-800 dark:text-slate-100 mb-6 uppercase tracking-wider text-xs">Passos da Inspeção</h3>
            <div className="space-y-2">
              {WIZARD_STEPS.map((s) => {
                const Icon = s.icon;
                const isActive = s.id === step;
                const isPast = s.id < step;
                const canClick = s.id <= highestReached && (s.id === step || validation[step - 1] || isPast);

                return (
                  <button
                    key={s.id}
                    disabled={!canClick}
                    onClick={() => handleStepChange(s.id)}
                    className={`w-full flex items-center gap-4 p-3 rounded-xl transition-all duration-200 text-left border ${
                      isActive
                        ? "bg-indigo-50/80 dark:bg-indigo-950/40 border-indigo-100 dark:border-indigo-900 shadow-sm"
                        : isPast
                          ? "hover:bg-slate-50/50 dark:hover:bg-slate-700/30 border-transparent"
                          : "opacity-40 cursor-not-allowed border-transparent"
                    }`}
                  >
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 border-2 transition-all ${
                      isActive
                        ? "bg-indigo-650 border-indigo-600 text-white shadow-md"
                        : isPast
                          ? "bg-emerald-500 border-emerald-500 text-white"
                          : "bg-slate-100 dark:bg-slate-700 border-slate-200 dark:border-slate-600 text-slate-400 dark:text-slate-500"
                    }`}>
                      {isPast ? <CheckCircle size={18} /> : <Icon size={18} />}
                    </div>
                    <div>
                      <p className={`text-[10px] font-bold uppercase tracking-wider ${isActive ? "text-indigo-600 dark:text-indigo-400" : isPast ? "text-emerald-600 dark:text-emerald-400" : "text-slate-400"}`}>
                        Passo {s.id}
                      </p>
                      <p className={`font-bold text-sm ${isActive ? "text-slate-900 dark:text-slate-100" : "text-slate-600 dark:text-slate-400"}`}>
                        {s.title}
                      </p>
                    </div>
                    {isPast && !isActive && (
                      <div className="ml-auto">
                        {!validation[s.id] && (
                          <span className="w-2 h-2 rounded-full bg-amber-400 block" />
                        )}
                      </div>
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        {/* Main Content Area */}
        <div className="flex-1 bg-white/70 dark:bg-slate-800/70 backdrop-blur-lg rounded-2xl p-6 lg:p-8 shadow-md border border-slate-200/50">
          <WizardRouter step={step} setStep={handleStepChange} />
        </div>
      </div>
    </div>
  );
}

"use client";
import React, { useEffect, useState } from "react";
import { useColeteWizardStore } from "./store/useColeteWizardStore";
import ColeteWizard from "./ColeteWizard";
import { Loader2 } from "lucide-react";

export default function ColeteWizardLoader({ coleteId }: { coleteId: number }) {
  const { setColeteId, setGlobalStock, setVerificacoes, setInspectionData, reset } = useColeteWizardStore();
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function loadData() {
      try {
        setLoading(true);
        reset();
        
        // 1. Carrega dados do Colete + Stock Global
        const coleteRes = await fetch(`/api/coletes/${coleteId}?includeStock=true`);
        if (!coleteRes.ok) throw new Error("Colete não encontrado");
        const coleteData = await coleteRes.json();
        
        setColeteId(coleteData.id);
        if (coleteData.verificacoes) {
          setVerificacoes(coleteData.verificacoes);
        }
        if (coleteData.globalStock) {
          setGlobalStock(coleteData.globalStock);
        }

        // 2. Procura se já existe um Rascunho para este colete
        const inspRes = await fetch(`/api/inspecoes?coleteId=${coleteId}`);
        let draftFound = false;
        
        if (inspRes.ok) {
          const inspecoes = await inspRes.json();
          // Assumimos que a mais recente (primeira da lista) pode ser o draft
          const draft = inspecoes.find((i: any) => i.status === "Draft" || i.status === "Rascunho");
          
          if (draft) {
            draftFound = true;
            useColeteWizardStore.getState().setInspectionId(draft.id);
            
            setInspectionData({
              brand: coleteData.marca || "",
              model: coleteData.modelo || "",
              serial: coleteData.serial || "",
              shipName: draft.navioNome || coleteData.navio?.nome || "",
              shipId: draft.navioId || coleteData.shipId || null,
              dataInspecao: draft.dataInspecao || new Date().toISOString().slice(0, 10),
              dataProxInspecao: draft.dataProxInspecao || "",
              temLuz: coleteData.temLuz === false ? false : true,

              testePressao: coleteData.testePressao || "",
              testeInsuflacao: coleteData.testeInsuflacao || "",
              testeVazamento: coleteData.testeVazamento || "",
            });
          }
        }
        
        if (!draftFound) {
          // Nova inspeção
          setInspectionData({
            brand: coleteData.marca || "",
            model: coleteData.modelo || "",
            serial: coleteData.serial || "",
            shipName: coleteData.navio?.nome || "",
            shipId: coleteData.shipId || null,
            dataInspecao: new Date().toISOString().slice(0, 10),
            dataProxInspecao: "",
            temLuz: coleteData.temLuz === false ? false : true,

            testePressao: coleteData.testePressao || "",
            testeInsuflacao: coleteData.testeInsuflacao || "",
            testeVazamento: coleteData.testeVazamento || "",
          });
        }
        
      } catch (err) {
        console.error("Erro a carregar colete:", err);
      } finally {
        setLoading(false);
      }
    }
    loadData();
  }, [coleteId]);

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center py-20">
        <Loader2 className="animate-spin text-indigo-500 mb-4" size={48} />
        <p className="text-slate-500 font-medium">A carregar dados do Colete e Stock...</p>
      </div>
    );
  }

  return <ColeteWizard />;
}

"use client";
import React, { useEffect, useState } from 'react';
import { useColeteWizardStore } from './store/useColeteWizardStore';

export default function Step1_DadosGerais() {
  const { inspectionData, setInspectionData } = useColeteWizardStore();
  const [catalogOptions, setCatalogOptions] = useState<any[]>([]);

  useEffect(() => {
    fetch('/api/coletes/catalog-options')
      .then(res => res.json())
      .then(data => {
        if (data && data.options) {
          setCatalogOptions(data.options);
        }
      })
      .catch(err => console.error("Erro ao carregar catálogo:", err));
  }, []);

  const handleChange = (field: string, value: any) => {
    setInspectionData({ [field]: value });
  };

  const marcas = Array.from(new Set(catalogOptions.map(o => o.marca).filter(Boolean))).sort();
  const modelosFiltered = catalogOptions
    .filter(o => !inspectionData.marca || o.marca.toUpperCase() === String(inspectionData.marca).toUpperCase())
    .map(o => o.modelo)
    .filter(Boolean);
  const modelos = Array.from(new Set(modelosFiltered)).sort();

  return (
    <div className="space-y-8 animate-in fade-in duration-300">
      <div>
        <h2 className="text-2xl font-bold text-slate-800">1. Identificação do Colete</h2>
        <p className="text-slate-600 mt-1">Registe os dados identificativos do colete e as suas características principais.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Serial */}
        <div className="space-y-2">
          <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Nº Série</label>
          <input 
            type="text" 
            className="w-full border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white transition-colors"
            placeholder="Ex: LALIZAS-123"
            value={inspectionData.serial || ''}
            onChange={(e) => handleChange('serial', e.target.value)}
          />
        </div>

        {/* Marca */}
        <div className="space-y-2">
          <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Marca</label>
          <input 
            list="marcas-list"
            type="text" 
            className="w-full border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white transition-colors"
            placeholder="Ex: LALIZAS"
            value={inspectionData.marca || ''}
            onChange={(e) => handleChange('marca', e.target.value)}
          />
          <datalist id="marcas-list">
            {marcas.map(m => <option key={m} value={m as string} />)}
          </datalist>
        </div>

        {/* Modelo */}
        <div className="space-y-2">
          <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Modelo</label>
          <input 
            list="modelos-list"
            type="text" 
            className="w-full border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white transition-colors"
            placeholder="Ex: Sigma 150N"
            value={inspectionData.modelo || ''}
            onChange={(e) => handleChange('modelo', e.target.value)}
          />
          <datalist id="modelos-list">
            {modelos.map(m => <option key={m} value={m as string} />)}
          </datalist>
        </div>

        {/* Tamanho */}
        <div className="space-y-2">
          <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Tamanho</label>
          <input 
            type="text" 
            className="w-full border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white transition-colors"
            placeholder="Ex: Adulto universal"
            value={inspectionData.tamanho || ''}
            onChange={(e) => handleChange('tamanho', e.target.value)}
          />
        </div>

        {/* Navio associado */}
        <div className="space-y-2">
          <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Navio (ID)</label>
          <input 
            type="number" 
            className="w-full border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white transition-colors"
            placeholder="ID do navio associado"
            value={inspectionData.shipId || ''}
            onChange={(e) => handleChange('shipId', e.target.value ? parseInt(e.target.value) : null)}
          />
        </div>
      </div>

      <hr className="border-slate-200 my-8" />

      <div>
        <h3 className="text-lg font-bold text-slate-800 mb-4">Dados da Inspeção e Certificação</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

          {/* Nome do Inspetor */}
          <div className="space-y-2">
            <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Inspetor</label>
            <input 
              type="text" 
              className="w-full border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white transition-colors"
              placeholder="Nome do técnico responsável"
              value={inspectionData.inspectorNome || ''}
              onChange={(e) => handleChange('inspectorNome', e.target.value)}
