        >
          Próximo Passo <ChevronRight size={18} />
        </button>
      </div>
    </div>
  );
}

"use client";
import React from "react";
import { useColeteWizardStore } from "./store/useColeteWizardStore";
import { ArrowLeft, ChevronRight, CheckCircle2, XCircle, AlertCircle, Info } from "lucide-react";

type Props = {
  onNext: () => void;
  onPrev: () => void;
};

const VISUAL_CHECKS = [
  { key: "tecidoExterior", label: "Tecido Exterior", desc: "Verificar cortes, desgaste ou descoloração." },
  { key: "colagens", label: "Costuras e Colagens", desc: "Integridade das uniões." },
  { key: "fitasReflectoras", label: "Fitas Refletoras", desc: "Aderência e refletividade." },
  { key: "zataosVelcro", label: "Fechos e Velcros", desc: "Funcionamento correto." },
  { key: "sistemaInflacao", label: "Sistema de Insuflação", desc: "Estado geral do atuador." },
  { key: "camaras", label: "Câmaras-de-ar (Bladders)", desc: "Desgaste ou danos na câmara interna." },
  { key: "tuboInflador", label: "Tubo de Insuflação Oral", desc: "Válvula e bocal." },
];

export default function Step2_Inspecao({ onNext, onPrev }: Props) {
  const { inspectionData, setInspectionData } = useColeteWizardStore();

  const handleSetCheck = (key: string, value: string) => {
    setInspectionData({ [key]: value });
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-300">
      <div>
        <h2 className="text-2xl font-bold text-slate-800">2. Inspeção Visual</h2>
        <p className="text-slate-600 mt-1">Verificação detalhada da integridade física do colete salva-vidas.</p>
      </div>

      <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
        <div className="grid grid-cols-12 gap-4 bg-slate-50 px-6 py-4 border-b border-slate-200 text-xs font-bold text-slate-500 uppercase tracking-wider">
          <div className="col-span-12 md:col-span-5">Ponto de Verificação</div>
          <div className="col-span-12 md:col-span-7">Estado</div>
        </div>

        <div className="divide-y divide-slate-100">
          {VISUAL_CHECKS.map((check) => {
            const currentValue = (inspectionData as any)[check.key];
            return (
              <div key={check.key} className="grid grid-cols-12 gap-4 px-6 py-4 items-center hover:bg-slate-50/50 transition-colors">
                <div className="col-span-12 md:col-span-5">
                  <p className="font-bold text-slate-800">{check.label}</p>
                  <p className="text-xs text-slate-500 mt-0.5">{check.desc}</p>
                </div>
                <div className="col-span-12 md:col-span-7">
                  <div className="flex flex-wrap gap-2">
                    <button
                      onClick={() => handleSetCheck(check.key, 'OK')}
                      className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-bold transition-colors ${
                        currentValue === 'OK'
                          ? 'bg-emerald-100 text-emerald-800 border border-emerald-200'
                          : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'
                      }`}
                    >
                      <CheckCircle2 size={16} /> Bom (OK)
                    </button>
                    <button
                      onClick={() => handleSetCheck(check.key, 'F')}
                      className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-bold transition-colors ${
                        currentValue === 'F'
                          ? 'bg-amber-100 text-amber-800 border border-amber-200'
                          : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'
                      }`}
                    >
                      <AlertCircle size={16} /> Falhou (F)
                    </button>
                    <button
                      onClick={() => handleSetCheck(check.key, 'R')}
                      className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-bold transition-colors ${
                        currentValue === 'R'
                          ? 'bg-blue-100 text-blue-800 border border-blue-200'
                          : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'
                      }`}
                    >
                      <Info size={16} /> Reparado (R)
                    </button>
                    <button
                      onClick={() => handleSetCheck(check.key, 'N/A')}
                      className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-bold transition-colors ${
                        currentValue === 'N/A'
                          ? 'bg-slate-200 text-slate-800 border border-slate-300'
                          : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'
                      }`}
                    >
                      <XCircle size={16} /> N/A
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Mecanismo */}
      <div className="bg-white border border-slate-200 rounded-2xl p-6 shadow-sm">
        <h3 className="text-sm font-bold text-slate-800 mb-4 uppercase tracking-wider">
          Tipo de Mecanismo de Insuflação
        </h3>
        <select
          value={inspectionData.mecanismoInflacao}
          onChange={(e) => setInspectionData({ mecanismoInflacao: e.target.value })}
          className="w-full md:w-1/2 border border-slate-200 rounded-xl px-4 py-2.5 bg-white text-slate-800 focus:ring-2 focus:ring-indigo-100 transition-colors"
        >
          <option value="">Selecionar mecanismo...</option>
          <option value="HR">Halkey Roberts (HR)</option>
          <option value="HM">Hammar (HM)</option>
          <option value="SEC">Secumar (SEC)</option>
          <option value="LZ_JS1">Lalizas JS1 Automático</option>
          <option value="LZ_MAN">Lalizas Manual Operating Head</option>
          <option value="UML">United Moulders (UML)</option>
          <option value="CREW">Crewsaver (CREW)</option>
          <option value="PL">Plastimo (PL)</option>
          <option value="MANUAL">Apenas Manual</option>
        </select>
      </div>

      <div className="flex justify-between pt-4">
        <button
          onClick={onPrev}
          className="flex items-center gap-2 bg-white border border-slate-200 text-slate-700 px-6 py-3 rounded-xl font-bold hover:bg-slate-50 transition-colors shadow-sm"
        >
          <ArrowLeft size={18} /> Voltar
        </button>
        <button
          onClick={onNext}
          className="flex items-center gap-2 bg-indigo-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-indigo-700 transition-colors shadow-sm"
        >
          Próximo Passo <ChevronRight size={18} />
        </button>
      </div>
    </div>
  );
}

"use client";
import React, { useState } from "react";
import { useColeteWizardStore } from "./store/useColeteWizardStore";
import { ArrowLeft, ChevronRight, Activity, ChevronDown, Package, CheckCircle2, RefreshCw, X } from "lucide-react";

type Props = {
  onNext: () => void;
  onPrev: () => void;
};

export default function Step3_Componentes({ onNext, onPrev }: Props) {
  const { inspectionData, setInspectionData, globalStock } = useColeteWizardStore();
  const componentes = inspectionData.componentes || [];
  const [editingId, setEditingId] = useState<string | null>(null);

  const updateItem = (id: string, field: string, value: any) => {
    setInspectionData({
      componentes: componentes.map((comp) =>
        comp.id === id ? { ...comp, [field]: value } : comp
      )
    });
  };

  const visibleComponentes = componentes.filter((comp) => comp.id !== 'light' || inspectionData.temLuz !== false);

  const handleStockSelect = (id: string, stockIdStr: string) => {
    const stockId = parseInt(stockIdStr, 10);
    const stockItem = globalStock.find((s) => s.id === stockId);
    if (stockItem) {
      setInspectionData({
        componentes: componentes.map((comp) => 
          comp.id === id ? { 
            ...comp, 
            reference: stockItem.referencia,
            stockId: stockItem.id,
            validade: (comp.id === 'cylinder' || comp.id === 'whistle') ? comp.validade : (stockItem.validade || comp.validade),
            lote: stockItem.lote || comp.lote
          } : comp
        )
      });
    }
  };

  const handleConfirmReplace = (id: string) => {
    const comp = componentes.find((c) => c.id === id);
    if (comp && comp.stockId) {
      updateItem(id, 'substituido', true);
      setEditingId(null);
    }
  };

  const handleCancelReplace = (id: string) => {
    updateItem(id, 'substituido', false);
    updateItem(id, 'stockId', null);
    updateItem(id, 'reference', '');
    setEditingId(null);
  };

  const getFilteredStock = (compId: string) => {
    return globalStock.filter(s => {
      const desc = s.descricao.toLowerCase();
      const cat = s.categoria?.toLowerCase() || '';
      if (compId === 'cylinder') return cat.includes('cilindro') || desc.includes('co2') || desc.includes('cylinder');
      if (compId === 'cartridge') return cat.includes('bobbin') || cat.includes('pastilha') || desc.includes('cartridge') || desc.includes('bobbin');
      if (compId === 'light') return cat.includes('luz') || desc.includes('light');
      if (compId === 'whistle') return cat.includes('apito') || desc.includes('whistle') || desc.includes('apito');
      return true;
    });
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-300">
      <div>
        <h2 className="text-2xl font-bold text-slate-800">3. Componentes e Peças</h2>
        <p className="text-slate-600 mt-1">Registe as peças de reposição instaladas. Clique em &quot;Substituir&quot; para selecionar um artigo do Stock Global.</p>
      </div>

      <div className="rounded-2xl border border-slate-200 bg-white p-4 flex flex-wrap items-center justify-between gap-4">
        <div>
          <h3 className="text-sm font-bold text-slate-800">Configuração de Componentes</h3>
          <p className="text-xs text-slate-500">Indique quais os componentes instalados neste colete.</p>
        </div>
        <div className="flex items-center gap-3">
          <label className="text-xs font-semibold text-slate-700">Colete tem luz de emergência?</label>
          <select
            className="border border-slate-300 rounded-lg px-3 py-1.5 text-xs bg-white focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500"
            value={inspectionData.temLuz === false ? 'nao' : 'sim'}
            onChange={(e) => setInspectionData({ temLuz: e.target.value === 'sim' })}
          >
            <option value="sim">Sim</option>
            <option value="nao">Não</option>
          </select>
        </div>
      </div>

      <div className="space-y-4">
        {visibleComponentes.map((comp) => {
          const availableStock = getFilteredStock(comp.id);
          const isEditing = editingId === comp.id;

          return (
            <div key={comp.id} className="bg-white border border-slate-200 rounded-2xl p-6 shadow-sm hover:border-indigo-200 transition-colors">
              <div className="flex items-center gap-3 mb-5 border-b border-slate-100 pb-3">
                <div className="p-2 bg-indigo-50 text-indigo-600 rounded-lg">
                  {comp.id === 'light' ? <Activity size={20} /> : <Package size={20} />}
                </div>
                <div className="flex-1">
                  <h3 className="text-lg font-bold text-slate-800">{comp.name}</h3>
                  {comp.substituido && comp.stockId && (
                    <p className="text-xs font-semibold text-emerald-600 flex items-center gap-1 mt-0.5">
                      <CheckCircle2 size={12} /> Substituído — Ref: {comp.reference}
                    </p>
                  )}
                </div>
                {!isEditing && !comp.substituido && (
                  <button
                    type="button"
                    onClick={() => {
                      setEditingId(comp.id);
                      updateItem(comp.id, 'stockId', null);
                      updateItem(comp.id, 'reference', '');
                    }}
                    className="flex items-center gap-1.5 rounded-lg border border-indigo-300 bg-indigo-50 px-4 py-2 text-xs font-bold text-indigo-700 hover:bg-indigo-100 transition-colors"
                  >
                    <RefreshCw size={14} />
                    Substituir
                  </button>
                )}
                {!isEditing && comp.substituido && (
                  <button
                    type="button"
                    onClick={() => handleCancelReplace(comp.id)}
                    className="flex items-center gap-1.5 rounded-lg border border-slate-300 bg-slate-50 px-4 py-2 text-xs font-bold text-slate-600 hover:bg-slate-100 transition-colors"
                  >
                    <X size={14} />
                    Reverter
                  </button>
                )}
              </div>

              {isEditing ? (
                <div className="space-y-4 animate-in fade-in duration-200">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <label className="text-xs font-bold uppercase tracking-wider text-slate-500">
                        Artigo do Stock
                      </label>
                      <div className="relative">
                        <select
                          value={comp.stockId || ""}
                          onChange={(e) => handleStockSelect(comp.id, e.target.value)}
                          className="w-full border border-slate-200 rounded-xl px-4 py-3 bg-slate-50 text-slate-800 focus:bg-white focus:ring-2 focus:ring-indigo-100 appearance-none font-medium text-sm transition-colors"
                        >
                          <option value="" disabled>Selecione um artigo do stock...</option>
                          {availableStock.map((s) => (
                            <option key={s.id} value={s.id}>
                              {s.referencia} - {s.descricao} (Lote: {s.lote || 'N/A'}, Qtd: {s.quantidade})
                            </option>
                          ))}
                        </select>
                        <div className="absolute inset-y-0 right-4 flex items-center pointer-events-none">
                          <ChevronDown size={16} className="text-slate-400" />
                        </div>
                      </div>
                    </div>

                    {comp.id !== 'cylinder' && comp.id !== 'whistle' && (
                    <div className="space-y-1.5">
                      <label className="text-xs font-bold uppercase tracking-wider text-slate-500">
                        Validade
                      </label>
                      <input
                        type="month"
                        value={comp.validade}
                        onChange={(e) => updateItem(comp.id, 'validade', e.target.value)}
                        className="w-full border border-slate-200 rounded-xl px-4 py-3 bg-white text-slate-800 focus:ring-2 focus:ring-indigo-100 transition-colors text-sm font-medium"
                      />
                    </div>
                    )}

                    <div className="space-y-1.5">
                      <label className="text-xs font-bold uppercase tracking-wider text-slate-500">
                        Lote
                      </label>
                      <input
                        type="text"
                        value={comp.lote}
                        placeholder="Ex: L2345"
                        onChange={(e) => updateItem(comp.id, 'lote', e.target.value)}
                        className="w-full border border-slate-200 rounded-xl px-4 py-3 bg-white text-slate-800 focus:ring-2 focus:ring-indigo-100 transition-colors text-sm font-medium"
                      />
                    </div>
                  </div>

                  <div className="flex justify-end gap-2">
                    <button
                      type="button"
                      onClick={() => handleCancelReplace(comp.id)}
                      className="flex items-center gap-1.5 rounded-lg border border-slate-300 bg-white px-4 py-2 text-xs font-bold text-slate-600 hover:bg-slate-50 transition-colors"
                    >
                      <X size={14} />
                      Cancelar
                    </button>
                    <button
                      type="button"
                      onClick={() => handleConfirmReplace(comp.id)}
                      disabled={!comp.stockId}
                      className="flex items-center gap-1.5 rounded-lg bg-emerald-600 px-4 py-2 text-xs font-bold text-white hover:bg-emerald-700 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                    >
                      <CheckCircle2 size={14} />
                      Confirmar Substituição
                    </button>
                  </div>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-12 gap-5">
                  <div className="lg:col-span-4 space-y-1.5">
                    <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Referência</label>
                    <div className="w-full border border-slate-200 rounded-xl px-4 py-3 bg-slate-50 text-slate-700 text-sm font-medium">
                      {comp.reference || '—'}
                    </div>
                  </div>
                  {comp.id !== 'cylinder' && comp.id !== 'whistle' ? (
                  <div className="lg:col-span-3 space-y-1.5">
                    <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Validade</label>
                    <input
                      type="month"
                      value={comp.validade}
                      onChange={(e) => updateItem(comp.id, 'validade', e.target.value)}
                      className="w-full border border-slate-200 rounded-xl px-4 py-3 bg-white text-slate-800 focus:ring-2 focus:ring-indigo-100 transition-colors text-sm font-medium"
                    />
                  </div>
                  ) : <div className="hidden lg:block lg:col-span-3" />}
                  <div className="lg:col-span-3 space-y-1.5">
                    <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Lote</label>
                    <input
                      type="text"
                      value={comp.lote}
                      placeholder="Ex: L2345"
                      onChange={(e) => updateItem(comp.id, 'lote', e.target.value)}
                      className="w-full border border-slate-200 rounded-xl px-4 py-3 bg-white text-slate-800 focus:ring-2 focus:ring-indigo-100 transition-colors text-sm font-medium"
                    />
                  </div>
                  <div className="lg:col-span-2 space-y-1.5">
                    <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Qtd</label>
                    <div className="w-full border border-slate-200 rounded-xl px-4 py-3 bg-slate-50 text-slate-700 text-sm font-medium">
                      {(comp as any).quantidade || 1}
                    </div>
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>

      <div className="flex justify-between pt-4">
        <button
          onClick={onPrev}
          className="flex items-center gap-2 bg-white border border-slate-200 text-slate-700 px-6 py-3 rounded-xl font-bold hover:bg-slate-50 transition-colors shadow-sm"
        >
          <ArrowLeft size={18} /> Voltar
        </button>
        <button
          onClick={onNext}
          className="flex items-center gap-2 bg-indigo-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-indigo-700 transition-colors shadow-sm"
        >
          Próximo Passo <ChevronRight size={18} />
        </button>
      </div>
    </div>
  );
}

"use client";
import React, { useState } from 'react';
import { useColeteWizardStore } from './store/useColeteWizardStore';
import { Camera, Upload, Trash2, FileText } from 'lucide-react';

export default function Step5_Evidencias() {
  const { coleteId, inspectionData } = useColeteWizardStore();
  const [uploading, setUploading] = useState(false);
  const [evidencias, setEvidencias] = useState<any[]>([]); // This should ideally be fetched from the API

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !coleteId) return;

    setUploading(true);
    try {
      // Fake upload for demonstration, normally would call API
      // const formData = new FormData();
      // formData.append("file", file);
      // await fetch(`/api/coletes/${coleteId}/evidencias`, { method: "POST", body: formData });
      
      const novaEvidencia = {
        name: file.name,
        originalName: file.name,
        size: file.size,
        url: URL.createObjectURL(file),
        uploadedAt: new Date().toISOString()
      };
      
      setEvidencias((prev) => [...prev, novaEvidencia]);
    } catch (error) {
      console.error("Erro no upload", error);
    } finally {
      setUploading(false);
      e.target.value = '';
    }
  };

  const removeEvidencia = (name: string) => {
    setEvidencias(evidencias.filter(e => e.name !== name));
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div>
        <h2 className="text-2xl font-bold text-slate-800">5. Evidências da Inspecção</h2>
        <p className="text-slate-600 mt-1">Faça o upload de fotografias do colete, do mecanismo e de quaisquer anomalias encontradas.</p>
      </div>

      <div className="bg-white border border-slate-200 rounded-xl p-6 shadow-sm">
        <div className="flex flex-col items-center justify-center border-2 border-dashed border-slate-300 rounded-xl p-10 bg-slate-50">
          <Camera className="w-12 h-12 text-slate-400 mb-4" />
          <p className="text-sm font-medium text-slate-700 mb-2">Arraste fotos ou clique para fazer upload</p>
          <p className="text-xs text-slate-500 mb-4">Formatos suportados: JPG, PNG, WEBP, PDF</p>
          
          <label className="bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-2 rounded-xl font-semibold cursor-pointer transition-colors flex items-center gap-2">
            <Upload size={18} />
            {uploading ? 'A enviar...' : 'Selecionar Arquivo'}
            <input 
              type="file" 
              className="hidden" 
              accept=".jpg,.jpeg,.png,.webp,.pdf"
              onChange={handleUpload}
              disabled={uploading || !coleteId}
            />
          </label>
        </div>
      </div>

      {evidencias.length > 0 && (
        <div className="space-y-4">
          <h3 className="text-lg font-bold text-slate-800">Ficheiros Anexados</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {evidencias.map((ev, index) => (
              <div key={index} className="flex items-center gap-4 bg-white border border-slate-200 p-4 rounded-xl shadow-sm">
                <div className="w-16 h-16 bg-slate-100 rounded-lg flex items-center justify-center shrink-0 overflow-hidden">
                  {ev.name.toLowerCase().endsWith('.pdf') ? (
                    <FileText className="text-slate-400" />
                  ) : (
                    <img src={ev.url} alt={ev.name} className="w-full h-full object-cover" />
                  )}
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-semibold text-slate-800 truncate">{ev.name}</p>
                  <p className="text-xs text-slate-500">{(ev.size / 1024).toFixed(1)} KB</p>
                </div>
                <button 
                  onClick={() => removeEvidencia(ev.name)}
                  className="text-slate-400 hover:text-red-600 transition-colors p-2"
                >
                  <Trash2 size={18} />
                </button>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";
import React, { useState } from "react";
import { useColeteWizardStore } from "./store/useColeteWizardStore";
import { ArrowLeft, Save, CheckCircle2, ShieldCheck, Activity, AlertCircle, FileText, Download, Info } from "lucide-react";
import { useRouter } from "next/navigation";
import { formatValidityDisplay } from "@/lib/date-display";

type Props = {
  onPrev: () => void;
};

export default function Step5_Finalizar({ onPrev }: Props) {
  const router = useRouter();
  const { coleteId, inspectionId, inspectionData, reset, setIsDirty } = useColeteWizardStore();
  const [isSaving, setIsSaving] = useState(false);
  const [isDrafting, setIsDrafting] = useState(false);

  const missingFields: string[] = [];
  if (!inspectionData.serial) missingFields.push("Número de Série");
  if (!inspectionData.dataInspecao) missingFields.push("Data da Inspeção");

  const handleSave = async (status: "Concluída" | "Rascunho") => {
    if (status === "Concluída" && missingFields.length > 0) {
      alert(`Faltam campos obrigatórios: ${missingFields.join(", ")}`);
      return;
    }

    try {
      const isDraft = status === "Rascunho";
      if (isDraft) setIsDrafting(true);
      else setIsSaving(true);

      const payload = {
        id: inspectionId, // Se já existir um rascunho anterior, atualiza-o
        coleteId,
        coleteSerial: inspectionData.serial,
        shipId: inspectionData.shipId,
        navioNome: inspectionData.shipName,
        date: inspectionData.dataInspecao,
        dataProxInspecao: inspectionData.dataProxInspecao,
        status,
        applyStockMovements: status === "Concluída", // Apenas desconta stock se concluir
        
        // Em vez de passarmos artigosSubstituidos que era do Jangada
        // Formatamos no mesmo standard para a tabela Inspecao poder apanhar os stocks
        artigosSubstituidos: inspectionData.componentes
          .filter(c => c.stockId)
          .map(c => ({
            stockId: c.stockId,
            descricao: c.name,
            referencia: c.reference,
            quantidade: 1, // Coletes tipicamente levam 1 de cada (1 luz, 1 cilindro, etc)
            lote: c.lote,
            validade: c.validade
          })),

        // Guardamos as verificações visuais e testes no checklistSnapshot para histórico futuro
        checklistSnapshot: {
          tecidoExterior: inspectionData.tecidoExterior,
          colagens: inspectionData.colagens,
          fitasReflectoras: inspectionData.fitasReflectoras,
          sistemaInflacao: inspectionData.sistemaInflacao,
          mecanismoInflacao: inspectionData.mecanismoInflacao,
          camaras: inspectionData.camaras,
          garrafaCO2: inspectionData.garrafaCO2,
          tuboInflador: inspectionData.tuboInflador,
          zataosVelcro: inspectionData.zataosVelcro,
          testePressao: inspectionData.testePressao,
          testeInsuflacao: inspectionData.testeInsuflacao,
          testeVazamento: inspectionData.testeVazamento,
          observacoes: inspectionData.observacoes,
          
          // Guardar tbm os serials e refs
          cilindroRef: inspectionData.componentes.find(c => c.id === 'cylinder')?.reference,
          cilindroLote: inspectionData.componentes.find(c => c.id === 'cylinder')?.lote,
          luzRef: inspectionData.componentes.find(c => c.id === 'light')?.reference,
          pastilhaRef: inspectionData.componentes.find(c => c.id === 'cartridge')?.reference,
        }
      };

      const endpoint = "/api/inspecoes";
      const method = inspectionId ? "PUT" : "POST";
      
      const res = await fetch(endpoint, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      if (!res.ok) throw new Error("Erro ao gravar inspeção.");

      alert(isDraft ? "Rascunho guardado com sucesso!" : "Inspeção Concluída!");
      setIsDirty(false);
      
      // Update Colete model base records
      if (status === "Concluída" && coleteId) {
         const cylinder = inspectionData.componentes.find(c => c.id === 'cylinder');
         const cartridge = inspectionData.componentes.find(c => c.id === 'cartridge');
         const light = inspectionData.componentes.find(c => c.id === 'light');
         const whistle = inspectionData.componentes.find(c => c.id === 'whistle');

         const fmtVal = (v: string | null | undefined) => {
           if (!v) return null;
           const match = v.match(/^(\d{4})-(\d{2})$/);
           if (match) return `${match[2]}/${match[1]}`;
           return v;
         };

         await fetch(`/api/coletes/${coleteId}`, {
           method: "PUT",
           headers: { "Content-Type": "application/json" },
           body: JSON.stringify({
             dataInspecao: inspectionData.dataInspecao,
             dataProxInspecao: inspectionData.dataProxInspecao,
             testePressao: inspectionData.testePressao,
             testeInsuflacao: inspectionData.testeInsuflacao,
             testeVazamento: inspectionData.testeVazamento,
             observacoes: inspectionData.observacoes,
             
              temLuz: inspectionData.temLuz !== false,
              cilindroRef: cylinder?.stockId ? (cylinder?.reference || null) : undefined,
              cilindroLote: cylinder?.stockId ? (cylinder?.lote || null) : undefined,
              cilindroValidade: undefined,
              pastilhaRef: cartridge?.reference || null,
              pastilhaLote: cartridge?.lote || null,
              pastilhaValidade: fmtVal(cartridge?.validade),
              luzRef: inspectionData.temLuz !== false ? (light?.reference || null) : null,
              luzLote: inspectionData.temLuz !== false ? (light?.lote || null) : null,
              luzValidade: inspectionData.temLuz !== false ? fmtVal(light?.validade) : null,
              apitoRef: whistle?.stockId ? (whistle?.reference || null) : undefined,
              apitoLote: whistle?.stockId ? (whistle?.lote || null) : undefined,
              apitoValidade: undefined,
           })
         });

         // Create a VerificacaoColete record to show in timeline
         await fetch(`/api/coletes/${coleteId}/verificacoes`, {
           method: "POST",
           headers: { "Content-Type": "application/json" },
           body: JSON.stringify({
             tecidoExterior: inspectionData.tecidoExterior,
             colagens: inspectionData.colagens,
             zataosVelcro: inspectionData.zataosVelcro,
             fitasReflectoras: inspectionData.fitasReflectoras,
             sistemaInflacao: inspectionData.sistemaInflacao,
             mecanismoInflacao: inspectionData.mecanismoInflacao,
             camaras: inspectionData.camaras,
             garrafaCO2: inspectionData.garrafaCO2,
             tuboInflador: inspectionData.tuboInflador,
             dataVerificacao: inspectionData.dataInspecao,
             inspectorNome: "Técnico Autorizado",
             observacoes: inspectionData.observacoes,
           })
         });
         
         // Generate Certificate (calling the existing Colete certificate route if needed)
         await fetch(`/api/coletes/${coleteId}/certificado`, { method: "POST" });
      }

      reset();
      router.push(`/equipamentos`);
      router.refresh();

    } catch (err: any) {
      alert(err.message || "Erro desconhecido");
    } finally {
      setIsSaving(false);
      setIsDrafting(false);
    }
  };

  const componentesSubstituidos = inspectionData.componentes.filter(c => c.stockId);

  return (
    <div className="space-y-8 animate-in fade-in duration-300">
      <div>
        <h2 className="text-2xl font-bold text-slate-800">5. Resumo e Conclusão</h2>
        <p className="text-slate-600 mt-1">Valide todas as informações antes de finalizar a inspeção do colete.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        
        {/* Resumo da Inspeção */}
        <div className="space-y-6">
          <div className="bg-white border border-slate-200 rounded-2xl p-6 shadow-sm">
            <h3 className="font-bold text-slate-800 flex items-center gap-2 mb-4">
              <ShieldCheck size={18} className="text-emerald-500" /> Resumo de Componentes
            </h3>
            {componentesSubstituidos.length > 0 ? (
              <div className="space-y-3">
                {componentesSubstituidos.map(c => (
                  <div key={c.id} className="flex justify-between items-center text-sm p-3 bg-slate-50 rounded-xl">
                    <div>
                      <p className="font-bold text-slate-800">{c.name}</p>
                      <p className="text-slate-500">Ref: {c.reference}</p>
                    </div>
                    <div className="text-right">
                      {c.lote && <p className="text-slate-600 font-medium">Lote: {c.lote}</p>}
                      {c.validade && <p className="text-xs text-slate-500">Validade: {formatValidityDisplay(c.validade)}</p>}
                    </div>
                  </div>
                ))}
                <div className="mt-4 p-3 bg-blue-50 text-blue-700 text-xs rounded-xl flex items-center gap-2">
                  <Info size={14} /> Estes artigos serão descontados automaticamente do stock Global.
                </div>
              </div>
            ) : (
              <p className="text-sm text-slate-500 flex items-center gap-2">
                <AlertCircle size={16} /> Nenhum artigo selecionado do stock.
              </p>
            )}
          </div>

          <div className="bg-white border border-slate-200 rounded-2xl p-6 shadow-sm">
            <h3 className="font-bold text-slate-800 flex items-center gap-2 mb-4">
              <Activity size={18} className="text-indigo-500" /> Testes Registados
            </h3>
            <ul className="space-y-2 text-sm">
              <li className="flex justify-between border-b border-slate-100 pb-2">
                <span className="text-slate-500">Insuflação:</span>
                <span className="font-bold text-slate-800">{inspectionData.testeInsuflacao || "Não Registado"}</span>
              </li>
              <li className="flex justify-between pt-1">
                <span className="text-slate-500">Pressão / Estanquidade:</span>
                <span className="font-bold text-slate-800">{inspectionData.testePressao || "Não Registado"}</span>
              </li>
            </ul>
          </div>
        </div>

        {/* Acções e Erros */}
        <div className="bg-white border border-slate-200 rounded-2xl p-6 shadow-sm h-fit">
          <h3 className="font-bold text-slate-800 mb-4">Ações Finais</h3>
          
          {missingFields.length > 0 && (
            <div className="mb-6 p-4 bg-red-50 text-red-700 rounded-xl text-sm flex items-start gap-3">
              <AlertCircle size={18} className="shrink-0 mt-0.5" />
              <div>
                <p className="font-bold">Faltam campos obrigatórios:</p>
                <ul className="list-disc list-inside mt-1">
                  {missingFields.map(f => <li key={f}>{f}</li>)}
                </ul>
              </div>
            </div>
          )}

          <div className="space-y-3">
            <button
              onClick={() => handleSave("Rascunho")}
              disabled={isSaving || isDrafting}
              className="w-full flex items-center justify-center gap-2 bg-white border-2 border-slate-200 text-slate-700 px-6 py-4 rounded-xl font-bold hover:bg-slate-50 transition-colors disabled:opacity-50"
            >
              {isDrafting ? <Activity className="animate-spin" size={20} /> : <Save size={20} />}
              Guardar Rascunho
            </button>

            <button
              onClick={() => handleSave("Concluída")}
              disabled={isSaving || isDrafting || missingFields.length > 0}
              className="w-full flex items-center justify-center gap-2 bg-indigo-600 text-white px-6 py-4 rounded-xl font-bold hover:bg-indigo-700 transition-colors shadow-sm shadow-indigo-200 disabled:opacity-50"
            >
              {isSaving ? <Activity className="animate-spin" size={20} /> : <CheckCircle2 size={20} />}
              Concluir Inspeção e Emitir Certificado
            </button>
            <p className="text-xs text-center text-slate-400 mt-2">
              A conclusão da inspeção bloqueia alterações e gera o Certificado Final do Colete.
            </p>
          </div>
        </div>

      </div>

      <div className="flex justify-start pt-4">
        <button
          onClick={onPrev}
          className="flex items-center gap-2 bg-white border border-slate-200 text-slate-700 px-6 py-3 rounded-xl font-bold hover:bg-slate-50 transition-colors shadow-sm"
        >
          <ArrowLeft size={18} /> Voltar
        </button>
      </div>
    </div>
  );
}

