"use client";

import React from "react";

export type ChecklistLegalItem = {
  id: string;
  label: string;
  referencia: string;
};

const CHECKLIST_KEY = "dgrm-checklist-legal-v1";

const checklistLegal: ChecklistLegalItem[] = [
  {
    id: "estacao-aprovada",
    label: "Oficina técnica aprovada e certificada para revisão de jangadas.",
    referencia: "DL 103/95, arts. 1.º a 5.º",
  },
  {
    id: "periodicidade-12m",
    label: "Revisões periódicas realizadas no prazo máximo de 12 meses.",
    referencia: "DL 103/95, art. 7.º, n.º 3",
  },
  {
    id: "ficha-certificado-bordo",
    label: "Certificado de reinspecção e relatório mantidos/emitidos conforme exigido.",
    referencia: "DL 103/95, arts. 8.º e 9.º",
  },
  {
    id: "condicoes-area-servico",
    label: "Área de serviço cumpre condições técnicas (espaço, iluminação, ventilação e equipamento).",
    referencia: "Portaria 1232/95, n.º 2.º",
  },
  {
    id: "procedimentos-revisao",
    label: "Procedimentos de revisão (GI/NAP/WP e inspeções) seguidos segundo fabricante e portaria.",
    referencia: "Portaria 1232/95, n.º 3.º e Anexo I",
  },
  {
    id: "registos-5-anos",
    label: "Registos de revisão e deficiências mantidos por pelo menos 5 anos.",
    referencia: "Portaria 1232/95, n.º 2.º, 15",
  },
];

export default function DgrmChecklistLegal() {
  const [checked, setChecked] = React.useState<Record<string, boolean>>({});

  React.useEffect(() => {
    try {
      const raw = window.localStorage.getItem(CHECKLIST_KEY);
      if (!raw) return;
      const parsed = JSON.parse(raw) as Record<string, boolean>;
      setChecked(parsed || {});
    } catch {}
  }, []);

  function toggle(id: string, value: boolean) {
    setChecked((prev) => {
      const next = { ...prev, [id]: value };
      try {
        window.localStorage.setItem(CHECKLIST_KEY, JSON.stringify(next));
      } catch {}
      return next;
    });
  }

  const done = checklistLegal.filter((item) => checked[item.id]).length;

  return (
    <div className="rounded-xl border border-blue-200 bg-blue-50 p-4 shadow-sm">
      <h2 className="text-lg font-semibold text-blue-900">Checklist legal de auditoria</h2>
      <p className="mt-1 text-xs text-blue-800">Base legal ligada ao Decreto-Lei n.º 103/95 e à Portaria n.º 1232/95.</p>
      <p className="mt-2 text-xs text-blue-900">Concluído: <b>{done}</b> / <b>{checklistLegal.length}</b></p>

      <div className="mt-3 space-y-2">
        {checklistLegal.map((item) => (
          <label key={item.id} className="flex items-start gap-2 rounded border border-blue-100 bg-white px-3 py-2 text-sm">
            <input
              type="checkbox"
              checked={Boolean(checked[item.id])}
              onChange={(e) => toggle(item.id, e.target.checked)}
              className="mt-0.5"
            />
            <span>
              {item.label}
              <span className="block text-xs text-gray-500">{item.referencia}</span>
            </span>
          </label>
        ))}
      </div>

      <div className="mt-3 text-xs">
        <a href="https://diariodarepublica.pt/dr/detalhe/decreto-lei/103-1995-501873" target="_blank" rel="noreferrer" className="text-blue-700 hover:underline mr-3">
          Abrir DL 103/95
        </a>
        <a href="https://diariodarepublica.pt/dr/detalhe/portaria/1232-1995-663346" target="_blank" rel="noreferrer" className="text-blue-700 hover:underline">
          Abrir Portaria 1232/95
        </a>
      </div>

      <div className="mt-4 rounded border border-blue-100 bg-white p-3">
        <p className="text-sm font-semibold text-blue-900">Ferramentas/equipamentos exigidos na legislação?</p>
        <p className="mt-1 text-xs text-gray-700">
          Sim. A Portaria n.º 1232/95 (n.º 2.º e Anexo I) exige condições técnicas mínimas da oficina,
          incluindo meios/equipamentos adequados de inspeção e ensaio, condições de trabalho e controlo
          documental.
        </p>
        <ul className="mt-2 list-disc pl-5 text-xs text-gray-700 space-y-1">
          <li>Equipamentos de teste/inspeção e ferramentas adequadas às operações de revisão.</li>
          <li>Instrumentos de medição/ensaio calibrados e com evidência documental de calibração.</li>
          <li>Condições de área de serviço (espaço, iluminação, ventilação e segurança).</li>
          <li>Registos técnicos e evidências de conformidade preservados por período legal.</li>
        </ul>
      </div>
    </div>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import FatoImersaoWizard from "./FatoImersaoWizard";
import { useFatoImersaoWizardStore } from "./store/useFatoImersaoWizardStore";
import { toDisplayValidade } from "@/lib/fato-date-utils";

export default function FatoImersaoWizardLoader({ fatoId }: { fatoId: number }) {
  const { setFatoId, setInspectionData, reset } = useFatoImersaoWizardStore();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      setLoading(true);
      reset();
      try {
        const res = await fetch(`/api/fatos-imersao/${fatoId}`);
        if (!res.ok) throw new Error("Fato não encontrado");
        const data = await res.json();
        if (cancelled) return;
        setFatoId(fatoId);
        setInspectionData({
          serial: data.serial || "",
          brand: data.marca || "",
          model: data.modelo || "",
          designNo: data.designNo || "",
          tamanho: data.tamanho || "",
          material: data.material || "",
          dataFabrico: data.dataFabrico || "",
          dataInspecao: data.dataInspecao || new Date().toISOString().slice(0, 10),
          dataProxInspecao: data.dataProxInspecao || "",
          shipId: data.shipId || null,
          shipName: data.navio?.nome || "",
          intervaloServicoMeses: data.intervaloServicoMeses || null,
          componentes: [
            {
              id: "light",
              name: "Luz de emergência",
              reference: data.luzRef || "",
              stockId: null,
              validade: data.luzValidade || "",
              lote: data.luzLote || "",
            },
            {
              id: "whistle",
              name: "Apito",
              reference: data.apitoRef || "",
              stockId: null,
              validade: data.apitoValidade || "",
              lote: data.apitoLote || "",
            },
            { id: "buddy", name: "Buddy line", reference: "", stockId: null, validade: "", lote: "" },
            { id: "gloves", name: "Luvas", reference: "", stockId: null, validade: "", lote: "" },
            { id: "tape", name: "Fita retro-refletora", reference: "", stockId: null, validade: "", lote: "" },
            { id: "beeswax", name: "Beeswax / grease zip", reference: "", stockId: null, validade: "", lote: "" },
          ],
        });
      } catch (e: any) {
        if (!cancelled) setError(e.message || "Erro");
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [fatoId, reset, setFatoId, setInspectionData]);

  if (loading) return <div className="p-10 text-slate-500">A carregar wizard...</div>;
  if (error) return <div className="p-10 text-red-600">{error}</div>;
  return <FatoImersaoWizard />;
}

"use client";

import React, { useEffect } from "react";
import { ArrowLeft, ChevronRight, Package } from "lucide-react";
import { useFatoImersaoWizardStore } from "./store/useFatoImersaoWizardStore";

type Props = { onNext: () => void; onPrev: () => void };

export default function Step3_Componentes({ onNext, onPrev }: Props) {
  const { inspectionData, setInspectionData, globalStock, setGlobalStock } = useFatoImersaoWizardStore();

  useEffect(() => {
    if (globalStock.length) return;
    fetch("/api/stock")
      .then((r) => r.json())
      .then((d) => {
        const items = Array.isArray(d)
          ? d
          : Array.isArray(d?.items)
            ? d.items
            : Array.isArray(d?.data)
              ? d.data
              : Array.isArray(d?.stock)
                ? d.stock
                : [];
        setGlobalStock(
          items.map((s: any) => ({
            id: s.id,
            referencia: s.referencia || s.ref || "",
            descricao: s.descricao || s.nome || "",
            quantidade: Number(s.quantidade ?? s.qty ?? 0),
            categoria: s.categoria || null,
            validade: s.validade || null,
            lote: s.lote || null,
          }))
        );
      })
      .catch(() => {});
  }, [globalStock.length, setGlobalStock]);

  const updateComp = (id: string, patch: Partial<(typeof inspectionData.componentes)[0]>) => {
    setInspectionData({
      componentes: inspectionData.componentes.map((c) => (c.id === id ? { ...c, ...patch } : c)),
    });
  };

  const fiStock = globalStock.filter(
    (s) =>
      /imers|suit|fato|luz|apito|luvas|neoprene|buddy|strop|beeswax|reflex/i.test(
        `${s.referencia} ${s.descricao} ${s.categoria || ""}`
      ) || true
  );

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div>
        <h2 className="text-2xl font-bold text-slate-800">3. Componentes / stock</h2>
        <p className="text-slate-600 mt-1">Substituições ligadas ao stock (luz, apito, luvas, fitas…).</p>
      </div>

      <div className="space-y-4">
        {inspectionData.componentes.map((c) => (
          <div key={c.id} className="bg-white border border-slate-200 rounded-2xl p-4 shadow-sm">
            <div className="flex items-center gap-2 mb-3">
              <Package size={16} className="text-cyan-700" />
              <h3 className="font-bold text-slate-800">{c.name}</h3>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-3">
              <label className="text-xs md:col-span-2">
                <span className="font-semibold text-slate-500 uppercase">Artigo stock</span>
                <select
                  value={c.stockId ?? ""}
                  onChange={(e) => {
                    const sid = e.target.value ? Number(e.target.value) : null;
                    const st = fiStock.find((x) => x.id === sid);
                    updateComp(c.id, {
                      stockId: sid,
                      reference: st?.referencia || c.reference,
                      lote: st?.lote || c.lote,
                      validade: st?.validade || c.validade,
                      substituido: !!sid,
                    });
                  }}
                  className="mt-1 w-full border rounded-xl px-3 py-2 bg-slate-50 text-sm"
                >
                  <option value="">— sem substituição —</option>
                  {fiStock.slice(0, 200).map((s) => (
                    <option key={s.id} value={s.id}>
                      {s.referencia} · {s.descricao} (qty {s.quantidade})
                    </option>
                  ))}
                </select>
              </label>
              <label className="text-xs">
                <span className="font-semibold text-slate-500 uppercase">Ref.</span>
                <input
                  value={c.reference}
                  onChange={(e) => updateComp(c.id, { reference: e.target.value })}
                  className="mt-1 w-full border rounded-xl px-3 py-2 bg-slate-50 text-sm"
                />
              </label>
              <label className="text-xs">
                <span className="font-semibold text-slate-500 uppercase">Lote</span>
                <input
                  value={c.lote}
                  onChange={(e) => updateComp(c.id, { lote: e.target.value })}
                  className="mt-1 w-full border rounded-xl px-3 py-2 bg-slate-50 text-sm"
                />
              </label>
              <label className="text-xs">
                <span className="font-semibold text-slate-500 uppercase">Validade</span>
                <input
                  value={c.validade}
                  onChange={(e) => updateComp(c.id, { validade: e.target.value })}
                  placeholder="MM/AAAA"
                  className="mt-1 w-full border rounded-xl px-3 py-2 bg-slate-50 text-sm"
                />
              </label>
            </div>
          </div>
        ))}
      </div>

      <div className="flex justify-between pt-2">
        <button onClick={onPrev} className="inline-flex items-center gap-2 border border-slate-200 px-5 py-3 rounded-xl font-bold">
          <ArrowLeft size={18} /> Anterior
        </button>
        <button onClick={onNext} className="inline-flex items-center gap-2 bg-cyan-700 text-white px-6 py-3 rounded-xl font-bold">
          Seguinte <ChevronRight size={18} />
        </button>
      </div>
    </div>
  );
}

