    for (const item of stockCatalog) {
      const refKey = normalizeText(item?.referencia);
      const codeKey = normalizeText(item?.codigoFabricante);
      if (refKey) map[refKey] = item;
      if (codeKey && !map[codeKey]) map[codeKey] = item;
    }
    return map;
  }, [stockCatalog]);

