      if (!stockItem) return;
      const key = String(stockItem.id || stockItem.referencia || stockItem.codigoFabricante || reference);
      if (seen.has(key)) return;
      seen.add(key);
      result.push(stockItem);
    });

    return result;
  };

  const getTechnicalInventoryItemsByTokens = (...tokens: string[]) => {
