      const searchable = `${item?.name || ""} ${item?.reference || ""} ${item?.notes || ""} ${item?.category || ""}`;
      if (!matchesTechnicalTokens(searchable, tokens)) return false;
      const key = `${item?.name || ""}::${item?.reference || ""}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
