        {/* Comprimento da Retenida (m) */}
        <div className="space-y-2">
          <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Comprimento da Retenida (m)</label>
          <input 
            type="text" 
            className="w-full border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white transition-colors"
            placeholder="Ex: 36"
            value={inspectionData.painterLength || ''}
            onChange={(e) => handleChange('painterLength', e.target.value)}
          />
        </div>

        {/* Altura de Lançamento Máxima (m) */}
        <div className="space-y-2">
          <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Altura Máx. Lançamento (m)</label>
          <input 
            type="text" 
            className="w-full border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white transition-colors"
            placeholder="Ex: 18"
            value={inspectionData.maxStowageHeight || ''}
            onChange={(e) => handleChange('maxStowageHeight', e.target.value)}
          />
        </div>

        {/* Tipo de Tecido */}
        <div className="space-y-2">
          <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Tipo de Tecido</label>
          <select 
            className="w-full border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white transition-colors"
            value={inspectionData.fabricType || ''}
            onChange={(e) => handleChange('fabricType', e.target.value)}
          >
            <option value="">Desconhecido / Outro</option>
            <option value="PU">PU (Poliuretano)</option>
            <option value="NR">NR (Borracha Natural)</option>
            <option value="PVC">PVC</option>
          </select>
        </div>

        {/* Tipo de Lançamento */}
        <div className="space-y-2">
          <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Tipo de Lançamento</label>
          <select 
            className="w-full border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white transition-colors"
            value={inspectionData.launchType || ''}
            onChange={(e) => handleChange('launchType', e.target.value)}
          >
            <option value="">Desconhecido / Outro</option>
            <option value="Throw-Over">Throw-Over (Queda Livre)</option>
            <option value="Davit-Launched">Davit-Launched (Arriável por Turco)</option>
          </select>
        </div>

        {/* Bandeira */}
        <div className="space-y-2">
          <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Bandeira do Navio</label>
          <input 
            type="text" 
            className="w-full border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white transition-colors"
            placeholder="Ex: Portugal"
            value={inspectionData.shipFlag || ''}
            onChange={(e) => handleChange('shipFlag', e.target.value)}
          />
        </div>

        {/* IMO */}
        <div className="space-y-2">
          <label className="text-xs font-bold uppercase tracking-wider text-slate-500">IMO do Navio</label>
          <input 
            type="text" 
            className="w-full border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white transition-colors"
            placeholder="Ex: 9123456"
            value={inspectionData.shipImo || ''}
            onChange={(e) => handleChange('shipImo', e.target.value)}
          />
        </div>

        {/* Call Sign */}
        <div className="space-y-2">
          <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Indicativo de Chamada</label>
          <input 
            type="text" 
            className="w-full border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white transition-colors"
            placeholder="Ex: CSAB2"
            value={inspectionData.shipCallSign || ''}
            onChange={(e) => handleChange('shipCallSign', e.target.value)}
          />
        </div>
      </div>

      <hr className="border-slate-200 my-8" />

      <div>
        <h3 className="text-lg font-bold text-slate-800 mb-4">Dados da Inspeção e Certificação</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Número do Certificado */}
          <div className="space-y-2">
            <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Nº do Certificado</label>
            <input 
              type="text" 
              className="w-full border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white transition-colors"
              placeholder="Ex: AZ26-001 (Deixar vazio para auto-gerar)"
              value={inspectionData.certificadoNumero || ''}
              onChange={(e) => handleChange('certificadoNumero', e.target.value)}
            />
          </div>

          {/* Número da Obra */}
          <div className="space-y-2">
            <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Nº da Obra</label>
            <input 
              type="text" 
              className="w-full border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white transition-colors"
              placeholder="Ex: OB-2026/04"
              value={inspectionData.numeroObra || ''}
              onChange={(e) => handleChange('numeroObra', e.target.value)}
            />
          </div>

          {/* Data da Inspeção */}
          <div className="space-y-2">
            <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Data da Inspeção</label>
            <input 
              type="date" 
              className="w-full border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white transition-colors"
              value={inspectionData.dataInspecao || ''}
              onChange={(e) => handleChange('dataInspecao', e.target.value)}
            />
          </div>

          {/* Próxima Inspeção */}
          <div className="space-y-2">
            <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Próxima Inspeção (Prevista)</label>
            <input 
              type="date" 
              className="w-full border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white transition-colors"
              value={inspectionData.dataProxInspecao || ''}
              onChange={(e) => handleChange('dataProxInspecao', e.target.value)}
            />
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Data de Fabrico</label>
            <input 
              type="month" 
              className="w-full border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white transition-colors"
              value={inspectionData.dataFabrico || ''}
              onChange={(e) => handleChange('dataFabrico', e.target.value)}
            />
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold uppercase tracking-wider text-slate-500">HRU Instalado</label>
            <select 
              className="w-full border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white transition-colors"
              value={inspectionData.hruAplicavel || 'NAO'}
              onChange={(e) => handleChange('hruAplicavel', e.target.value)}
            >
              <option value="NAO">Não</option>
              <option value="SIM">Sim</option>
            </select>
          </div>

          {inspectionData.hruAplicavel === 'SIM' && (
            <div className="space-y-2">
              <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Validade do HRU</label>
              <input 
                type="month" 
                className={`w-full rounded-xl px-4 py-3 bg-amber-50 focus:bg-white transition-colors border ${
                  hruWarning 
                    ? 'border-amber-300 ring-2 ring-amber-100 bg-amber-50 focus:ring-amber-200' 
                    : 'border-slate-200'
                }`}
                value={inspectionData.hruValidade || ''}
                onChange={(e) => handleChange('hruValidade', e.target.value)}
              />
              {hruWarning && (
                <p className="text-[10px] text-amber-700 font-semibold mt-1">
                  ⚠️ Sugere-se substituir (val. inferior a {getInspectionIntervalLabel(inspectionData.brand, inspectionData.model, inspectionData.shipDetails)})
                </p>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
    </>
  );
}

"use client";
import React from 'react';
import { useJangadaWizardStore } from './store/useJangadaWizardStore';
import { Plus, Trash2, Tag, Calendar, Hash, Info } from 'lucide-react';
import { raftModelData } from '../rafts/raftModelData';
import { getInspectionIntervalYears, getInspectionIntervalLabel, getSubstitutionMaxValidityDays } from '../rafts/inspectionInterval';

const checkValidityWarning = (validadeStr: string, dataProxInspecao: string, dataInspecao: string, brand: string, shipDetails: any) => {
  if (!validadeStr) return null;
  
  let refDateStr = dataProxInspecao;
  if (!refDateStr && dataInspecao) {
    const years = getInspectionIntervalYears(brand, '', shipDetails);
    const parts = dataInspecao.split('-');
    if (parts[0] && parts[0].length === 4) {
      const year = parseInt(parts[0]) + years;
      const month = parts[1] || '01';
      const day = parts[2] || '01';
      refDateStr = `${year}-${month}-${day}`;
    }
  }
  
  if (!refDateStr) return null;
  
  const [vYear, vMonth] = validadeStr.split('-').map(Number);
  const valDate = new Date(vYear, (vMonth || 1) - 1, 1);
  
  const [pYear, pMonth] = refDateStr.split('-').map(Number);
  const proxDate = new Date(pYear, (pMonth || 1) - 1, 1);
  
  if (isNaN(valDate.getTime()) || isNaN(proxDate.getTime())) return null;
  
  if (valDate < proxDate) {
    return 'warning';
  }
  return 'ok';
};

const COMPONENT_TYPES = [
  'Cabeça Operacional (Operating Head)',
  'Válvula de Enchimento (Inlet Valve)',
  'Válvula de Alívio (Relief Valve)',
  'Válvula de Retenção (Non-Return Valve)',
  'Mangueira / Tubo Alta Pressão (High Pressure Hose)',
  'Manómetro (Pressure Gauge)',
  'Fita de Fecho (Bursting Band)',
  'Outro Componente'
];

export default function Step3_Componentes() {
  const { inspectionData, setInspectionData } = useJangadaWizardStore();

  const componentes = inspectionData.componentes || [];

  React.useEffect(() => {
    if (componentes.length === 0 && inspectionData.brand && inspectionData.model && !inspectionData.hasAutoFilledComponents) {
      const brandKey = inspectionData.brand.toUpperCase();
      const brandData = raftModelData[brandKey];
      
      if (brandData) {
        const modelData = brandData.find(m => 
          m.name.toUpperCase() === inspectionData.model.toUpperCase() ||
          m.aliases?.map(a => a.toUpperCase()).includes(inspectionData.model.toUpperCase())
        );

        if (modelData && (modelData.serviceItems || modelData.spareParts)) {
          const autoComponents: any[] = [];
          let idCounter = Date.now();
          
          if (modelData.serviceItems) {
            modelData.serviceItems.forEach(item => {
              autoComponents.push({
                id: (idCounter++).toString(),
                type: item.name,
                reference: item.reference || '',
                serialLote: '',
                validade: '',
                isAuto: true,
                category: item.category || 'SERVIÇO',
                notes: item.notes
              });
            });
          }
          
          if (modelData.spareParts) {
            modelData.spareParts.forEach(item => {
              autoComponents.push({
                id: (idCounter++).toString(),
                type: item.name,
                reference: item.reference || '',
                serialLote: '',
                validade: '',
                isAuto: true,
                category: item.category || 'SPARE',
                notes: item.notes
              });
            });
          }
          
          if (autoComponents.length > 0) {
            setInspectionData({ 
              componentes: autoComponents,
              hasAutoFilledComponents: true 
            });
          }
        }
      }
    }
  }, [inspectionData.brand, inspectionData.model, componentes.length, inspectionData.hasAutoFilledComponents, setInspectionData]);

  const addComponent = () => {
    setInspectionData({
      componentes: [
        ...componentes,
        { id: Date.now().toString(), type: COMPONENT_TYPES[0], reference: '', serialLote: '', validade: '', estado: '' }
      ]
    });
  };

  const removeComponent = (id: string) => {
    setInspectionData({
      componentes: componentes.filter((c: any) => c.id !== id)
    });
  };

  const updateComponent = (id: string, field: string, value: string) => {
    setInspectionData({
      componentes: componentes.map((c: any) => 
        c.id === id ? { ...c, [field]: value } : c
      )
    });
  };

  const getLongValidity = (comp: any): number | null => {
    if (String(comp.estado || '').toUpperCase() === 'DANIFICADO') return null;
    if (!comp.validade) return null;
    let refDateStr = inspectionData.dataProxInspecao;
    if (!refDateStr && inspectionData.dataInspecao) {
      const years = getInspectionIntervalYears(inspectionData.brand, '', inspectionData.shipDetails);
      const parts = inspectionData.dataInspecao.split('-');
      if (parts[0] && parts[0].length === 4) {
        refDateStr = `${parseInt(parts[0]) + years}-${parts[1] || '01'}-${parts[2] || '01'}`;
      }
    }
    if (!refDateStr) return null;
    const [vYear, vMonth] = comp.validade.split('-').map(Number);
    const valDate = new Date(vYear, (vMonth || 1) - 1, 1);
    const [rYear, rMonth] = refDateStr.split('-').map(Number);
    const refDate = new Date(rYear, (rMonth || 1) - 1, 1);
    if (isNaN(valDate.getTime()) || isNaN(refDate.getTime())) return null;
    const monthsDiff = (valDate.getFullYear() - refDate.getFullYear()) * 12 + (valDate.getMonth() - refDate.getMonth());
    const intervalMonths = getSubstitutionMaxValidityDays(inspectionData.brand, inspectionData.model, inspectionData.shipDetails) / 30;
    if (monthsDiff > intervalMonths) return monthsDiff;
    return null;
  };

  const handleStockSelect = (id: string, stockIdStr: string) => {
    const stockId = parseInt(stockIdStr, 10);
    const stockItem = inspectionData.globalStock?.find((s: any) => s.id === stockId);
    if (stockItem) {
      setInspectionData({
        componentes: componentes.map((c: any) => 
          c.id === id ? { 
            ...c, 
            reference: stockItem.referencia, 
            stockId: stockItem.id,
            validade: stockItem.validade || c.validade,
            serialLote: stockItem.lote || c.serialLote
          } : c
        )
      });
    }
  };

  // Filter stock for components
  const componentStock = (inspectionData.globalStock || []).filter((s: any) => {
    const cat = (s.categoria || '').toUpperCase();
    const desc = (s.descricao || '').toLowerCase();
    return cat.includes('VALV') || cat.includes('CILINDRO') || cat.includes('MANGUEIRA') ||
      cat.includes('COMPONENTE') || cat.includes('BEXIGA') || cat.includes('GASKET') ||
      cat.includes('OP_HEAD') || cat.includes('BOBBIN') || cat.includes('TUBO') ||
      desc.includes('valvula') || desc.includes('valve') || desc.includes('hose') ||
      desc.includes('mangueira') || desc.includes('operating head') || desc.includes('cabeca') ||
      desc.includes('cylinder') || desc.includes('cilindro') || desc.includes('o-ring') ||
      desc.includes('gasket') || desc.includes('vedante') || desc.includes('tubo');
  });

  return (
    <div className="space-y-8 animate-in fade-in duration-300">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">3. Componentes Críticos & Válvulas</h2>
          <p className="text-slate-600 mt-1">Registe as válvulas e cabeças substituídas ou inspecionadas.</p>
        </div>
        <button 
          onClick={addComponent}
          className="flex items-center justify-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-xl font-semibold shadow-sm hover:bg-indigo-700 transition-colors"
        >
          <Plus size={18} />
          Adicionar Componente
        </button>
      </div>

      {componentes.length === 0 ? (
        <div className="border-2 border-dashed border-slate-200 bg-slate-50 rounded-2xl p-12 flex flex-col items-center justify-center text-center">
          <WrenchIcon className="w-12 h-12 text-slate-300 mb-3" />
          <h3 className="text-lg font-semibold text-slate-700 mb-1">Nenhum componente registado</h3>
          <p className="text-sm text-slate-500 max-w-md">
            Clique no botão acima para adicionar válvulas, mangueiras ou cabeças operacionais substituídas durante a revisão desta jangada.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 gap-6">
           {componentes.map((comp: any) => {
            const warningStatus = checkValidityWarning(
              comp.validade,
              inspectionData.dataProxInspecao,
              inspectionData.dataInspecao,
              inspectionData.brand,
              inspectionData.shipDetails
            );
            const isWarning = warningStatus === 'warning';
            return (
              <div key={comp.id} className="border border-slate-200 rounded-2xl bg-white p-6 shadow-sm relative group transition-all hover:border-indigo-200 hover:shadow-md">
              <button 
                onClick={() => removeComponent(comp.id)}
                className="absolute top-4 right-4 p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors opacity-0 group-hover:opacity-100"
                title="Remover componente"
              >
                <Trash2 size={18} />
              </button>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="col-span-1 md:col-span-2 lg:col-span-1 space-y-1.5">
                  <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Tipo de Componente</label>
                  <select 
                    value={comp.type}
                    onChange={(e) => updateComponent(comp.id, 'type', e.target.value)}
                    className="w-full border-slate-200 rounded-xl px-3 py-2.5 bg-slate-50 focus:bg-white text-sm transition-colors font-medium"
                  >
                    {COMPONENT_TYPES.map(type => (
                      <option key={type} value={type}>{type}</option>
                    ))}
                  </select>
                </div>

                <div className="space-y-1.5">
                  <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Referência (P/N) do Stock</label>
                  <div className="relative">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                      <Tag size={14} className="text-slate-400" />
                    </div>
                    {componentStock.length > 0 ? (
                    <select 
                      value={comp.stockId || ""}
                      onChange={(e) => handleStockSelect(comp.id, e.target.value)}
                      className="w-full border-slate-200 rounded-xl pl-9 pr-3 py-2.5 bg-slate-50 focus:bg-white text-sm transition-colors"
                    >
                      <option value="" disabled>Selecionar peça do armazém...</option>
                      {componentStock.map((s: any) => (
                        <option key={s.id} value={s.id}>
                          {s.referencia} - {s.descricao} {s.quantidade > 0 ? `(Qtd: ${s.quantidade})` : '(Sem Stock)'}
                        </option>
                      ))}
                    </select>
                    ) : (
                    <div className="w-full border border-dashed border-slate-200 rounded-xl px-3 py-2.5 bg-slate-50 text-xs text-slate-400 italic">
                      Nenhum artigo de stock disponível para esta categoria
                    </div>
                    )}
                  </div>
                </div>

                <div className="space-y-1.5">
                  <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Lote / Nº Série</label>
                  <div className="relative">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                      <Hash size={14} className="text-slate-400" />
                    </div>
                    <input 
                      type="text" 
                      placeholder="Ex: L123 / SN456"
                      value={comp.serialLote}
                      onChange={(e) => updateComponent(comp.id, 'serialLote', e.target.value)}
                      className="w-full border-slate-200 rounded-xl pl-9 pr-3 py-2.5 bg-slate-50 focus:bg-white text-sm transition-colors"
                    />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Validade</label>
                  <div className="relative">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                      <Calendar size={14} className="text-slate-400" />
                    </div>
                    <input 
                      type="month" 
                      value={comp.validade}
                      onChange={(e) => updateComponent(comp.id, 'validade', e.target.value)}
                      className={`w-full border rounded-xl pl-9 pr-3 py-2.5 bg-slate-50 focus:bg-white text-sm transition-colors ${
                        isWarning
                          ? 'border-amber-300 ring-2 ring-amber-100 bg-amber-50 focus:ring-amber-200 text-amber-900'
                          : 'border-slate-200'
                      }`}
                    />
                    {isWarning && (
                      <p className="text-[10px] text-amber-700 font-semibold mt-1">
                        ⚠️ Sugere-se substituir (val. inferior a {getInspectionIntervalLabel(inspectionData.brand, inspectionData.model, inspectionData.shipDetails)})
                      </p>
                    )}
                    {getLongValidity(comp) !== null && (
                      <div className="mt-1.5 rounded-lg border border-amber-300 bg-amber-50 px-2 py-1.5">
                        <p className="text-[10px] font-bold text-amber-800 leading-snug">
                          Validade superior ao intervalo de inspeção ({getInspectionIntervalLabel(inspectionData.brand, inspectionData.model, inspectionData.shipDetails)}). Confirme que este componente foi efetivamente substituído.
                        </p>
                        <label className="flex items-center gap-1.5 mt-1 cursor-pointer select-none">
                          <input
                            type="checkbox"
                            checked={String(comp.estado || '').toUpperCase() === 'DANIFICADO'}
                            onChange={(e) => updateComponent(comp.id, 'estado', e.target.checked ? 'DANIFICADO' : '')}
                            className="rounded border-slate-300 text-amber-700 focus:ring-amber-500"
                          />
                          <span className="text-[10px] font-semibold text-amber-900">Componente danificado (substituído com justificação)</span>
                        </label>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          )})}
        </div>
      )}
    </div>
  );
}

function WrenchIcon(props: any) {
  return (
    <svg
      {...props}
      xmlns="http://www.w3.org/2000/svg"
      width="24"
      height="24"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z" />
    </svg>
  );
}

"use client";
import React, { useMemo } from 'react';
import { useJangadaWizardStore } from './store/useJangadaWizardStore';
import { Package, ShieldAlert, Zap, Droplets, Flame, Stethoscope, Info, PackageSearch, X } from 'lucide-react';
import { getMandatoryPackItemsForRaft, findMatchingArticleForPackItem } from '../rafts/mandatoryPack';
import { formatValidityDisplay } from '@/lib/date-display';
import { getInspectionIntervalYears, getInspectionIntervalLabel, getSubstitutionMaxValidityDays } from '../rafts/inspectionInterval';

const toMonthYearFormat = (dateStr?: string | null) => {
  if (!dateStr) return '';
  const trimmed = String(dateStr).trim();

  const mmYyyy = trimmed.match(/^(\d{1,2})\/(\d{4})$/);
  if (mmYyyy) {
    const month = Number(mmYyyy[1]);
    const year = Number(mmYyyy[2]);
    if (month >= 1 && month <= 12) return `${String(month).padStart(2, '0')}/${year}`;
  }

  const yyyyMm = trimmed.match(/^(\d{4})-(\d{1,2})/);
  if (yyyyMm) {
    const month = Number(yyyyMm[2]);
    const year = Number(yyyyMm[1]);
    if (month >= 1 && month <= 12) return `${String(month).padStart(2, '0')}/${year}`;
  }

  const d = new Date(trimmed);
  if (isNaN(d.getTime())) return '';
  return `${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
};

const parseMonthYear = (dateStr: string): { year: number; month: number } | null => {
  if (!dateStr) return null;
  const trimmed = String(dateStr).trim();

  const mmYyyy = trimmed.match(/^(\d{1,2})\/(\d{4})$/);
  if (mmYyyy) {
    const month = Number(mmYyyy[1]);
    const year = Number(mmYyyy[2]);
    if (year > 0 && month >= 1 && month <= 12) return { year, month };
  }

  const yyyyMm = trimmed.match(/^(\d{4})-(\d{1,2})$/);
  if (yyyyMm) {
    const year = Number(yyyyMm[1]);
    const month = Number(yyyyMm[2]);
    if (year > 0 && month >= 1 && month <= 12) return { year, month };
  }

  return null;
};

const maskMonthYearInput = (raw: string) => {
  const digits = String(raw || '').replace(/\D/g, '').slice(0, 6);
  if (digits.length <= 2) return digits;
  return `${digits.slice(0, 2)}/${digits.slice(2)}`;
};

const getStockCandidatesForLabel = (globalStock: any[], label: string) => {
  const queryDesc = (label || '').toLowerCase();
  const firstWord = queryDesc.split(' ')[0];
  return (globalStock || [])
    .filter((s: any) => s.quantidade > 0)
    .filter((s: any) => {
      const stockDesc = (s.descricao || '').toLowerCase();
      const refDesc = (s.referencia || '').toLowerCase();
      return stockDesc.includes(firstWord) ||
             refDesc.includes(firstWord) ||
             (s.categoria && s.categoria === 'PACK');
    });
};

const getStockAvailableForLabel = (globalStock: any[], label: string) => {
  return getStockCandidatesForLabel(globalStock, label).reduce(
    (sum, s: any) => sum + (s.quantidade || 0),
    0
  );
};

function getDaysRemaining(validadeStr: string, refDate: Date): number | null {
  const parsed = parseMonthYear(validadeStr);
  if (!parsed) return null;
  const expDate = new Date(parsed.year, parsed.month - 1, 1);
  const diffTime = expDate.getTime() - refDate.getTime();
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

const checkValidityWarning = (validadeStr: string, dataProxInspecao: string, dataInspecao: string, brand: string, shipDetails: any) => {
  if (!validadeStr) return null;
  
  let refDateStr = dataProxInspecao;
  if (!refDateStr && dataInspecao) {
    const years = getInspectionIntervalYears(brand, '', shipDetails);
    const parts = dataInspecao.split('-');
    if (parts[0] && parts[0].length === 4) {
      const year = parseInt(parts[0]) + years;
      const month = parts[1] || '01';
      const day = parts[2] || '01';
      refDateStr = `${year}-${month}-${day}`;
    }
  }
  
  if (!refDateStr) return null;
  
  const vParsed = parseMonthYear(validadeStr);
  if (!vParsed) return null;
  const valDate = new Date(vParsed.year, vParsed.month - 1, 1);
  
  const [pYear, pMonth] = refDateStr.split('-').map(Number);
  const proxDate = new Date(pYear, (pMonth || 1) - 1, 1);
  
  if (isNaN(valDate.getTime()) || isNaN(proxDate.getTime())) return null;
  
  if (valDate < proxDate) {
    return 'warning';
  }
  return 'ok';
};

const PACK_ICONS: Record<string, any> = {
  'agua': Droplets,
  'racoes': Package,
  'farmacia': Stethoscope,
  'comprimidos': ShieldAlert,
  'paraquedas': Flame,
  'fachos': Flame,
  'fumo': Flame,
  'pilhas': Zap,
};

const PACK_COLORS: Record<string, string> = {
  'agua': 'text-blue-500 bg-blue-50',
  'racoes': 'text-amber-600 bg-amber-50',
  'farmacia': 'text-emerald-600 bg-emerald-50',
  'comprimidos': 'text-teal-600 bg-teal-50',
  'paraquedas': 'text-red-500 bg-red-50',
  'fachos': 'text-orange-500 bg-orange-50',
  'fumo': 'text-slate-600 bg-slate-100',
  'pilhas': 'text-yellow-600 bg-yellow-50',
};

export default function Step4_PackMascara() {
  const { inspectionData, setInspectionData } = useJangadaWizardStore();

  const packItems = inspectionData.packItems || {};

  const refDate = React.useMemo(
    () => (inspectionData.dataInspecao ? new Date(inspectionData.dataInspecao) : new Date()),
    [inspectionData.dataInspecao]
  );

  // Calcular itens obrigatórios baseados na jangada atual
  const mandatoryItems = useMemo(() => {
    return getMandatoryPackItemsForRaft({
      brand: inspectionData.brand,
      model: inspectionData.model,
      packType: inspectionData.packType,
      capacity: inspectionData.capacity as number,
    });
  }, [inspectionData.brand, inspectionData.model, inspectionData.packType, inspectionData.capacity]);

  
  React.useEffect(() => {
    if (mandatoryItems.length > 0 && (!packItems || Object.keys(packItems).length === 0)) {
      const initialPackItems: any = {};
      mandatoryItems.forEach(item => {
        const matched = findMatchingArticleForPackItem(item, (inspectionData.artigos || []) as any[]) as any;
        initialPackItems[item.checklistName] = {
          checklistName: item.checklistName,
          name: item.label,
          descricao: item.label,
          quantidade: item.quantity,
          quantidadeVerificada: matched ? matched.quantidade : 0,
          validade: matched ? toMonthYearFormat(matched.validade) : '',
          validadeOriginal: matched ? toMonthYearFormat(matched.validade) : '',
          lote: matched ? matched.codigoFabricante || matched.referencia || '' : '',
          referencia: matched ? matched.referencia : '',
          stockId: matched ? matched.id : undefined,
        };
      });
      setInspectionData({ packItems: initialPackItems });
    }
  }, [mandatoryItems, packItems, setInspectionData, inspectionData.artigos]);

  const updateItem = (referenciaStr: string, field: string, value: string) => {
    const updated = { ...packItems };
    for (const key of Object.keys(updated)) {
      if (updated[key].referencia === referenciaStr) {
        updated[key] = { ...updated[key], [field]: value };
      }
    }
    setInspectionData({ packItems: updated });
  };

  const [stockDialogKey, setStockDialogKey] = React.useState<string | null>(null);

  const applyStockItem = (key: string, stockItem: any) => {
    if (!stockItem) return;
    setInspectionData({
      packItems: {
        ...packItems,
        [key]: {
          ...(packItems[key] || {}),
          referencia: stockItem.referencia,
          stockId: stockItem.id,
          descricao: stockItem.descricao || packItems[key]?.descricao,
          validade: toMonthYearFormat(stockItem.validade) || packItems[key]?.validade || '',
          lote: stockItem.lote || '',
        },
      },
    });
    setStockDialogKey(null);
  };

  const clearStock = (key: string) => {
    const updated = { ...packItems };
    const current = { ...(updated[key] || {}) };
    delete current.stockId;
    updated[key] = current;
    setInspectionData({ packItems: updated });
  };

  const isDamagedItem = (item: any) => String(item.estado || '').toUpperCase() === 'DANIFICADO';

  const getSubstitutionBlockReason = (item: any) => {
    if (isDamagedItem(item)) return null;
    if (!item?.validadeOriginal) return null;
    const maxDays = getSubstitutionMaxValidityDays(inspectionData.brand, inspectionData.model, inspectionData.shipDetails);
    const days = getDaysRemaining(item.validadeOriginal, refDate);
    if (days === null || days <= maxDays) return null;
    return days;
  };

  const handleItemChange = (itemId: string, field: string, value: any) => {
    const current = packItems[itemId] || {};

    if (field === 'quantidade') {
      const newQty = Number(value) || 0;
      if (newQty > 0 && getSubstitutionBlockReason(current) !== null) return;
      setInspectionData({
        packItems: { ...packItems, [itemId]: { ...current, quantidade: newQty } },
      });
      return;
    }

    if (field === 'estado') {
      const newEstado = value ? 'DANIFICADO' : '';
      const next = { ...current, estado: newEstado };
      if (newEstado === '' && (Number(current.quantidade) || 0) > 0 && getSubstitutionBlockReason(current) !== null) {
        next.quantidade = 0;
      }
      setInspectionData({ packItems: { ...packItems, [itemId]: next } });
      return;
    }

    setInspectionData({
      packItems: { ...packItems, [itemId]: { ...current, [field]: value } }
    });
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-300">
      <div>
        <h2 className="text-2xl font-bold text-slate-800">4. Pack de Emergência</h2>
        <p className="text-slate-600 mt-1">Registe as validades e quantidades dos consumíveis obrigatórios da jangada.</p>
        <div className="mt-3 flex items-center gap-2 bg-indigo-50 text-indigo-700 px-3 py-2 rounded-lg text-sm font-medium w-fit border border-indigo-100">
          <Info size={16} />
          A mostrar requisitos para: {inspectionData.packType || 'Pack não definido'} / {inspectionData.capacity || '0'} Pax
        </div>
        {(() => {
          const insufficientItems = mandatoryItems.filter((item) => {
            const data = packItems[item.checklistName] || {};
            const qty = data.quantidade || 0;
            return qty > 0 && qty > getStockAvailableForLabel(inspectionData.globalStock, item.label);
          });
          if (insufficientItems.length === 0) return null;
          return (
            <div className="mt-3 flex items-start gap-3 rounded-xl border border-red-300 bg-red-50 px-4 py-3">
              <ShieldAlert className="text-red-600 shrink-0 mt-0.5" size={20} />
              <div>
                <p className="text-sm font-bold text-red-800">
                  {insufficientItems.length} artigo{insufficientItems.length === 1 ? '' : 's'} com stock insuficiente
                </p>
                <p className="text-xs text-red-700 mt-0.5">
                  {insufficientItems.map((item) => item.label).join(' · ')} — quantidade substituída excede o stock disponível.
                </p>
              </div>
            </div>
          );
        })()}
      </div>

      <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
        <div className="grid grid-cols-12 gap-4 bg-slate-50 px-6 py-4 border-b border-slate-200 text-xs font-bold text-slate-500 uppercase tracking-wider">
          <div className="col-span-12 lg:col-span-4">Artigo de Emergência</div>
          <div className="col-span-6 lg:col-span-2 text-center">Obrigatório</div>
          <div className="col-span-6 lg:col-span-3 text-center">Verificado / Substituído</div>
          <div className="col-span-12 lg:col-span-3">Nova Validade / Lote</div>
        </div>

        <div className="divide-y divide-slate-100">
          {mandatoryItems.length === 0 ? (
            <div className="p-8 text-center text-slate-500">
              Configure o "Tipo de Pack" e "Capacidade" no Passo 1 para ver os itens obrigatórios.
            </div>
          ) : (
            mandatoryItems.map((item) => {
              const simpleKey = item.checklistName.replace('validade_', '').replace('foguetoes_', '').replace('_alimentares', '').replace('_mao', '').replace('_lanterna', '').replace('_enjoo', '');
              const icon = PACK_ICONS[simpleKey] || Package;
              const color = PACK_COLORS[simpleKey] || 'text-indigo-600 bg-indigo-50';
              const IconComponent = icon;

              const data = packItems[item.checklistName] || { quantidadeVerificada: 0, quantidade: 0, lote: '', validade: '' };
              const isDamaged = isDamagedItem(data);
              const blockReasonDays = getSubstitutionBlockReason(data);
              const warningStatus = checkValidityWarning(
                data.validade || '',
                inspectionData.dataProxInspecao,
                inspectionData.dataInspecao,
                inspectionData.brand,
                inspectionData.shipDetails
              );
              const isWarning = warningStatus === 'warning';
              
              return (
                <div key={item.checklistName} className="grid grid-cols-12 gap-4 px-6 py-5 items-center hover:bg-slate-50/50 transition-colors">
                  <div className="col-span-12 lg:col-span-4 flex items-center gap-3">
                    <div className={`p-2 rounded-lg ${color}`}>
                      <IconComponent size={20} />
                    </div>
                    <div>
                      <p className="font-semibold text-slate-800 flex items-center gap-2">
                        {item.label}
                        {data.quantidade > 0 && (
                          <span className="inline-flex items-center text-[9px] font-bold px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-700 border border-emerald-200">
                            ✓ Substituído
                          </span>
                        )}
                      </p>
                      <p className="text-[10px] uppercase tracking-wider text-slate-400 font-medium">{item.category}</p>
                      {data.validadeOriginal && (() => {
                        const parts = data.validadeOriginal.split('-').map(Number);
                        const vYear = parts[0] || new Date().getFullYear();
                        const vMonth = parts[1] || 1;
                        const expDate = new Date(vYear, vMonth - 1, 1);
                        const insDate = new Date(inspectionData.dataInspecao || Date.now());
                        const diffDays = Math.ceil((expDate.getTime() - insDate.getTime()) / (1000 * 60 * 60 * 24));
                        const isExpired = diffDays < 0;
                        const isNearExpiry = diffDays <= 60;
                        return (
                          <div className="mt-1 flex flex-wrap items-center gap-2 text-[11px]">
                            <span className={`px-2 py-0.5 rounded-md font-bold flex items-center gap-1 ${
                              isExpired ? 'bg-red-100 text-red-800 border border-red-200' :
                              isNearExpiry ? 'bg-amber-100 text-amber-800 border border-amber-200' :
                              'bg-slate-100 text-slate-700'
                            }`}>
                              <span>Anterior: {data.validadeOriginal}</span>
                              {isExpired && <span>(Caducado)</span>}
                              {isNearExpiry && !isExpired && <span>(A caducar)</span>}
                            </span>
                            {(isExpired || isNearExpiry) && data.quantidade === 0 && (
                              <button
                                type="button"
                                onClick={() => handleItemChange(item.checklistName, 'quantidade', item.quantity || 1)}
                                className="text-[10px] font-extrabold px-2 py-0.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-md shadow-sm transition"
                              >
                                Substituir Agora
                              </button>
                            )}
                          </div>
                        );
                      })()}
                    </div>
                  </div>
                  
                  <div className="col-span-6 lg:col-span-2 flex justify-center">
                    <div className="bg-slate-100 px-3 py-1.5 rounded-lg text-slate-700 font-semibold text-sm w-fit border border-slate-200">
                      {item.quantityLabel}
                    </div>
                  </div>

                  <div className="col-span-6 lg:col-span-3 flex flex-col gap-1.5">
                    <div className="flex gap-2">
                      <div className="w-1/2">
                        <label className="text-[10px] uppercase text-slate-400 font-bold mb-1 block lg:hidden">Verificado</label>
                        <input
                          type="number"
                          min="0"
                          placeholder="Verif."
                          value={data.quantidadeVerificada || ''}
                          onChange={(e) => handleItemChange(item.checklistName, 'quantidadeVerificada', parseInt(e.target.value) || 0)}
                          className="w-full text-sm border-slate-200 rounded-xl px-2 py-2 bg-white focus:ring-2 focus:ring-indigo-100 transition-colors"
                          title="Quantidade Verificada"
                        />
                      </div>
                      <div className="w-1/2">
                        <label className="text-[10px] uppercase text-slate-400 font-bold mb-1 block lg:hidden">Substituído</label>
                        <input
                          type="number"
                          min="0"
                          placeholder="Subst."
                          value={data.quantidade || ''}
                          onChange={(e) => handleItemChange(item.checklistName, 'quantidade', parseInt(e.target.value) || 0)}
                          className={`w-full text-sm rounded-xl px-2 py-2 bg-white focus:ring-2 transition-colors ${
                            data.quantidade > 0 && (data.quantidade || 0) > getStockAvailableForLabel(inspectionData.globalStock, item.label)
                              ? 'border-red-300 ring-2 ring-red-100 bg-red-50'
                              : 'border-slate-200 focus:ring-indigo-100'
                          }`}
                          title="Quantidade Substituída"
                        />
                      </div>
                    </div>
                    <label className="flex items-center gap-1.5 text-[11px] font-semibold cursor-pointer select-none">
                      <input
                        type="checkbox"
                        checked={isDamaged}
                        onChange={(e) => handleItemChange(item.checklistName, 'estado', e.target.checked ? 'DANIFICADO' : '')}
                        className="rounded border-slate-300 text-red-600 focus:ring-red-500"
                      />
                      <span className={isDamaged ? 'text-red-700' : 'text-slate-600'}>Danificado</span>
                    </label>
                    {blockReasonDays !== null && (
                      isDamaged ? (
                        <div className="flex items-start gap-2 rounded-xl border border-emerald-300 bg-emerald-50 px-3 py-2 text-[11px] font-bold text-emerald-800">
                          <ShieldAlert size={14} className="shrink-0 mt-0.5" />
                          <span className="leading-snug">Substituição permitida — artigo marcado como danificado.</span>
                        </div>
                      ) : (
                        <div className="flex items-start gap-2 rounded-xl border border-amber-300 bg-amber-50 px-3 py-2 text-[11px] font-bold text-amber-800">
                          <ShieldAlert size={14} className="shrink-0 mt-0.5" />
                          <span className="leading-snug">
                            Validade original superior a {getInspectionIntervalLabel(inspectionData.brand, inspectionData.model, inspectionData.shipDetails)} (expira em {blockReasonDays} dias). Só é possível substituir se marcar o artigo como <b>Danificado</b>.
                          </span>
                        </div>
                      )
                    )}
                    {(() => {
                      const selectedStock = data.stockId
                        ? (inspectionData.globalStock || []).find((s: any) => s.id === data.stockId)
                        : null;
                      const selectedStockAvailable = selectedStock?.quantidade || 0;
                      const totalAvailable = getStockAvailableForLabel(inspectionData.globalStock, item.label);
                      const qty = data.quantidade || 0;
                      const insufficientTotal = qty > 0 && qty > totalAvailable;
                      const insufficientSelected = selectedStock && qty > 0 && qty > selectedStockAvailable;
                      if (!insufficientTotal && !insufficientSelected) return null;
                      return (
                        <div className={`flex items-start gap-2 rounded-xl border px-3 py-2 text-[11px] font-bold ${
                          insufficientSelected
                            ? 'border-red-300 bg-red-50 text-red-800'
                            : 'border-amber-300 bg-amber-50 text-amber-800'
                        }`}>
                          <ShieldAlert size={14} className="shrink-0 mt-0.5" />
                          <div className="leading-snug">
                            {insufficientSelected && selectedStock
                              ? <>Stock insuficiente no lote {selectedStock.lote || selectedStock.referencia}: disponível {selectedStockAvailable}, necessita {qty}.</>
                              : <>Stock insuficiente: disponível {totalAvailable}, necessita {qty}.</>}
                          </div>
                        </div>
                      );
                    })()}
                  </div>

                  <div className="col-span-12 lg:col-span-3 flex flex-col gap-3">
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-bold uppercase tracking-wider text-slate-500">Lote no Stock (Opcional)</label>
                      <div className="flex gap-2">
                        <button
                          type="button"
                          onClick={() => setStockDialogKey(item.checklistName)}
                          className={`flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-bold transition-colors border ${
                            data.stockId
                              ? 'bg-indigo-50 text-indigo-700 border-indigo-200 hover:bg-indigo-100'
                              : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50 hover:text-slate-800'
                          }`}
                        >
                          <PackageSearch size={14} />
                          {data.stockId ? 'Alterar lote' : 'Substituir do Stock'}
                        </button>
                        {data.stockId && (
                          <button
                            type="button"
                            onClick={() => clearStock(item.checklistName)}
                            title="Remover seleção de stock"
                            className="px-2 py-2 rounded-lg text-xs font-bold text-slate-400 border border-slate-200 hover:text-red-600 hover:border-red-200 hover:bg-red-50 transition-colors"
                          >
                            <X size={14} />
                          </button>
                        )}
                      </div>
                      {(() => {
                        const selectedStock = data.stockId
                          ? (inspectionData.globalStock || []).find((s: any) => s.id === data.stockId)
                          : null;
                        if (!selectedStock) return null;
                        const insufficient = data.quantidade > 0 && data.quantidade > selectedStock.quantidade;
                        return (
                          <div className="mt-1.5 text-[10px] leading-relaxed">
                            <p className="text-slate-500">
                              Ref: <b className="text-slate-700">{selectedStock.referencia}</b>
                              {selectedStock.lote ? ` · Lote: ${selectedStock.lote}` : ''}
                              {selectedStock.validade ? ` · Val: ${formatValidityDisplay(selectedStock.validade)}` : ''}
                            </p>
                            <p className={insufficient ? 'text-red-700 font-bold' : 'text-emerald-700 font-semibold'}>
                              {insufficient
                                ? `⚠️ Stock insuficiente — disponível: ${selectedStock.quantidade}`
                                : `✓ Disponível: ${selectedStock.quantidade}`}
                            </p>
                          </div>
                        );
                      })()}
                    </div>
                    
                    <div className="flex gap-2">
                      <div className="w-1/2">
                        <label className="text-[10px] uppercase text-slate-400 font-bold mb-1 block">
                          Validade (MM/AAAA) {data.validade && <span className="inline-block w-1.5 h-1.5 rounded-full bg-emerald-500 ml-1"></span>}
                        </label>
                        <input
                          type="text"
                          inputMode="numeric"
                          placeholder="MM/AAAA"
                          maxLength={7}
                          value={data.validade}
                          onChange={(e) => handleItemChange(item.checklistName, 'validade', maskMonthYearInput(e.target.value))}
                          className={`w-full text-sm rounded-xl px-2 py-2 bg-white focus:ring-2 transition-colors border ${
                            data.quantidade > 0 && !data.validade 
                              ? 'border-red-300 ring-2 ring-red-100 bg-red-50' 
                              : isWarning
                                ? 'border-amber-300 ring-2 ring-amber-100 bg-amber-50 focus:ring-amber-200 text-amber-900'
                                : 'border-slate-200 focus:ring-indigo-100'
                          }`}
                        />
                        {data.validade && (() => {
                          const refDate = inspectionData.dataInspecao ? new Date(inspectionData.dataInspecao) : new Date();
                          const days = getDaysRemaining(data.validade, refDate);
                          if (days === null) return null;
                          if (days < 0) return <p className="text-[9px] text-red-700 font-bold mt-1">⛔ Expirado há {Math.abs(days)} dias</p>;
                          if (days <= 30) return <p className="text-[9px] text-red-700 font-bold mt-1">⚠️ Expira em {days} dias</p>;
                          if (days <= 90) return <p className="text-[9px] text-amber-700 font-semibold mt-1">Expira em {days} dias</p>;
                          return <p className="text-[9px] text-emerald-700 font-medium mt-1">✓ Válido por {days} dias</p>;
                        })()}
                        {isWarning && (
                          <p className="text-[9px] text-amber-700 font-semibold mt-1 leading-tight">
                            ⚠️ Sugere-se substituir (val. inferior a {getInspectionIntervalLabel(inspectionData.brand, inspectionData.model, inspectionData.shipDetails)})
                          </p>
                        )}
                      </div>
                      <div className="w-1/2">
                        <label className="text-[10px] uppercase text-slate-400 font-bold mb-1 block">Lote Manual</label>
                        <input
                          type="text"
                          placeholder="Ex: A23"
                          value={data.lote}
                          onChange={(e) => handleItemChange(item.checklistName, 'lote', e.target.value)}
                          className="w-full text-sm border-slate-200 rounded-xl px-2 py-2 bg-white focus:ring-2 focus:ring-indigo-100 transition-colors"
                        />
                      </div>
                    </div>
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>
      
      <div className="bg-amber-50 border border-amber-200 rounded-xl p-4 flex gap-3 items-start">
        <ShieldAlert className="text-amber-600 shrink-0 mt-0.5" size={20} />
        <div>
          <h4 className="text-sm font-bold text-amber-900">Atenção Crítica de Validades</h4>
          <p className="text-xs text-amber-800 mt-1">A validade global da jangada será ditada pelo artigo de emergência que expirar primeiro. Certifique-se que nenhuma validade inserida expira antes da próxima revisão agendada.</p>
        </div>
      </div>

      {stockDialogKey && (() => {
        const dialogItem = mandatoryItems.find((i) => i.checklistName === stockDialogKey);
        const candidates = getStockCandidatesForLabel(inspectionData.globalStock, dialogItem?.label || '')
          .sort((a: any, b: any) => (b.quantidade || 0) - (a.quantidade || 0));

        return (
          <div
            className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm"
            onClick={() => setStockDialogKey(null)}
          >
            <div
              className="bg-white rounded-2xl shadow-2xl border border-slate-100 w-full max-w-lg overflow-hidden animate-in fade-in zoom-in-95"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100">
                <div>
                  <h3 className="text-lg font-bold text-slate-800">Substituir do Stock</h3>
                  <p className="text-xs text-slate-500">{dialogItem?.label} — escolha o lote a aplicar</p>
                </div>
                <button
                  type="button"
                  onClick={() => setStockDialogKey(null)}
                  className="p-2 rounded-lg text-slate-400 hover:text-slate-600 hover:bg-slate-100 transition-colors"
                >
                  <X size={18} />
                </button>
              </div>

              <div className="p-4 max-h-[50vh] overflow-y-auto space-y-2">
                {candidates.length === 0 ? (
                  <div className="text-center py-10 text-slate-500 text-sm">
                    <PackageSearch size={32} className="mx-auto mb-2 text-slate-300" />
                    Sem artigos de stock disponíveis para este item.
                  </div>
                ) : (
                  candidates.map((s: any) => (
                    <button
                      key={s.id}
                      type="button"
                      onClick={() => applyStockItem(stockDialogKey, s)}
                      className="w-full text-left p-3 rounded-xl border border-slate-200 hover:border-indigo-300 hover:bg-indigo-50/40 transition-colors"
                    >
                      <div className="flex items-center justify-between gap-3">
                        <div className="min-w-0">
                          <p className="font-bold text-slate-800 text-sm truncate">{s.referencia}</p>
                          <p className="text-xs text-slate-500 truncate">{s.descricao}</p>
                          <p className="text-[10px] text-slate-400 mt-0.5">
                            Lote: {s.lote || 'N/A'}{s.validade ? ` · Validade: ${formatValidityDisplay(s.validade)}` : ''}
                          </p>
                        </div>
                        <span className={`shrink-0 text-xs font-bold px-2.5 py-1 rounded-lg ${
                          s.quantidade > 0 ? 'bg-emerald-50 text-emerald-700' : 'bg-red-50 text-red-700'
                        }`}>
                          {s.quantidade} disp.
                        </span>
                      </div>
                    </button>
                  ))
                )}
              </div>

              <div className="px-6 py-3 border-t border-slate-100 flex justify-end">
                <button
                  type="button"
                  onClick={() => setStockDialogKey(null)}
                  className="px-4 py-2 text-sm font-bold text-slate-600 hover:bg-slate-100 rounded-xl transition-colors"
                >
                  Cancelar
                </button>
              </div>
            </div>
          </div>
        );
      })()}
    </div>
  );
}

"use client";
import React, { useEffect, useMemo, useState } from 'react';
import { useJangadaWizardStore } from './store/useJangadaWizardStore';
import { getTestRecommendations, type TestRecommendation } from '@/modules/rafts/testRules';
import { Activity, Gauge, ArrowDownToLine, Droplet, Clock, AlertTriangle, Info, CheckCircle2, XCircle, HelpCircle } from 'lucide-react';

const TEST_ICONS: Record<string, React.ElementType> = {
  testeWP: Gauge,
  testeGI: Droplet,
  testeFS: Activity,
  testeNAP: Clock,
  testeDL: ArrowDownToLine,
};

const STATUS_CONFIG: Record<string, { bg: string; border: string; text: string; label: string; icon: React.ElementType }> = {
  required: {
    bg: 'bg-amber-50',
    border: 'border-amber-300',
    text: 'text-amber-800',
    label: 'Obrigatório',
    icon: AlertTriangle,
  },
  'not-required': {
    bg: 'bg-slate-50',
    border: 'border-slate-200',
    text: 'text-slate-500',
    label: 'Não aplicável',
    icon: XCircle,
  },
  overdue: {
    bg: 'bg-red-50',
    border: 'border-red-300',
    text: 'text-red-800',
    label: 'Atrasado',
    icon: AlertTriangle,
  },
  optional: {
    bg: 'bg-blue-50',
    border: 'border-blue-200',
    text: 'text-blue-700',
    label: 'Recomendado',
    icon: Info,
  },
  unknown: {
    bg: 'bg-slate-50',
    border: 'border-slate-200',
    text: 'text-slate-500',
    label: 'Sem dados',
    icon: HelpCircle,
  },
};

export default function Step6_Testes() {
  const { inspectionData, setInspectionData } = useJangadaWizardStore();
  const testes = inspectionData.testes || {};
  const [equipments, setEquipments] = useState<any[]>([]);

  const recommendations = useMemo(() => getTestRecommendations({
    brand: inspectionData.brand,
    model: inspectionData.model,
    launchType: inspectionData.launchType,
    dataFabrico: inspectionData.dataFabrico,
    inspectionDate: inspectionData.dataInspecao,
  }), [inspectionData.brand, inspectionData.model, inspectionData.launchType, inspectionData.dataFabrico, inspectionData.dataInspecao]);

  const recMap = useMemo(() => {
    const map: Record<string, TestRecommendation> = {};
    for (const rec of recommendations) map[rec.testId] = rec;
    return map;
  }, [recommendations]);

  const ageYears = recommendations[0]?.ageYears ?? null;

  const requiredButSkipped = useMemo(() => {
    return recommendations.filter(r =>
      r.status === 'required' && testes[r.testId] === 'N/A'
    );
  }, [recommendations, testes]);

  useEffect(() => {
    fetch('/api/equipamentos-calibracao')
      .then(res => res.json())
      .then(data => {
        if (Array.isArray(data)) {
          setEquipments(data);
        }
      })
      .catch(err => console.error('Erro ao carregar equipamentos de calibração:', err));
  }, []);

  const checkCalibrationWarning = (sensorId: string) => {
    if (!sensorId) return null;
    const sensor = equipments.find(e => String(e.id) === String(sensorId));
    if (!sensor) return null;
    const expDate = new Date(sensor.dataProxCalibracao);
    const insDate = inspectionData.date ? new Date(inspectionData.date) : new Date();
    if (isNaN(expDate.getTime())) return null;
    if (insDate > expDate) {
      return `O equipamento "${sensor.nome}" [Ref: ${sensor.referencia}] está com calibração expirada desde ${expDate.toLocaleDateString('pt-PT')}.`;
    }
    return null;
  };

  const handleTestChange = (testId: string, result: string) => {
    setInspectionData({
      testes: {
        ...testes,
        [testId]: result
      }
    });
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-300">
      <div>
        <h2 className="text-2xl font-bold text-slate-800">6. Testes Operacionais e de Pressão</h2>
        <p className="text-slate-600 mt-1">Registe os resultados dos testes estruturais realizados na jangada.</p>
      </div>

      {/* Age-Based Test Summary */}
      <div className="bg-gradient-to-r from-indigo-50 to-blue-50 border border-indigo-200 rounded-2xl p-5">
        <div className="flex items-center gap-3 mb-4">
          <div className="bg-indigo-100 p-2 rounded-xl">
            <Info size={20} className="text-indigo-600" />
          </div>
          <div>
            <h3 className="text-sm font-bold text-indigo-900 uppercase tracking-wider">Testes Recomendados pela Idade</h3>
            <p className="text-xs text-indigo-700 mt-0.5">
              {ageYears !== null
                ? `Jangada com ${ageYears} ano(s) desde fabrico — regras SOLAS/ISO aplicáveis`
                : 'Idade desconhecida — sem data de fabrico registada'}
            </p>
          </div>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
          {recommendations.map((rec) => {
            const cfg = STATUS_CONFIG[rec.status] || STATUS_CONFIG.unknown;
            const Icon = cfg.icon;
            const currentResult = testes[rec.testId] || '';
            const isSkipped = currentResult === 'N/A' && rec.status === 'required';

            return (
              <div
                key={rec.testId}
                className={`rounded-xl p-3 border ${cfg.bg} ${cfg.border} ${isSkipped ? 'ring-2 ring-red-400 ring-offset-1' : ''}`}
              >
                <div className="flex items-center gap-1.5 mb-1">
                  <Icon size={14} className={cfg.text} />
                  <span className={`text-xs font-bold ${cfg.text}`}>{rec.shortLabel}</span>
                </div>
                <p className={`text-[11px] font-semibold ${cfg.text} leading-tight`}>{cfg.label}</p>
                {rec.nextGiYear !== null && rec.testId === 'testeGI' && rec.status !== 'overdue' && (
                  <p className="text-[10px] text-indigo-600 mt-1">Próx. GI: {rec.nextGiYear}</p>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Warning: Required Tests Skipped */}
      {requiredButSkipped.length > 0 && (
        <div className="bg-red-50 border border-red-300 rounded-2xl p-4 flex items-start gap-3">
          <AlertTriangle size={20} className="text-red-600 shrink-0 mt-0.5" />
          <div>
            <p className="text-sm font-bold text-red-800">
              Testes obrigatórios marcados como N/A
            </p>
            <p className="text-xs text-red-700 mt-1">
              {requiredButSkipped.map(r => r.shortLabel).join(', ')} — {requiredButSkipped.length === 1 ? 'é obrigatório' : 'são obrigatórios'} para uma jangada com {ageYears} ano(s).
              Altere o resultado para PASSOU ou REPROVOU antes de avançar.
            </p>
          </div>
        </div>
      )}

      <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
        <div className="bg-slate-50 px-6 py-4 border-b border-slate-200 flex items-center justify-between">
          <h3 className="text-lg font-bold text-slate-800">Painel de Testes</h3>
        </div>

        <div className="divide-y divide-slate-100 p-6 space-y-6">
          {recommendations.map((rec) => {
            const currentResult = testes[rec.testId] || '';
            const isWP = rec.testId === 'testeWP';
            const cfg = STATUS_CONFIG[rec.status] || STATUS_CONFIG.unknown;
            const StatusIcon = cfg.icon;
            const isSkipped = currentResult === 'N/A' && rec.status === 'required';
            const TestIcon = TEST_ICONS[rec.testId] || Gauge;

            return (
              <div
                key={rec.testId}
                className={`pt-6 first:pt-0 border-t border-slate-100 first:border-0 ${isSkipped ? 'bg-red-50/50 -mx-6 px-6 rounded-xl' : ''}`}
              >
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                  <div className="flex items-start gap-4">
                    <div className={`p-3 rounded-xl shrink-0 ${
                      rec.status === 'required' ? 'bg-amber-100 text-amber-600' :
                      rec.status === 'overdue' ? 'bg-red-100 text-red-600' :
                      rec.status === 'not-required' ? 'bg-slate-100 text-slate-400' :
                      'bg-indigo-50 text-indigo-600'
                    }`}>
                      <TestIcon size={24} />
                    </div>
                    <div className="flex-1">
                      <div className="flex items-center gap-2 flex-wrap">
                        <h4 className="text-base font-bold text-slate-800">{rec.label}</h4>
                        <span className={`inline-flex items-center gap-1 text-[11px] font-bold px-2 py-0.5 rounded-full ${cfg.bg} ${cfg.border} border ${cfg.text}`}>
                          <StatusIcon size={12} />
                          {cfg.label}
                        </span>
                        {isSkipped && (
                          <span className="inline-flex items-center gap-1 text-[11px] font-bold px-2 py-0.5 rounded-full bg-red-100 border border-red-300 text-red-700">
                            <AlertTriangle size={12} />
                            Obrigatório — não pode ser N/A
                          </span>
                        )}
                      </div>
                      <p className="text-sm text-slate-500 mt-1">{rec.reason}</p>
                      <p className="text-xs text-slate-400 mt-0.5">{rec.detail}</p>
                    </div>
                  </div>

                  <div className="flex bg-slate-100 p-1 rounded-xl w-fit">
                    {['PASSOU', 'REPROVOU', 'N/A'].map((option) => (
                      <button
                        key={option}
                        onClick={() => handleTestChange(rec.testId, option)}
                        className={`px-6 py-2.5 rounded-lg text-sm font-bold transition-all ${
                          currentResult === option
                            ? option === 'PASSOU'
                              ? 'bg-emerald-500 text-white shadow-sm'
                              : option === 'REPROVOU'
                                ? 'bg-red-500 text-white shadow-sm'
                                : 'bg-slate-600 text-white shadow-sm'
                            : 'text-slate-500 hover:text-slate-700 hover:bg-slate-200'
                        }`}
                      >
                        {option}
                      </button>
                    ))}
                  </div>
                </div>

                {isWP && currentResult === 'PASSOU' && (
                  <div className="mt-6 ml-[3.25rem] grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 bg-slate-50 p-5 rounded-2xl border border-slate-200">
                    <div className="col-span-full mb-2 flex justify-between items-center">
                      <h5 className="text-sm font-bold text-slate-700">Parâmetros do Teste WP</h5>
                      <div className="flex items-center gap-2">
                        <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Unidade:</label>
                        <select 
                          value={testes.wpUnidadePressao === 'mbar' ? 'hpa' : (testes.wpUnidadePressao || 'hpa')}
                          onChange={(e) => handleTestChange('wpUnidadePressao', e.target.value)}
                          className="border-slate-200 rounded-xl px-2 py-1 text-xs font-bold bg-white focus:ring-2 focus:ring-indigo-100"
                        >
                          <option value="hpa">hPa</option>
                          <option value="inh2o">inH2O</option>
                          <option value="inhg">inHg</option>
                        </select>
                      </div>
                    </div>

                    {/* Equipamentos de Medição */}
                    <div className="col-span-full grid grid-cols-1 md:grid-cols-2 gap-4 mb-2 bg-indigo-50/50 p-4 rounded-xl border border-indigo-100/50">
                      <div className="space-y-1.5">
                        <label className="text-xs font-bold uppercase tracking-wider text-slate-500 font-semibold text-slate-700">Manómetro (Pressão das Câmaras)</label>
                        <select
                          value={testes.wpManometroId || ''}
                          onChange={(e) => handleTestChange('wpManometroId', e.target.value)}
                          className="w-full border-slate-200 rounded-xl px-3 py-2 bg-white text-sm focus:ring-2 focus:ring-indigo-100 font-medium text-slate-700"
                        >
                          <option value="">-- Selecione o Manómetro --</option>
                          {equipments.filter(e => e.tipo === 'manometro').map(e => (
                            <option key={e.id} value={e.id}>{e.nome} ({e.referencia})</option>
                          ))}
                        </select>
                        {(() => {
                          const warning = checkCalibrationWarning(testes.wpManometroId);
                          if (warning) {
                            return (
                              <div className="text-xs font-semibold text-amber-700 flex items-center gap-1.5 mt-1 bg-amber-50 p-1.5 rounded border border-amber-200">
                                <AlertTriangle size={14} className="shrink-0" />
                                <span>{warning}</span>
                              </div>
                            );
                          }
                          return null;
                        })()}
                      </div>

                      <div className="space-y-1.5">
                        <label className="text-xs font-bold uppercase tracking-wider text-slate-500 font-semibold text-slate-700">Barómetro (Pressão Atmosférica)</label>
                        <select
                          value={testes.wpBarometroId || ''}
                          onChange={(e) => handleTestChange('wpBarometroId', e.target.value)}
                          className="w-full border-slate-200 rounded-xl px-3 py-2 bg-white text-sm focus:ring-2 focus:ring-indigo-100 font-medium text-slate-700"
                        >
                          <option value="">-- Selecione o Barómetro --</option>
                          {equipments.filter(e => e.tipo === 'barometro').map(e => (
                            <option key={e.id} value={e.id}>{e.nome} ({e.referencia})</option>
                          ))}
                        </select>
                        {(() => {
                          const warning = checkCalibrationWarning(testes.wpBarometroId);
                          if (warning) {
                            return (
                              <div className="text-xs font-semibold text-amber-700 flex items-center gap-1.5 mt-1 bg-amber-50 p-1.5 rounded border border-amber-200">
                                <AlertTriangle size={14} className="shrink-0" />
                                <span>{warning}</span>
                              </div>
                            );
                          }
                          return null;
                        })()}
                      </div>
                    </div>

                    <div className="space-y-1.5">
                      <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Hora Início</label>
                      <input 
                        type="time" 
                        value={testes.wpHoraInicio || ''}
                        onChange={(e) => {
                          const val = e.target.value;
                          handleTestChange('wpHoraInicio', val);
                          if (val) {
                            const [h, m] = val.split(':').map(Number);
                            if (!isNaN(h) && !isNaN(m)) {
                              const endH = (h + 1) % 24;
                              handleTestChange('wpHoraFim', `${String(endH).padStart(2, '0')}:${String(m).padStart(2, '0')}`);
                            }
                          }
                        }}
                        className="w-full border-slate-200 rounded-xl px-3 py-2 bg-white text-sm focus:ring-2 focus:ring-indigo-100"
                      />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Hora Fim (Automático +60m)</label>
                      <input 
                        type="time" 
                        value={testes.wpHoraFim || ''}
                        onChange={(e) => handleTestChange('wpHoraFim', e.target.value)}
                        className="w-full border-slate-200 rounded-xl px-3 py-2 bg-white text-sm focus:ring-2 focus:ring-indigo-100"
                      />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Temp. Inicial (ºC)</label>
                      <input 
                        type="number" step="0.1"
                        value={testes.wpTempInicio || ''}
                        onChange={(e) => handleTestChange('wpTempInicio', e.target.value)}
                        className="w-full border-slate-200 rounded-xl px-3 py-2 bg-white text-sm focus:ring-2 focus:ring-indigo-100"
                      />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Temp. Final (ºC)</label>
                      <input 
                        type="number" step="0.1"
                        value={testes.wpTempFim || ''}
                        onChange={(e) => handleTestChange('wpTempFim', e.target.value)}
                        className="w-full border-slate-200 rounded-xl px-3 py-2 bg-white text-sm focus:ring-2 focus:ring-indigo-100"
                      />
                    </div>

                    <div className="space-y-1.5">
                      <label className="text-xs font-bold uppercase tracking-wider text-slate-500">P. Atmosférica Inicial (hPa)</label>
                      <input 
                        type="number" step="0.1"
                        value={testes.wpPressaoAtmInicio || ''}
                        onChange={(e) => handleTestChange('wpPressaoAtmInicio', e.target.value)}
                        className="w-full border-slate-200 rounded-xl px-3 py-2 bg-white text-sm focus:ring-2 focus:ring-indigo-100"
                      />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-xs font-bold uppercase tracking-wider text-slate-500">P. Atmosférica Final (hPa)</label>
                      <input 
                        type="number" step="0.1"
                        value={testes.wpPressaoAtmFim || ''}
                        onChange={(e) => handleTestChange('wpPressaoAtmFim', e.target.value)}
                        className="w-full border-slate-200 rounded-xl px-3 py-2 bg-white text-sm focus:ring-2 focus:ring-indigo-100"
                      />
                    </div>

                    <div className="col-span-full border-t border-slate-200 my-2"></div>

                    <div className="space-y-1.5">
                      <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Pressão Câm. Sup. (Início)</label>
                      <input 
                        type="number" step="0.01"
                        value={testes.wpCamaraSupInicio || ''}
                        onChange={(e) => handleTestChange('wpCamaraSupInicio', e.target.value)}
                        className="w-full border-slate-200 rounded-xl px-3 py-2 bg-white text-sm focus:ring-2 focus:ring-indigo-100"
                      />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Pressão Câm. Sup. (Fim)</label>
                      <input 
                        type="number" step="0.01"
                        value={testes.wpCamaraSupFim || ''}
                        onChange={(e) => handleTestChange('wpCamaraSupFim', e.target.value)}
                        className="w-full border-slate-200 rounded-xl px-3 py-2 bg-white text-sm focus:ring-2 focus:ring-indigo-100"
                      />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Pressão Câm. Inf. (Início)</label>
                      <input 
                        type="number" step="0.01"
                        value={testes.wpCamaraInfInicio || ''}
                        onChange={(e) => handleTestChange('wpCamaraInfInicio', e.target.value)}
                        className="w-full border-slate-200 rounded-xl px-3 py-2 bg-white text-sm focus:ring-2 focus:ring-indigo-100"
                      />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Pressão Câm. Inf. (Fim)</label>
                      <input 
                        type="number" step="0.01"
                        value={testes.wpCamaraInfFim || ''}
                        onChange={(e) => handleTestChange('wpCamaraInfFim', e.target.value)}
                        className="w-full border-slate-200 rounded-xl px-3 py-2 bg-white text-sm focus:ring-2 focus:ring-indigo-100"
                      />
                    </div>

