"use client";
import React, { useMemo, useEffect, useState } from 'react';
import { useJangadaWizardStore } from './store/useJangadaWizardStore';
import { AlertTriangle, CheckCircle, Save, FileText, Anchor, ShieldAlert } from 'lucide-react';
import { useRouter } from 'next/navigation';
import SignatureCanvas from '@/components/shared/SignatureCanvas';
import { appToast } from '@/lib/app-toast';
import { enqueueOfflineSyncOperation } from '@/lib/offline-sync/client';
import { formatDateDisplay } from '@/lib/date-display';
import { getIvaRate, calcIva, round2 } from '@/lib/iva';

export default function Step8_ResumoFinal() {
  const router = useRouter();
  const { 
    jangadaId,
    shipId,
    inspecaoId,
    setInspecaoId,
    inspectionData, 
    setInspectionData,
    setStep,
    setIsSaving,
    isSaving
  } = useJangadaWizardStore();

  const [selectedTecnicoId, setSelectedTecnicoId] = useState<string>('');
  const [tecnicos, setTecnicos] = useState<any[]>([]);
  const [certs, setCerts] = useState<any[]>([]);

  useEffect(() => {
    fetch('/api/tecnicos?includeInactive=false')
      .then(res => res.json())
      .then(data => {
        if (Array.isArray(data)) {
          setTecnicos(data);
          if (inspectionData.responsavel) {
            const match = data.find(t => t.nome.toLowerCase() === inspectionData.responsavel.toLowerCase());
            if (match) {
              setSelectedTecnicoId(String(match.id));
            }
          }
        }
      })
      .catch(err => console.error('Erro ao carregar técnicos:', err));
  }, [inspectionData.responsavel]);

  useEffect(() => {
    if (selectedTecnicoId) {
      fetch(`/api/tecnicos/certificacoes?tecnicoId=${selectedTecnicoId}`)
        .then(res => res.json())
        .then(data => {
          if (Array.isArray(data)) {
            setCerts(data);
          }
        })
        .catch(err => console.error('Erro ao carregar certificações:', err));
    } else {
      setCerts([]);
    }
  }, [selectedTecnicoId]);

  const checkTechnicianCertification = () => {
    if (!selectedTecnicoId) return null;
    const brand = (inspectionData.brand || '').trim().toUpperCase();
    if (!brand) return null;

    const hasCert = certs.find(c => {
      const matchBrand = c.fabricante.trim().toUpperCase() === brand;
      const valid = new Date(c.dataValidade) >= (inspectionData.dataInspecao ? new Date(inspectionData.dataInspecao) : new Date());
      return matchBrand && valid && c.ativo;
    });

    if (!hasCert) {
      const tecnico = tecnicos.find(t => String(t.id) === String(selectedTecnicoId));
      return `O técnico ${tecnico?.nome || ''} não tem certificação válida do fabricante ${brand} para esta balsa.`;
    }
    return null;
  };

  // Validate the data to generate warnings
  const warnings = useMemo(() => {
    const list: { text: string; step: number; isCritical: boolean }[] = [];
    const today = new Date();
    const insDate = inspectionData.dataInspecao ? new Date(inspectionData.dataInspecao) : today;

    // Step 1 Validations
    if (!inspectionData.serial) list.push({ text: 'Nº de Série da jangada não definido.', step: 1, isCritical: true });
    if (!inspectionData.brand || !inspectionData.model) list.push({ text: 'Marca ou Modelo da jangada não definidos.', step: 1, isCritical: true });
    if (!inspectionData.packType) list.push({ text: 'Tipo de Pack não selecionado.', step: 1, isCritical: true });
    if (!inspectionData.dataProxInspecao) list.push({ text: 'Data da Próxima Inspeção não definida.', step: 1, isCritical: true });
    
    // Step 2 Validations
    const checklistItems = Object.values(inspectionData.checklist || {});
    const reprovados = checklistItems.filter((item: any) => item.status === 'REPROVADO');
    if (reprovados.length > 0) {
      list.push({ text: `Existem ${reprovados.length} itens do checklist exterior/interior marcados como Reprovado.`, step: 2, isCritical: true });
    }

    // Step 3 Validations
    const componentes = inspectionData.componentes || [];
    const missingValidades = componentes.filter((c: any) => !c.validade);
    if (missingValidades.length > 0) {
      list.push({ text: `Falta definir a validade em ${missingValidades.length} componente(s) crítico(s).`, step: 3, isCritical: true });
    }

    // Step 4 Validations - Pack consumíveis
    const packItems = Object.values(inspectionData.packItems || {});
    const mandatoryPackItems = packItems.filter((item: any) => item.quantidade >= 0); // todos os itens do pack
    const consumiveisSemValidade = mandatoryPackItems.filter((item: any) => !item.validade || item.validade.trim() === '');
    if (consumiveisSemValidade.length > 0) {
      list.push({ text: `${consumiveisSemValidade.length} itens obrigatórios do pack sem validade registada.`, step: 4, isCritical: true });
    }
    const consumiveisSubstituidosSemValidade = packItems.filter((item: any) => item.quantidade > 0 && (!item.validade || item.validade.trim() === ''));
    if (consumiveisSubstituidosSemValidade.length > 0) {
      list.push({ text: `Foram substituídos ${consumiveisSubstituidosSemValidade.length} consumíveis sem registo de nova validade.`, step: 4, isCritical: true });
    }
    
    // Validades a expirar (dias restantes)
    packItems.forEach((item: any) => {
      if (item.validade) {
        const [vYear, vMonth] = item.validade.split('-').map(Number);
        const expDate = new Date(vYear, (vMonth || 1) - 1, 1);
        const diffTime = expDate.getTime() - insDate.getTime();
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
        if (diffDays < 0) {
          list.push({ text: `${item.name}: validade expirada há ${Math.abs(diffDays)} dias (${formatMonthYearDisplay(item.validade)})`, step: 4, isCritical: true });
        } else if (diffDays <= 30) {
          list.push({ text: `${item.name}: validade expira em ${diffDays} dias (${formatMonthYearDisplay(item.validade)})`, step: 4, isCritical: diffDays <= 0 });
        } else if (diffDays <= 90) {
          list.push({ text: `${item.name}: validade em ${diffDays} dias (${formatMonthYearDisplay(item.validade)})`, step: 4, isCritical: false });
        }
      }
    });

    // Step 5 Validations - Cilindro
    if (!inspectionData.cylinder?.serial) list.push({ text: 'Nº de Série do cilindro não definido.', step: 5, isCritical: false });
    if (!inspectionData.cylinder?.pesoBruto) list.push({ text: 'Peso Bruto do cilindro não verificado.', step: 5, isCritical: false });
    
    const rawProxTeste = inspectionData.cylinder?.dataProxTeste || inspectionData.cylinder?.nextTestDate;
    if (rawProxTeste) {
      const expDate = new Date(rawProxTeste);
      if (!isNaN(expDate.getTime())) {
        const diffTime = expDate.getTime() - insDate.getTime();
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
        if (diffDays < 0) {
          list.push({
            text: `Teste hidrostático cilindro (${inspectionData.cylinder?.serial || 'S/N'}) expirado desde ${expDate.toLocaleDateString('pt-PT')} (${Math.abs(diffDays)} dias)`,
            step: 5,
            isCritical: true,
          });
        } else if (diffDays <= 90) {
          list.push({
            text: `Teste hidrostático cilindro (${inspectionData.cylinder?.serial || 'S/N'}) expira em ${diffDays} dias (${expDate.toLocaleDateString('pt-PT')})`,
            step: 5,
            isCritical: diffDays <= 30,
          });
        }
      }
    }

    // HRU Validade
    if (inspectionData.hruValidade || inspectionData.hruExpiry) {
      const hruDate = new Date(inspectionData.hruValidade || inspectionData.hruExpiry);
      if (!isNaN(hruDate.getTime())) {
        const diffTime = hruDate.getTime() - insDate.getTime();
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
        if (diffDays < 0) {
          list.push({ text: `HRU (${inspectionData.hruReference || 'S/R'}) expirado há ${Math.abs(diffDays)} dias`, step: 5, isCritical: true });
        } else if (diffDays <= 90) {
          list.push({ text: `HRU (${inspectionData.hruReference || 'S/R'}) expira em ${diffDays} dias`, step: 5, isCritical: diffDays <= 30 });
        }
      }
    } else {
      list.push({ text: 'HRU: referência ou validade não definidas', step: 5, isCritical: true });
    }

    // Step 6 Validations
    const testes = Object.values(inspectionData.testes || {});
    if (testes.includes('REPROVOU')) {
      list.push({ text: 'Existem testes operacionais/pressão que reprovararam.', step: 6, isCritical: true });
    }

    // Step 7 Validations - Reconciliação substituições vs orçamento
    const orcamentoLinhas = inspectionData.orcamento?.linhas || [];
    if (orcamentoLinhas.length > 0) {
      const substituidos = [
        ...Object.values(inspectionData.packItems || {}).filter((item: any) => Number(item.quantidade) > 0),
        ...(inspectionData.componentes || []).filter((comp: any) => comp.reference || comp.stockId),
      ];
      substituidos.forEach((sub: any) => {
        const ref = sub.referencia || sub.reference || sub.name;
        if (!ref) return;
        const qty = Number(sub.quantidade) || (sub.checklistName ? 1 : 1);
        const linha = orcamentoLinhas.find(
          (l: any) => l.referencia === ref || (l.stockId && String(l.stockId) === String(sub.stockId))
        );
        if (!linha) {
          list.push({ text: `${ref}: substituído no passo 4 mas sem linha correspondente no orçamento (passo 7).`, step: 7, isCritical: false });
        } else if (Number(linha.quantidade) !== qty) {
          list.push({ text: `${ref}: quantidade divergente entre substituições (${qty}) e orçamento (${Number(linha.quantidade)}).`, step: 7, isCritical: false });
        }
      });
    }

    return list;
  }, [inspectionData]);

  function formatMonthYearDisplay(val: string) {
    if (!val) return '—';
    const [y, m] = val.split('-').map(Number);
    return `${String(m).padStart(2, '0')}-${y}`;
  }

  const criticalCount = warnings.filter(w => w.isCritical).length;

  const buildSavePayload = (isFinal = false) => {
    const packSubstitutions = Object.values(inspectionData.packItems || {})
      .filter((item: any) => item.quantidade > 0)
      .map((item: any) => ({
        stockId: item.stockId || null,
        referencia: item.referencia,
        descricao: item.descricao || item.name,
        quantidade: item.quantidade,
        motivo: "Substituição Inspeção",
        validade: item.validade || null,
        codigoFabricante: item.codigoFabricante || null,
      }));

    const compSubstitutions = (inspectionData.componentes || [])
      .filter((comp: any) => comp.stockId || comp.reference) // Apenas os que têm referência preenchida
      .map((comp: any) => ({
        stockId: comp.stockId || null,
        referencia: comp.reference,
        descricao: comp.name || "Componente",
        quantidade: 1, // Componentes normais são 1 por 1
        motivo: "Substituição Inspeção",
        validade: comp.validade || null,
        codigoFabricante: null,
      }));

    const artigosSubstituidos = [...packSubstitutions, ...compSubstitutions];

    const testes = inspectionData.testes || {};
    const unit = testes.wpUnidadePressao === 'mbar' ? 'hpa' : (testes.wpUnidadePressao || 'hpa');

    const tIn = parseFloat(testes.wpTempInicio || '0');
    const tOut = parseFloat(testes.wpTempFim || '0');
    const pAtmIn = parseFloat(testes.wpPressaoAtmInicio || '0');
    const pAtmOut = parseFloat(testes.wpPressaoAtmFim || '0');
    
    const supIn = parseFloat(testes.wpCamaraSupInicio || '0');
    const supOut = parseFloat(testes.wpCamaraSupFim || '0');
    const infIn = parseFloat(testes.wpCamaraInfInicio || '0');
    const infOut = parseFloat(testes.wpCamaraInfFim || '0');

    const toMbar = (val: number) => {
      if (isNaN(val) || val <= 0) return NaN;
      if (unit === 'inhg') return val * 33.8638866667;
      if (unit === 'inh2o') return val * 2.490889;
      return val;
    };

    const fromMbar = (val: number) => {
      if (isNaN(val) || val <= 0) return NaN;
      if (unit === 'inhg') return val / 33.8638866667;
      if (unit === 'inh2o') return val / 2.490889;
      return val;
    };

    let supDropStr = "";
    let infDropStr = "";

    if (!isNaN(tIn) && !isNaN(tOut) && !isNaN(pAtmIn) && !isNaN(pAtmOut)) {
      const tempDelta = tOut - tIn;
      const baroDelta = pAtmOut - pAtmIn;
      const correctionTempMb = -(tempDelta * 4);
      const correctionBaroMb = baroDelta;
      const totalCorrectionMb = correctionTempMb + correctionBaroMb;

      if (!isNaN(supIn) && !isNaN(supOut)) {
        const startMb = toMbar(supIn);
        const endMb = toMbar(supOut);
        const correctedEndMb = endMb + totalCorrectionMb;
        const dropMb = Math.max(0, startMb - correctedEndMb);
        const percent = startMb > 0 ? (dropMb / startMb) * 100 : 0;
        supDropStr = isNaN(dropMb) ? "" : `${fromMbar(dropMb).toFixed(2)} ${unit} (${percent.toFixed(1)}%)`;
      }

      if (!isNaN(infIn) && !isNaN(infOut)) {
        const startMb = toMbar(infIn);
        const endMb = toMbar(infOut);
        const correctedEndMb = endMb + totalCorrectionMb;
        const dropMb = Math.max(0, startMb - correctedEndMb);
        const percent = startMb > 0 ? (dropMb / startMb) * 100 : 0;
        infDropStr = isNaN(dropMb) ? "" : `${fromMbar(dropMb).toFixed(2)} ${unit} (${percent.toFixed(1)}%)`;
      }
    }

    const ordemId = typeof window !== 'undefined' ? new URLSearchParams(window.location.search).get('ordemId') : null;

    return {
      // Identificação e Jangada Fields
      ...inspectionData,
      id: inspecaoId || undefined,
      shipId: shipId,
      raftId: jangadaId,
      navioNome: inspectionData.shipName || inspectionData.shipNameManual || null,
      shipNameManual: inspectionData.shipName || inspectionData.shipNameManual || null,
      jangadaSerial: inspectionData.serial || null,
      date: inspectionData.dataInspecao || new Date().toISOString().slice(0, 10),
      dataProxInspecao: inspectionData.dataProxInspecao || null,
      
      owner: inspectionData.owner || null,
      launchType: inspectionData.launchType || null,
      painterLength: inspectionData.painterLength || null,
      maxStowageHeight: inspectionData.maxStowageHeight || null,
      fabricType: inspectionData.fabricType || null,

      // Cilindros Fields
      cylinderSerial: inspectionData.cylinder?.serial || null,
      cylinderPesoBruto: inspectionData.cylinder?.pesoBruto || null,
      cylinderTara: inspectionData.cylinder?.tara || null,
      cylinderCo2: inspectionData.cylinder?.co2 || null,
      cylinderN2: inspectionData.cylinder?.n2 || null,
      cylinderDataTeste: inspectionData.cylinder?.dataTeste || null,
      cylinderDataProxTeste: inspectionData.cylinder?.dataProxTeste || null,
      
      // Testes
      testeWP: testes.testeWP || null,
      testeNAP: testes.testeNAP || null,
      testeFS: testes.testeFS || null,
      testeGI: testes.testeGI || null,
      testeDL: testes.testeDL || null,

      testeWPUnidadePressao: testes.wpUnidadePressao || null,
      testeWPHoraInicio: testes.wpHoraInicio || null,
      testeWPHoraFim: testes.wpHoraFim || null,
      testeWPTemperaturaInicial: testes.wpTempInicio || null,
      testeWPTemperaturaFinal: testes.wpTempFim || null,
      testeWPPressaoAtmosfericaInicial: testes.wpPressaoAtmInicio || null,
      testeWPPressaoAtmosfericaFinal: testes.wpPressaoAtmFim || null,
      testeWPCamaraSuperiorInicio: testes.wpCamaraSupInicio || null,
      testeWPCamaraSuperiorFim: testes.wpCamaraSupFim || null,
      testeWPCamaraSuperiorQueda: supDropStr || null,
      testeWPCamaraInferiorInicio: testes.wpCamaraInfInicio || null,
      testeWPCamaraInferiorFim: testes.wpCamaraInfFim || null,
      testeWPCamaraInferiorQueda: infDropStr || null,

      // Inspeção Fields
      status: isFinal ? (criticalCount > 0 ? "Condenada" : "Concluída") : "Draft",
      responsavel: inspectionData.responsavel || "Operador",
       applyStockMovements: isFinal,
       signatureBase64: inspectionData.signatureBase64 || null,
       clienteAssinaturaBase64: inspectionData.clienteAssinaturaBase64 || null,
       clienteNomeAssinatura: inspectionData.clienteNomeAssinatura || null,
       guiaTransporteUrl: inspectionData.guiaTransporteUrl || null,
       checklistSnapshot: inspectionData.checklist || {},
      artigosSubstituidos,
      orcamento: {
        linhas: (inspectionData.orcamento?.linhas || []).map((linha) => ({
          stockId: linha.stockId ?? null,
          referencia: linha.referencia || "",
          descricao: linha.descricao || "",
          quantidade: Number(linha.quantidade) || 0,
          precoUnitario: Number(linha.unitPrice) || 0,
          total: Math.round((Number(linha.quantidade) || 0) * (Number(linha.unitPrice) || 0) * 100) / 100,
          source: linha.source || "manual",
        })),
        valorMaoObra: 0,
        valorDesconto: Number(inspectionData.orcamento?.valorDesconto || 0),
        isIsentoIva: Boolean(inspectionData.orcamento?.isIsentoIva),
        usarOrcamento: Boolean(inspectionData.orcamento?.usarOrcamento),
        removedIds: inspectionData.orcamento?.removedIds || [],
      },
      ordemId: ordemId ? parseInt(ordemId, 10) : null,
    };
  };

  const saveToBackend = async (isFinal: boolean) => {
    try {
      setIsSaving(true);
      const payload = buildSavePayload(isFinal);

      if (typeof window !== 'undefined' && !window.navigator.onLine) {
        try {
          const method = inspecaoId ? 'PUT' : 'POST';
          const path = inspecaoId ? `/api/inspecoes?id=${inspecaoId}` : '/api/inspecoes';
          const queued = enqueueOfflineSyncOperation({
            path,
            method: method as 'PUT' | 'POST',
            body: payload,
            entityType: 'jangada-inspection',
            entityId: String(inspecaoId || jangadaId),
            summary: `Inspeção offline: ${inspectionData.serial || jangadaId}`,
          });

          if (queued) {
            appToast.warning("Sem ligação à internet. A inspeção foi enfileirada para sincronização automática.");
            if (isFinal) {
              setStep(9);
            }
          } else {
            appToast.error("Fila offline cheia. Não foi possível guardar a inspeção.");
          }
        } catch (err) {
          console.error("Erro ao enfileirar offline:", err);
          appToast.error("Ocorreu um erro ao guardar a inspeção localmente.");
        } finally {
          setIsSaving(false);
        }
        return;
      }

      // 1. Atualiza Jangada (testes, etc)
      if (jangadaId) {
        const jangadaPayload: Record<string, any> = {
          brand: inspectionData.brand,
          model: inspectionData.model,
          serial: inspectionData.serial,
          packType: inspectionData.packType,
          capacity: inspectionData.capacity,
          dataFabrico: inspectionData.dataFabrico,
          dataInspecao: inspectionData.dataInspecao,
          dataProxInspecao: inspectionData.dataProxInspecao,
          launchType: inspectionData.launchType,
          fabricType: inspectionData.fabricType,
          painterLength: inspectionData.painterLength,
          maxStowageHeight: inspectionData.maxStowageHeight,
          hruReferencia: inspectionData.hruReference,
          hruValidade: inspectionData.hruExpiry,
          radarReflector: inspectionData.radarReflector,
          radarReflectorValidade: inspectionData.radarReflectorExpiry,
          owner: inspectionData.owner,
          // Cylinder data
          cylinderSerial: inspectionData.cylinder?.serial,
          cylinderPesoBruto: inspectionData.cylinder?.pesoBruto,
          cylinderTara: inspectionData.cylinder?.tara,
          cylinderCo2: inspectionData.cylinder?.co2,
          cylinderN2: inspectionData.cylinder?.n2,
          cylinderDataTeste: inspectionData.cylinder?.dataTeste,
          cylinderDataProxTeste: inspectionData.cylinder?.dataProxTeste,
          // Test results
          testeWP: inspectionData.testes?.testeWP,
          testeNAP: inspectionData.testes?.testeNAP,
          testeGI: inspectionData.testes?.testeGI,
          testeFS: inspectionData.testes?.testeFS,
          testeDL: inspectionData.testes?.testeDL,
          // WP test details
          testeWPUnidadePressao: inspectionData.testes?.wpUnidadePressao,
          testeWPHoraInicio: inspectionData.testes?.wpHoraInicio,
          testeWPHoraFim: inspectionData.testes?.wpHoraFim,
          testeWPTemperaturaInicial: inspectionData.testes?.wpTempInicio,
          testeWPTemperaturaFinal: inspectionData.testes?.wpTempFim,
          testeWPPressaoAtmosfericaInicial: inspectionData.testes?.wpPressaoAtmInicio,
          testeWPPressaoAtmosfericaFinal: inspectionData.testes?.wpPressaoAtmFim,
          testeWPCamaraSuperiorInicio: inspectionData.testes?.wpCamaraSupInicio,
          testeWPCamaraSuperiorFim: inspectionData.testes?.wpCamaraSupFim,
          testeWPCamaraInferiorInicio: inspectionData.testes?.wpCamaraInfInicio,
          testeWPCamaraInferiorFim: inspectionData.testes?.wpCamaraInfFim,
          testeWPInstrumento: inspectionData.testes?.wpManometroId,
          testeWPBarometro: inspectionData.testes?.wpBarometroId,
          // NAP test details
          testeNAPUnidadePressao: inspectionData.testes?.napUnidadePressao,
          testeNAPHoraInicio: inspectionData.testes?.napHoraInicio,
          testeNAPHoraFim: inspectionData.testes?.napHoraFim,
          testeNAPTemperaturaInicial: inspectionData.testes?.napTempInicio,
          testeNAPTemperaturaFinal: inspectionData.testes?.napTempFim,
          testeNAPPressaoAtmosfericaInicial: inspectionData.testes?.napPressaoAtmInicio,
          testeNAPPressaoAtmosfericaFinal: inspectionData.testes?.napPressaoAtmFim,
          testeNAPCamaraSuperiorInicio: inspectionData.testes?.napCamaraSupInicio,
          testeNAPCamaraSuperiorFim: inspectionData.testes?.napCamaraSupFim,
          testeNAPCamaraInferiorInicio: inspectionData.testes?.napCamaraInfInicio,
          testeNAPCamaraInferiorFim: inspectionData.testes?.napCamaraInfFim,
          testeNAPInstrumento: inspectionData.testes?.napManometroId,
        };

        const jangadaRes = await fetch(`/api/jangadas/${jangadaId}`, {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(jangadaPayload),
        });
        if (!jangadaRes.ok) {
          const errorJson = await jangadaRes.json().catch(() => ({}));
          throw new Error(errorJson.error || errorJson.message || `Erro ao atualizar dados da jangada (Código ${jangadaRes.status})`);
        }
      }

      // 2. Atualiza Navio se associado
      if (shipId) {
        try {
          const shipRes = await fetch(`/api/navios/${shipId}`, {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              proprietario: inspectionData.owner,
              bandeira: inspectionData.shipFlag,
              imo: inspectionData.shipImo,
              callSignal: inspectionData.shipCallSign,
            }),
          });
          if (!shipRes.ok) {
            console.warn("Erro ao atualizar dados do navio:", shipRes.status);
          }
        } catch (shipErr) {
          console.error("Erro ao atualizar dados do navio:", shipErr);
        }
      }

      // 3. Guarda / Finaliza Inspecao
      const method = inspecaoId ? "PUT" : "POST";
      const url = inspecaoId ? `/api/inspecoes?id=${inspecaoId}` : '/api/inspecoes';
      
      const inspRes = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      if (!inspRes.ok) throw new Error("Falha ao gravar inspeção");

      const savedInsp = await inspRes.json();
      if (savedInsp?.id) {
        setInspecaoId(savedInsp.id);
      }

      if (isFinal) {
        setStep(9);
      } else {
        appToast.success("Rascunho guardado com sucesso!");
      }
    } catch (error) {
      console.error(error);
      appToast.error("Ocorreu um erro ao gravar. Verifica a tua ligação.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleSaveDraft = () => {
    saveToBackend(false);
  };

  const handleFinish = () => {
    const criticalWarnings = warnings.filter(w => w.isCritical);
    if (criticalWarnings.length > 0) {
      const msg = `Atenção: Existem ${criticalWarnings.length} validações críticas:\n\n${criticalWarnings.map(w => `• ${w.text}`).join('\n')}\n\nA inspeção NÃO pode ser finalizada até corrigir estes itens.`;
      alert(msg);
      return;
    }
    saveToBackend(true);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-300">
      <div>
        <h2 className="text-2xl font-bold text-slate-800">8. Fecho & Resumo</h2>
        <p className="text-slate-600 mt-1">Valide os alertas automáticos antes de fechar e emitir o certificado.</p>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
        
        {/* Painel Central de Alertas */}
        <div className="xl:col-span-2 space-y-6">
          <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
            <div className="bg-slate-50 border-b border-slate-200 px-6 py-4 flex items-center gap-3">
              <ShieldAlert className="text-slate-500" size={20} />
              <h3 className="text-lg font-bold text-slate-800">Validação do Sistema</h3>
            </div>
            
            <div className="p-6">
              {warnings.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-8 text-center">
                  <div className="w-16 h-16 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mb-4">
                    <CheckCircle size={32} />
                  </div>
                  <h4 className="text-lg font-bold text-slate-800">Tudo Perfeito!</h4>
                  <p className="text-slate-500 mt-1 max-w-sm">
                    A inteligência do sistema não detetou falhas, validades em atraso ou itens reprovados. A jangada está pronta para ser certificada.
                  </p>
                </div>
              ) : (
                <div className="space-y-3">
                  {warnings.map((warning, idx) => (
                    <div 
                      key={idx} 
                      className={`flex items-start justify-between gap-4 p-4 rounded-xl border ${
                        warning.isCritical 
                          ? 'bg-red-50 border-red-200 text-red-900' 
                          : 'bg-amber-50 border-amber-200 text-amber-900'
                      }`}
                    >
                      <div className="flex items-start gap-3">
                        <AlertTriangle className={`shrink-0 mt-0.5 ${warning.isCritical ? 'text-red-500' : 'text-amber-500'}`} size={18} />
                        <div>
                          <p className="font-semibold text-sm">{warning.text}</p>
                          <p className={`text-xs mt-0.5 ${warning.isCritical ? 'text-red-700' : 'text-amber-700'}`}>
                            {warning.isCritical ? 'Ação Crítica Obrigatória' : 'Aviso Informativo'}
                          </p>
                        </div>
                      </div>
                      <button 
                        onClick={() => setStep(warning.step)}
                        className={`text-xs font-bold px-3 py-1.5 rounded-lg whitespace-nowrap transition-colors ${
                          warning.isCritical 
                            ? 'bg-red-100 hover:bg-red-200 text-red-800' 
                            : 'bg-amber-100 hover:bg-amber-200 text-amber-800'
                        }`}
                      >
                        Corrigir Passo {warning.step}
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Secção de Assinatura Digital */}
          <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden mt-6">
            <div className="bg-slate-50 border-b border-slate-200 px-6 py-4 flex items-center gap-3">
              <FileText className="text-slate-500" size={20} />
              <h3 className="text-lg font-bold text-slate-800">Assinatura Digital do Técnico</h3>
            </div>
            <div className="p-6 space-y-4">
              <div className="space-y-1.5 max-w-md">
                <label className="text-xs font-bold uppercase tracking-wider text-slate-500 font-semibold">Técnico Responsável pela Inspeção</label>
                <select
                  value={selectedTecnicoId}
                  onChange={(e) => {
                    const id = e.target.value;
                    setSelectedTecnicoId(id);
                    const tecnico = tecnicos.find(t => String(t.id) === String(id));
                    setInspectionData({ responsavel: tecnico?.nome || 'Operador' });
                  }}
                  className="w-full border-slate-200 rounded-xl px-3 py-2 bg-white text-sm focus:ring-2 focus:ring-indigo-100 font-medium text-slate-700"
                >
                  <option value="">-- Selecione o Técnico --</option>
                  {tecnicos.map(t => (
                    <option key={t.id} value={t.id}>{t.nome}</option>
                  ))}
                </select>
                {(() => {
                  const warning = checkTechnicianCertification();
                  if (warning) {
                    return (
                      <div className="text-xs font-semibold text-amber-700 flex items-center gap-1.5 mt-2 bg-amber-50 p-2 rounded-xl border border-amber-200">
                        <AlertTriangle size={16} className="shrink-0" />
                        <span>{warning}</span>
                      </div>
                    );
                  }
                  return null;
                })()}
              </div>

              <p className="text-sm text-slate-600">
                Por favor, assine digitalmente no quadro abaixo para validar esta inspeção e incluir a assinatura no dossier e certificados.
              </p>
              <SignatureCanvas 
                onChange={(base64) => setInspectionData({ signatureBase64: base64 ?? '' })} 
                initialValue={inspectionData.signatureBase64}
              />
            </div>
          </div>

          {/* Secǜo de Termo de Aceitao, Recibo de Entrega e Assinatura do Cliente / Comandante */}
          <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden mt-6">
            <div className="bg-slate-50 border-b border-slate-200 px-6 py-4 flex items-center gap-3">
              <CheckCircle className="text-emerald-600" size={20} />
              <h3 className="text-lg font-bold text-slate-800">Termo de Aceitaǜo & Recibo de Entrega (Cliente / Comandante)</h3>
            </div>
            <div className="p-6 space-y-4">
              <div className="space-y-1.5 max-w-md">
                <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Nome / Cargo do Comandante ou Representante</label>
                <input
                  type="text"
                  value={String((inspectionData as any).clienteNomeAssinatura || "")}
                  onChange={(e) => setInspectionData({ clienteNomeAssinatura: e.target.value })}
                  placeholder="Ex: Comandante João Silva / Agente Marítimo"
                  className="w-full border-slate-200 rounded-xl px-3 py-2 bg-white text-sm focus:ring-2 focus:ring-indigo-100 font-medium text-slate-700"
                />
              </div>

              <div>
                <label className="block text-xs font-bold uppercase tracking-wider text-slate-500 mb-1">Guia de Transporte / Conhecimento de Embarque do Transitrio (Opcional)</label>
                <div className="flex items-center gap-3 max-w-md">
                  <label className="flex-1 flex items-center justify-center gap-2 px-4 py-2.5 border-2 border-dashed border-slate-300 hover:border-indigo-500 rounded-xl cursor-pointer bg-slate-50 hover:bg-indigo-50/30 transition-all text-xs font-bold text-slate-600">
                    <FileText size={16} className="text-indigo-600" />
                    <span>{inspectionData.guiaTransporteUrl ? "Substituir Guia / PDF" : "Carregar Guia de Transporte (PDF/Foto)"}</span>
                    <input
                      type="file"
                      accept="application/pdf,image/*"
                      className="hidden"
                      onChange={async (e) => {
                        const file = e.target.files?.[0];
                        if (!file) return;
                        try {
                          const fd = new FormData();
                          fd.append("file", file);
                          fd.append("categoria", "documentos");
                          const res = await fetch("/api/upload-documento", {
                            method: "POST",
                            body: fd,
                          });
                          const json = await res.json();
                          if (!res.ok) throw new Error(json.error || "Erro no upload");
                          const fileUrl = json.url || json.path || json.fileUrl;
                          if (fileUrl) {
                            setInspectionData({ guiaTransporteUrl: fileUrl });
                            appToast.success("Guia de transporte carregada com sucesso!");
                          }
                        } catch (err: unknown) {
                          appToast.error(err instanceof Error ? err.message : "Erro ao carregar guia");
                        }
                      }}
                    />
                  </label>
                </div>
                {Boolean((inspectionData as any).guiaTransporteUrl) && (
                  <div className="mt-2 flex items-center justify-between p-2.5 bg-emerald-50 border border-emerald-200 rounded-xl max-w-md">
                    <a href={String((inspectionData as any).guiaTransporteUrl || "")} target="_blank" rel="noopener noreferrer" className="text-xs font-bold text-emerald-800 hover:underline flex items-center gap-1.5 truncate">
                      <CheckCircle size={14} className="shrink-0 text-emerald-600" />
                      <span className="truncate">Ver Guia de Transporte Carregada</span>
                    </a>
                    <button
                      type="button"
                      onClick={() => setInspectionData({ guiaTransporteUrl: "" })}
                      className="text-xs text-red-600 hover:text-red-800 font-semibold ml-2 shrink-0"
                    >
                      Remover
                    </button>
                  </div>
                )}
              </div>

              <p className="text-sm text-slate-600 pt-2">
                Assinatura do cliente ou representante a confirmar a aceitação da revisão e recibo de entrega da jangada:
              </p>
              <SignatureCanvas 
                onChange={(base64) => setInspectionData({ clienteAssinaturaBase64: base64 ?? '' })} 
                initialValue={String((inspectionData as any).clienteAssinaturaBase64 || "")}
              />
            </div>
          </div>
        </div>

        {/* Barra Lateral de Resumo Rápido */}
        <div className="space-y-6">
          <div className="bg-gradient-to-br from-indigo-900 to-indigo-950 rounded-2xl p-6 text-white shadow-md">
            <h3 className="text-sm font-bold uppercase tracking-wider text-indigo-300 mb-6">Raio-X da Jangada</h3>
            
            <div className="space-y-5">
              <div className="flex items-center gap-4">
                <div className="bg-white/10 p-2.5 rounded-xl text-white">
                  <Anchor size={20} />
                </div>
                <div>
                  <p className="text-xs text-indigo-200 font-medium uppercase tracking-wider mb-0.5">Identificação</p>
                  <p className="font-semibold">{inspectionData.serial || 'Sem Série'}</p>
                  <p className="text-xs text-indigo-100">{inspectionData.brand || 'Sem Marca'} - {inspectionData.model || 'Sem Modelo'}</p>
                </div>
              </div>

              <div className="flex items-center gap-4">
                <div className="bg-white/10 p-2.5 rounded-xl text-white">
                  <FileText size={20} />
                </div>
                <div>
                  <p className="text-xs text-indigo-200 font-medium uppercase tracking-wider mb-0.5">Configuração</p>
                  <p className="font-semibold">{inspectionData.packType || 'Sem Pack'}</p>
                  <p className="text-xs text-indigo-100">{inspectionData.capacity ? `${inspectionData.capacity} Pessoas` : 'S/ Capacidade'}</p>
                </div>
              </div>

              <div className="flex items-center gap-4">
                <div className="bg-white/10 p-2.5 rounded-xl text-white">
                  <CheckCircle size={20} />
                </div>
                <div>
                  <p className="text-xs text-indigo-200 font-medium uppercase tracking-wider mb-0.5">Estado</p>
                  <p className="font-semibold text-emerald-300">Em Rascunho</p>
                  <p className="text-xs text-indigo-100">Próx. Insp: {formatDateDisplay(inspectionData.dataProxInspecao, '?')}</p>
                </div>
              </div>

              {(() => {
                const orcLinhas = inspectionData.orcamento?.linhas || [];
                if (orcLinhas.length === 0 && !inspectionData.orcamento?.usarOrcamento) return null;
                const orcSubtotal = orcLinhas.reduce((s: number, l: any) => s + (Number(l.quantidade) || 0) * (Number(l.unitPrice) || 0), 0);
                const orcDesconto = Number(inspectionData.orcamento?.valorDesconto || 0);
                const orcBase = Math.max(0, orcSubtotal - orcDesconto);
                const orcIsento = Boolean(inspectionData.orcamento?.isIsentoIva);
                const orcIva = calcIva(orcBase, orcIsento);
                const orcTotal = round2(orcBase + orcIva);
                return (
                  <div className="flex items-start gap-4">
                    <div className="bg-white/10 p-2.5 rounded-xl text-white">
                      <FileText size={20} />
                    </div>
                    <div className="flex-1">
                      <p className="text-xs text-indigo-200 font-medium uppercase tracking-wider mb-0.5">Orçamento (Passo 7)</p>
                      <p className="font-semibold">{orcLinhas.length} linha(s) · {new Intl.NumberFormat('pt-PT', { style: 'currency', currency: 'EUR' }).format(orcTotal)}</p>
                      <p className="text-xs text-indigo-100">
                        Subtotal: {new Intl.NumberFormat('pt-PT', { style: 'currency', currency: 'EUR' }).format(orcBase)}
                        {!orcIsento && ` · IVA (${(getIvaRate() * 100).toFixed(0)}%): ${new Intl.NumberFormat('pt-PT', { style: 'currency', currency: 'EUR' }).format(orcIva)}`}
                        {orcIsento && ' · Isento de IVA'}
                      </p>
                    </div>
                  </div>
                );
              })()}
            </div>

            <hr className="border-indigo-800 my-6" />

            <div className="flex gap-3">
              <button 
                onClick={handleSaveDraft}
                disabled={isSaving}
                className="w-1/3 py-4 rounded-xl font-bold flex items-center justify-center gap-2 transition-all bg-white/10 hover:bg-white/20 text-white"
              >
                {isSaving ? "A Gravar..." : "Guardar Rascunho"}
              </button>

              <button 
                onClick={handleFinish}
                disabled={isSaving}
                className={`w-2/3 py-4 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${
                  criticalCount === 0 
                    ? 'bg-emerald-500 hover:bg-emerald-600 text-white shadow-lg shadow-emerald-500/30' 
                    : 'bg-amber-500 hover:bg-amber-600 text-white shadow-lg shadow-amber-500/30'
                }`}
              >
                <Save size={20} />
                {isSaving ? "A Processar..." : (criticalCount === 0 ? 'Fechar Inspeção e Gravar' : 'Finalizar com Falhas (Condenada)')}
              </button>
            </div>
            {criticalCount > 0 && (
              <p className="text-center text-xs mt-3 text-amber-200">Existem falhas que reprovam a jangada</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";
import React, { useState } from 'react';
import { useJangadaWizardStore } from './store/useJangadaWizardStore';
import { CheckCircle, Download, FileText, Loader2, ArrowRight } from 'lucide-react';
import { useRouter } from 'next/navigation';
import { getMandatoryPackItemsForRaft } from '../rafts/mandatoryPack';

export default function Step9_Certificados() {
  const router = useRouter();
  const { inspectionData, jangadaId, shipId, inspecaoId } = useJangadaWizardStore();
  const [loading, setLoading] = useState<string | null>(null);
  const [previewHtml, setPreviewHtml] = useState<string | null>(null);

  const buildCertificatePayload = () => {
    const testes = inspectionData.testes || {};
    const mandatoryItems = getMandatoryPackItemsForRaft({
      brand: inspectionData.brand,
      model: inspectionData.model,
      packType: inspectionData.packType,
      capacity: inspectionData.capacity as number,
    });

    const artigosSubstituidos = Object.values(inspectionData.packItems || {})
      .filter((item: any) => item.quantidade > 0)
      .map((item: any) => {
        const mand = mandatoryItems.find((m: any) => m.checklistName === item.checklistName);
        return {
          stockId: item.stockId || null,
          referencia: item.referencia,
          descricao: item.descricao || item.name || mand?.label || item.checklistName || 'Artigo',
          quantidade: item.quantidade,
          validade: item.validade || null,
        };
      });

    // Build checklist for quadro template with article references, quantities, validities, and explicit replacement keys
    const buildQuadroChecklist = () => {
      const checklist: Record<string, any> = {
        ...(inspectionData.checklist || {}),
        ...(inspectionData.testes || {})
      };

      const normalizeText = (text: string) => {
        return text.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
      };

      const findPackItem = (tokens: string[]) => {
        return Object.values(inspectionData.packItems || {}).find((item: any) => {
          const nameNorm = normalizeText(item.descricao || item.name || '');
          return tokens.every(token => nameNorm.includes(normalizeText(token)));
        });
      };

      const findMandatoryItem = (tokens: string[]) => {
        return mandatoryItems.find((item: any) => {
          const nameNorm = normalizeText(item.label || '');
          return tokens.every(token => nameNorm.includes(normalizeText(token)));
        });
      };

      const mapItem = (tokens: string[], refKey?: string, valKey?: string, qtyKey?: string, statusKey?: string, loteKey?: string, explicitReplacementKey?: string) => {
        const packItem = findPackItem(tokens);
        const mandItem = findMandatoryItem(tokens);
        
        // Use packItem (replacement data) if available, otherwise use mandatory item reference
        const referencia = packItem?.referencia || mandItem?.stockReferences?.[0] || '';
        const quantidade = packItem?.quantidade || mandItem?.quantity || 0;
        const validade = packItem?.validade || '';
        const lote = packItem?.lote || '';
        
        if (referencia && refKey) checklist[refKey] = referencia;
        if (validade && valKey) {
          const valStr = String(validade);
          if (valStr.includes('T')) {
            checklist[valKey] = valStr.slice(0, 7);
          } else {
            checklist[valKey] = valStr;
          }
        }
        if (quantidade > 0 && qtyKey) checklist[qtyKey] = quantidade;
        if (statusKey) checklist[statusKey] = 'YES';
        if (lote && loteKey) {
          const loteStr = String(lote).trim();
          checklist[loteKey] = loteStr.toUpperCase().startsWith('LOTE') ? loteStr : `LOTE ${loteStr}`;
        }
        if (explicitReplacementKey && quantidade > 0) {
          checklist[explicitReplacementKey] = quantidade;
        }
      };

      mapItem(['farmacia'], 'ref_farmacia', 'validade_farmacia', 'qtd_farmacia', 'ambulancia', 'lote_farmacia', 'substituicao_explicita__farmacia');
      if (!checklist.ref_farmacia) mapItem(['ambulancia'], 'ref_farmacia', 'validade_farmacia', 'qtd_farmacia', 'ambulancia', 'lote_farmacia', 'substituicao_explicita__farmacia');
      if (!checklist.ref_farmacia) mapItem(['first', 'aid'], 'ref_farmacia', 'validade_farmacia', 'qtd_farmacia', 'ambulancia', 'lote_farmacia', 'substituicao_explicita__farmacia');
      if (!checklist.ref_farmacia) mapItem(['socorros'], 'ref_farmacia', 'validade_farmacia', 'qtd_farmacia', 'ambulancia', 'lote_farmacia', 'substituicao_explicita__farmacia');

      mapItem(['comprimido'], 'ref_comprimidos', 'validade_comprimidos', 'qtd_comprimidos', 'comprimidos_enjoo', 'lote_comprimidos', 'substituicao_explicita__comprimidos_p_enjoo');
      if (!checklist.ref_comprimidos) mapItem(['pastilha'], 'ref_comprimidos', 'validade_comprimidos', 'qtd_comprimidos', 'comprimidos_enjoo', 'lote_comprimidos', 'substituicao_explicita__comprimidos_p_enjoo');
      if (!checklist.ref_comprimidos) mapItem(['enjoo'], 'ref_comprimidos', 'validade_comprimidos', 'qtd_comprimidos', 'comprimidos_enjoo', 'lote_comprimidos', 'substituicao_explicita__comprimidos_p_enjoo');
      if (!checklist.ref_comprimidos) mapItem(['seasick'], 'ref_comprimidos', 'validade_comprimidos', 'qtd_comprimidos', 'comprimidos_enjoo', 'lote_comprimidos', 'substituicao_explicita__comprimidos_p_enjoo');
      if (!checklist.ref_comprimidos) mapItem(['tables'], 'ref_comprimidos', 'validade_comprimidos', 'qtd_comprimidos', 'comprimidos_enjoo', 'lote_comprimidos', 'substituicao_explicita__comprimidos_p_enjoo');

      mapItem(['paraquedas'], 'ref_paraquedas', 'validade_paraquedas', 'qtd_paraquedas', 'foguetoes_paraquedas', 'lote_paraquedas', 'substituicao_explicita__foguetes_paraquedas');
      if (!checklist.ref_paraquedas) mapItem(['parachute'], 'ref_paraquedas', 'validade_paraquedas', 'qtd_paraquedas', 'foguetoes_paraquedas', 'lote_paraquedas', 'substituicao_explicita__foguetes_paraquedas');
      if (!checklist.ref_paraquedas) mapItem(['rocket'], 'ref_paraquedas', 'validade_paraquedas', 'qtd_paraquedas', 'foguetoes_paraquedas', 'lote_paraquedas', 'substituicao_explicita__foguetes_paraquedas');

      mapItem(['facho'], 'ref_fachos', 'validade_fachos_mao', 'qtd_fachos', 'fachos_mao', 'lote_fachos', 'substituicao_explicita__fachos_de_mao');
      if (!checklist.ref_fachos) mapItem(['handflare'], 'ref_fachos', 'validade_fachos_mao', 'qtd_fachos', 'fachos_mao', 'lote_fachos', 'substituicao_explicita__fachos_de_mao');
      if (!checklist.ref_fachos) mapItem(['handflares'], 'ref_fachos', 'validade_fachos_mao', 'qtd_fachos', 'fachos_mao', 'lote_fachos', 'substituicao_explicita__fachos_de_mao');

      mapItem(['fumo'], 'ref_potes', 'validade_potes_fumo', 'qtd_potes', 'potes_fumo', 'lote_potes', 'substituicao_explicita__potes_de_fumo');
      if (!checklist.ref_potes) mapItem(['smoke'], 'ref_potes', 'validade_potes_fumo', 'qtd_potes', 'potes_fumo', 'lote_potes', 'substituicao_explicita__potes_de_fumo');
      if (!checklist.ref_potes) mapItem(['fumigeno'], 'ref_potes', 'validade_potes_fumo', 'qtd_potes', 'potes_fumo', 'lote_potes', 'substituicao_explicita__potes_de_fumo');
      if (!checklist.ref_potes) mapItem(['fumígeno'], 'ref_potes', 'validade_potes_fumo', 'qtd_potes', 'potes_fumo', 'lote_potes', 'substituicao_explicita__potes_de_fumo');

      mapItem(['lanterna'], 'ref_lanterna', 'validade_lanterna', 'qtd_lanterna', 'lanterna', 'lote_lanterna');
      if (!checklist.ref_lanterna) mapItem(['torch'], 'ref_lanterna', 'validade_lanterna', 'qtd_lanterna', 'lanterna', 'lote_lanterna');

      mapItem(['pilha'], 'ref_bateria', 'validade_pilhas_lanterna', 'qtd_pilhas_lanterna', 'pilhas_lanterna', 'lote_bateria', 'substituicao_explicita__pilhas_para_lanterna');
      if (!checklist.ref_bateria) mapItem(['torch', 'batter'], 'ref_bateria', 'validade_pilhas_lanterna', 'qtd_pilhas_lanterna', 'pilhas_lanterna', 'lote_bateria', 'substituicao_explicita__pilhas_para_lanterna');

      mapItem(['bateria', 'litio'], 'ref_bateria_litio', 'validade_bateria', 'qtd_bateria_litio', 'bateria_litio', 'lote_bateria_litio');
      if (!checklist.ref_bateria_litio) mapItem(['bateria', 'lítio'], 'ref_bateria_litio', 'validade_bateria', 'qtd_bateria_litio', 'bateria_litio', 'lote_bateria_litio');
      if (!checklist.ref_bateria_litio) mapItem(['bateria', 'lithium'], 'ref_bateria_litio', 'validade_bateria', 'qtd_bateria_litio', 'bateria_litio', 'lote_bateria_litio');

      mapItem(['cinta', 'fecho'], 'ref_cinta_fecho', undefined, 'qtd_cinta_fecho', 'cinta_fecho');
      if (!checklist.ref_cinta_fecho) mapItem(['bursting', 'band'], 'ref_cinta_fecho', undefined, 'qtd_cinta_fecho', 'cinta_fecho');
      if (!checklist.ref_cinta_fecho) mapItem(['bursting', 'tape'], 'ref_cinta_fecho', undefined, 'qtd_cinta_fecho', 'cinta_fecho');

      mapItem(['jogo', 'repara'], 'ref_jogo_reparacao', undefined, 'qtd_jogo_reparacao', 'jogo_reparacao');
      if (!checklist.ref_jogo_reparacao) mapItem(['repair', 'kit'], 'ref_jogo_reparacao', undefined, 'qtd_jogo_reparacao', 'jogo_reparacao');

      mapItem(['luz', 'ext'], undefined, 'validade_luzes_exteriores', undefined, 'luz_exterior_bateria');
      mapItem(['luz', 'int'], undefined, 'validade_bateria', undefined, 'luz_interior_bateria');

      mapItem(['agua'], 'ref_agua', 'validade_agua', undefined, 'saco_agua');
      if (!checklist.ref_agua) mapItem(['água'], 'ref_agua', 'validade_agua', undefined, 'saco_agua');
      if (!checklist.ref_agua) mapItem(['water'], 'ref_agua', 'validade_agua', undefined, 'saco_agua');

      mapItem(['racao'], 'ref_racoes', 'validade_racoes', undefined, 'racoes_alimentares');
      if (!checklist.ref_racoes) mapItem(['ração'], 'ref_racoes', 'validade_racoes', undefined, 'racoes_alimentares');
      if (!checklist.ref_racoes) mapItem(['racoes'], 'ref_racoes', 'validade_racoes', undefined, 'racoes_alimentares');
      if (!checklist.ref_racoes) mapItem(['rações'], 'ref_racoes', 'validade_racoes', undefined, 'racoes_alimentares');
      if (!checklist.ref_racoes) mapItem(['ration'], 'ref_racoes', 'validade_racoes', undefined, 'racoes_alimentares');
      if (!checklist.ref_racoes) mapItem(['food'], 'ref_racoes', 'validade_racoes', undefined, 'racoes_alimentares');

      return checklist;
    };

    const rawUnit = testes.wpUnidadePressao || testes.testeWPUnidadePressao || 'hpa';
    const unit = rawUnit === 'mbar' ? 'hpa' : rawUnit;

    const tIn = parseFloat(testes.wpTempInicio || testes.testeWPTemperaturaInicial || '0');
    const tOut = parseFloat(testes.wpTempFim || testes.testeWPTemperaturaFinal || '0');
    const pAtmIn = parseFloat(testes.wpPressaoAtmInicio || testes.testeWPPressaoAtmosfericaInicial || '0');
    const pAtmOut = parseFloat(testes.wpPressaoAtmFim || testes.testeWPPressaoAtmosfericaFinal || '0');
    
    const supIn = parseFloat(testes.wpCamaraSupInicio || testes.testeWPCamaraSuperiorInicio || '0');
    const supOut = parseFloat(testes.wpCamaraSupFim || testes.testeWPCamaraSuperiorFim || '0');
    const infIn = parseFloat(testes.wpCamaraInfInicio || testes.testeWPCamaraInferiorInicio || '0');
    const infOut = parseFloat(testes.wpCamaraInfFim || testes.testeWPCamaraInferiorFim || '0');

    const toMbar = (val: number) => {
      if (isNaN(val) || val <= 0) return NaN;
      if (unit === 'inhg') return val * 33.8638866667;
      if (unit === 'inh2o') return val * 2.490889;
      return val;
    };

    const fromMbar = (val: number) => {
      if (isNaN(val) || val <= 0) return NaN;
      if (unit === 'inhg') return val / 33.8638866667;
      if (unit === 'inh2o') return val / 2.490889;
      return val;
    };

    let wpUpperCorrected: string | number = '';
    let wpUpperDrop: string | number = '';
    let wpUpperDropPercent: string | number = '';
    let wpLowerCorrected: string | number = '';
    let wpLowerDrop: string | number = '';
    let wpLowerDropPercent: string | number = '';

    if (!isNaN(tIn) && !isNaN(tOut) && !isNaN(pAtmIn) && !isNaN(pAtmOut)) {
      const tempDelta = tOut - tIn;
      const baroDelta = pAtmOut - pAtmIn;
      const correctionTempMb = -(tempDelta * 4);
      const correctionBaroMb = baroDelta;
      const totalCorrectionMb = correctionTempMb + correctionBaroMb;

      if (!isNaN(supIn) && !isNaN(supOut)) {
        const startMb = toMbar(supIn);
        const endMb = toMbar(supOut);
        const correctedEndMb = endMb + totalCorrectionMb;
        const dropMb = Math.max(0, startMb - correctedEndMb);
        const percent = startMb > 0 ? (dropMb / startMb) * 100 : 0;
        wpUpperCorrected = isNaN(correctedEndMb) ? '' : Number(fromMbar(correctedEndMb).toFixed(2));
        wpUpperDrop = isNaN(dropMb) ? '' : Number(fromMbar(dropMb).toFixed(2));
        wpUpperDropPercent = isNaN(percent) ? '' : Number(percent.toFixed(2));
      }

      if (!isNaN(infIn) && !isNaN(infOut)) {
        const startMb = toMbar(infIn);
        const endMb = toMbar(infOut);
        const correctedEndMb = endMb + totalCorrectionMb;
        const dropMb = Math.max(0, startMb - correctedEndMb);
        const percent = startMb > 0 ? (dropMb / startMb) * 100 : 0;
        wpLowerCorrected = isNaN(correctedEndMb) ? '' : Number(fromMbar(correctedEndMb).toFixed(2));
        wpLowerDrop = isNaN(dropMb) ? '' : Number(fromMbar(dropMb).toFixed(2));
        wpLowerDropPercent = isNaN(percent) ? '' : Number(percent.toFixed(2));
      }
    }

    return {
      id: jangadaId,
      inspectionId: inspecaoId,
      certNumber: inspectionData.certificadoNumero || '',
      numeroObra: inspectionData.numeroObra || '',
      inspectionDate: inspectionData.dataInspecao || new Date().toISOString().slice(0, 10),
      nextInspectionDate: inspectionData.dataProxInspecao || '',
      shipName: inspectionData.shipName || inspectionData.shipNameManual || 'Sem navio',
      brand: inspectionData.brand || '',
      raftModel: inspectionData.model || '',
      raftCapacity: String(inspectionData.capacity || ''),
      raftSerial: inspectionData.serial || '',
      manufactureDate: inspectionData.dataFabrico || '',
      packType: inspectionData.packType || '',
      
      owner: inspectionData.owner || '',
      shipFlag: inspectionData.shipFlag || '',
      shipImo: inspectionData.shipImo || '',
      shipCallSign: inspectionData.shipCallSign || '',
      launchType: inspectionData.launchType || '',
      fabricType: inspectionData.fabricType || '',
      painterLength: inspectionData.painterLength || '',
      maxStowageHeight: inspectionData.maxStowageHeight || '',
      cylinderHydroTestDate: inspectionData.cylinder?.dataTeste || '',
      hruReference: inspectionData.hruReference || '',
      hruExpiry: inspectionData.hruExpiry || '',
      radarReflector: inspectionData.radarReflector || '',
      radarReflectorExpiry: inspectionData.radarReflectorExpiry || '',

      cylinderSerial: inspectionData.cylinder?.serial || '',
      cylinderGrossWeight: inspectionData.cylinder?.pesoBruto || '',
      cylinderTare: inspectionData.cylinder?.tara || '',
      cylinderCo2: inspectionData.cylinder?.co2 || '',
      cylinderN2: inspectionData.cylinder?.n2 || '',

      pressureUnit: unit,
      tempInitial: testes.wpTempInicio || testes.testeWPTemperaturaInicial || '',
      tempFinal: testes.wpTempFim || testes.testeWPTemperaturaFinal || '',
      baroInitial: testes.wpPressaoAtmInicio || testes.testeWPPressaoAtmosfericaInicial || '',
      baroFinal: testes.wpPressaoAtmFim || testes.testeWPPressaoAtmosfericaFinal || '',
      wpStartTime: testes.wpHoraInicio || testes.testeWPHoraInicio || '',
      wpEndTime: testes.wpHoraFim || testes.testeWPHoraFim || '',
      wpUpperStart: testes.wpCamaraSupInicio || testes.testeWPCamaraSuperiorInicio || '',
      wpUpperEnd: testes.wpCamaraSupFim || testes.testeWPCamaraSuperiorFim || '',
      wpUpperCorrected,
      wpUpperDrop,
      wpUpperDropPercent,
      wpLowerStart: testes.wpCamaraInfInicio || testes.testeWPCamaraInferiorInicio || '',
      wpLowerEnd: testes.wpCamaraInfFim || testes.testeWPCamaraInferiorFim || '',
      wpLowerCorrected,
      wpLowerDrop,
      wpLowerDropPercent,

      napTestDone: inspectionData.testes?.teste_nap || testes.testeNAP || 'NAO',
      fsTestDone: inspectionData.testes?.teste_fs || testes.testeFS || 'NAO',
      giTestDone: inspectionData.testes?.teste_gi || testes.testeGI || 'NAO',
      loadTestDone: inspectionData.testes?.teste_dl || testes.testeDL || 'NAO',
      
      status: 'Concluída',
      checklist: buildQuadroChecklist(),
      artigosSubstituidos,
      substituicoes: artigosSubstituidos,
    };
  };

  const handleGenerate = async (type: 'orey-html' | 'orey-xlsx' | 'survitec' | 'quadro-xlsx') => {
    setLoading(type);
    setPreviewHtml(null);
    try {
      const payload = buildCertificatePayload();
      let url = '';
      
      if (type === 'orey-html') url = '/api/certificados/orey?format=html';
      if (type === 'orey-xlsx') url = '/api/certificados/orey?format=xlsx';
      if (type === 'survitec') url = '/api/certificados/survitec-moderno';
      if (type === 'quadro-xlsx') url = '/api/exportar-raft';

      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });

      if (!response.ok) throw new Error('Falha ao gerar certificado');

      if (type === 'orey-xlsx' || type === 'quadro-xlsx') {
        const blob = await response.blob();
        const downloadUrl = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = downloadUrl;

        let fileName = response.headers.get("Content-Disposition")?.match(/filename="?([^";]+)"?/)?.[1];
        if (!fileName) {
          if (type === 'quadro-xlsx') {
            const rawDate = inspectionData.inspectionDate || payload.inspectionDate || new Date().toISOString();
            const inspectionDate = new Date(rawDate as string);
            const month = String(inspectionDate.getMonth() + 1).padStart(2, '0');
            const year = inspectionDate.getFullYear();
            const monthYear = `${month} ${year}`;

            const serial = inspectionData.serial || '';
            const model = inspectionData.model || '';
            const rawCap = inspectionData.capacity || '';
            const capMatch = String(rawCap).match(/\d+/);
            const capacity = capMatch ? `${Number(capMatch[0])}P` : String(rawCap).trim();

            fileName = `${serial} ${model} ${capacity} (${monthYear}).xlsx`;
          } else {
            fileName = `Certificado_Orey_${inspectionData.serial}.xlsx`;
          }
        }

        a.download = fileName;
        document.body.appendChild(a);
        a.click();
        a.remove();
        window.URL.revokeObjectURL(downloadUrl);
      } else {
        const data = await response.json();
        setPreviewHtml(data.html);
      }
    } catch (error) {
      console.error(error);
      alert('Erro ao gerar certificado. Verifique a consola.');
    } finally {
      setLoading(null);
    }
  };

  const handleDownloadPreview = () => {
    if (!previewHtml) return;
    const blob = new Blob([previewHtml], { type: 'text/html;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `Certificado_${inspectionData.serial}.html`;
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
  };

  return (
    <div className="space-y-8 animate-in fade-in zoom-in-95 duration-500">
      <div className="text-center space-y-4 py-8">
        <div className="w-20 h-20 bg-emerald-100 text-emerald-500 rounded-full flex items-center justify-center mx-auto mb-6 ring-8 ring-emerald-50">
          <CheckCircle size={40} className="animate-bounce" />
        </div>
        <h2 className="text-3xl font-extrabold text-slate-800 tracking-tight">Inspeção Submetida!</h2>
        <p className="text-slate-500 max-w-md mx-auto text-lg">
          A jangada <span className="font-bold text-slate-700">{inspectionData.serial}</span> foi atualizada e os consumos de stock aplicados com sucesso.
        </p>
      </div>

      <div className="bg-white border border-slate-200 rounded-3xl p-8 shadow-sm">
        <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
          <FileText className="text-indigo-500" />
          Emissão de Certificados
        </h3>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <button 
            onClick={() => handleGenerate('orey-xlsx')}
            disabled={loading !== null}
            className="flex flex-col items-center justify-center gap-3 p-6 rounded-2xl border-2 border-emerald-100 bg-emerald-50 hover:bg-emerald-100 hover:border-emerald-200 transition-all text-emerald-700 font-bold"
          >
            {loading === 'orey-xlsx' ? <Loader2 className="animate-spin" size={32} /> : <Download size={32} />}
            <span>Exportar Excel</span>
            <span className="text-xs font-medium text-emerald-400">Certificado .xlsx</span>
          </button>

          <button 
            onClick={() => handleGenerate('quadro-xlsx')}
            disabled={loading !== null}
            className="flex flex-col items-center justify-center gap-3 p-6 rounded-2xl border-2 border-blue-100 bg-blue-50 hover:bg-blue-100 hover:border-blue-200 transition-all text-blue-700 font-bold"
          >
            {loading === 'quadro-xlsx' ? <Loader2 className="animate-spin" size={32} /> : <FileText size={32} />}
            <span>Quadro Inspeção</span>
            <span className="text-xs font-medium text-blue-400">Tabela de Dados</span>
          </button>
        </div>
      </div>

      {previewHtml && (
        <div className="bg-white border border-slate-200 rounded-3xl overflow-hidden shadow-xl animate-in slide-in-from-bottom-8">
          <div className="bg-slate-800 px-6 py-4 flex items-center justify-between">
            <h3 className="text-white font-bold flex items-center gap-2">
              Visualização Prévia do Certificado
            </h3>
            <button 
              onClick={handleDownloadPreview}
              className="px-4 py-2 bg-indigo-500 hover:bg-indigo-600 text-white rounded-lg font-bold text-sm flex items-center gap-2 transition-colors"
            >
              <Download size={16} />
              Transferir HTML
            </button>
          </div>
          <div className="p-0 bg-slate-100 relative h-[800px] overflow-auto">
            <iframe 
              srcDoc={previewHtml} 
              className="w-full h-full bg-white scale-95 origin-top mt-4 rounded-xl shadow-sm border border-slate-200"
            />
          </div>
        </div>
      )}

      <div className="flex justify-center pt-8">
        <button 
          onClick={() => router.push('/jangadas')}
          className="px-8 py-4 bg-slate-800 hover:bg-slate-900 text-white rounded-xl font-bold flex items-center gap-3 transition-transform hover:scale-105"
        >
          Voltar para a Lista de Jangadas
          <ArrowRight size={20} />
        </button>
      </div>
    </div>
  );
}

import { create } from 'zustand';
import { devtools } from 'zustand/middleware';
import { getLocalDateKey } from '@/lib/date-utils';
import type { InspectionData, GlobalStockItem } from '../types';

export type { GlobalStockItem } from '../types';

type WizardState = {
  // Navigation
  currentStep: number;
  setStep: (step: number) => void;
  nextStep: () => void;
  prevStep: () => void;
  canProceed: () => boolean;
  validationErrors: string[];
  clearValidationErrors: () => void;
  
  // Data Payload
  jangadaId: number | null;
  shipId: number | null;
  inspecaoId: number | null;
  inspecoes: any[];
  setJangadaId: (id: number | null) => void;
  setShipId: (id: number | null) => void;
  setInspecaoId: (id: number | null) => void;
  
  inspectionData: InspectionData;
  setInspectionData: (data: Partial<InspectionData>) => void;
  
  // Global Stock
  globalStock: GlobalStockItem[];
  setGlobalStock: (stock: GlobalStockItem[]) => void;
  
  // Initialize from Backend
  initializeWizard: (raftData: any, draftData?: any) => void;
  
  // Saving Status
  isSaving: boolean;
  setIsSaving: (isSaving: boolean) => void;
  
  // Auto-save
  lastSaved: Date | null;
  setLastSaved: (date: Date) => void;
  isDirty: boolean;
  setIsDirty: (dirty: boolean) => void;
};

export const useJangadaWizardStore = create<WizardState>()(
  devtools(
    (set, get) => ({
      currentStep: 1,
      setStep: (step) => set({ currentStep: step }),
      nextStep: () => {
        const state = get();
        if (state.canProceed()) {
          set({ currentStep: Math.min(state.currentStep + 1, 10), validationErrors: [] });
        }
      },
      prevStep: () => set((state) => ({ currentStep: Math.max(state.currentStep - 1, 1), validationErrors: [] })),
      
      canProceed: () => {
        const state = get();
        const data = state.inspectionData;
        const step = state.currentStep;
        const errors: string[] = [];

        if (step === 1) {
          if (!data.serial?.trim()) errors.push("Série é obrigatória");
          if (!data.brand?.trim()) errors.push("Marca é obrigatória");
          if (!data.model?.trim()) errors.push("Modelo é obrigatório");
          if (!data.packType?.trim()) errors.push("Tipo de pack é obrigatório");
          if (!data.capacity) errors.push("Capacidade é obrigatória");
        }

        if (step === 6) {
          if (data.testes?.testeWP === 'PASSOU') {
            if (!data.testes?.wpCamaraSupInicio) errors.push("Pressão Câmara Superior (Início) é obrigatória para teste WP");
            if (!data.testes?.wpCamaraSupFim) errors.push("Pressão Câmara Superior (Fim) é obrigatória para teste WP");
          }
        }

        set({ validationErrors: errors });
        return errors.length === 0;
      },
      
      validationErrors: [],
      clearValidationErrors: () => set({ validationErrors: [] }),
      
      jangadaId: null,
      shipId: null,
      inspecaoId: null,
      inspecoes: [],
      setJangadaId: (id) => set({ jangadaId: id }),
      setShipId: (id) => set({ shipId: id }),
      setInspecaoId: (id) => set({ inspecaoId: id }),
      
      inspectionData: {} as InspectionData,
      setInspectionData: (data) => set((state) => ({ 
        inspectionData: { ...state.inspectionData, ...data },
        isDirty: true,
      })),

      globalStock: [],
      setGlobalStock: (stock) => set({ globalStock: stock }),
      
      initializeWizard: (raftData, draftData) => {
        // Here we map backend Raft model fields into the inspectionData
        // We also map the draftData if an inspection is already in progress
        const initialData: any = {
          // Identificação
          brand: raftData?.brand || '',
          model: raftData?.model || '',
          serial: raftData?.serial || '',
          packType: raftData?.packType || '',
          capacity: raftData?.capacity || '',
          dataFabrico: raftData?.dataFabrico || '',
          dataInspecao: draftData?.dataInspecao || raftData?.dataInspecao || getLocalDateKey(),
          dataProxInspecao: draftData?.dataProxInspecao || raftData?.dataProxInspecao || '',
          shipName: draftData?.navioNome || raftData?.shipNameManual || raftData?.shipDetails?.nome || '',
          
          owner: raftData?.shipDetails?.proprietario || raftData?.ownerDisplay || raftData?.owner || '',
          shipFlag: raftData?.shipDetails?.bandeira || '',
          shipImo: raftData?.shipDetails?.imo || '',
          shipCallSign: raftData?.shipDetails?.callSignal || '',
          launchType: raftData?.launchType || '',
          fabricType: raftData?.fabricType || '',
          painterLength: raftData?.painterLength || '',
          maxStowageHeight: raftData?.maxStowageHeight || '',
          hruReference: raftData?.hruReferencia || '',
          hruExpiry: raftData?.hruValidade || '',
          radarReflector: raftData?.radarReflector || '',
          radarReflectorExpiry: raftData?.radarReflectorValidade || '',
          artigos: raftData?.artigos || [],
          shipDetails: raftData?.shipDetails || null,

          // Cilindro Base
          cylinder: {
            serial: raftData?.cylinderSerial || '',
            pesoBruto: raftData?.cylinderPesoBruto || '',
            tara: raftData?.cylinderTara || '',
            co2: raftData?.cylinderCo2 || '',
            n2: raftData?.cylinderN2 || '',
            dataTeste: raftData?.cylinderDataTeste || '',
            dataProxTeste: raftData?.cylinderDataProxTeste || '',
          },

          // Testes Base
          testes: {
            ...raftData,
            wpUnidadePressao: raftData?.testeWPUnidadePressao || 'hpa',
            wpManometroId: raftData?.testeWPManometroId || '',
            wpBarometroId: raftData?.testeWPBarometroId || '',
            wpHoraInicio: raftData?.testeWPHoraInicio || '',
            wpHoraFim: raftData?.testeWPHoraFim || '',
            wpTempInicio: raftData?.testeWPTemperaturaInicial || '',
            wpTempFim: raftData?.testeWPTemperaturaFinal || '',
            wpPressaoAtmInicio: raftData?.testeWPPressaoAtmosfericaInicial || '',
            wpPressaoAtmFim: raftData?.testeWPPressaoAtmosfericaFinal || '',
            wpCamaraSupInicio: raftData?.testeWPCamaraSuperiorInicio || '',
            wpCamaraSupFim: raftData?.testeWPCamaraSuperiorFim || '',
            wpCamaraInfInicio: raftData?.testeWPCamaraInferiorInicio || '',
            wpCamaraInfFim: raftData?.testeWPCamaraInferiorFim || '',
            // NAP parameters
            napUnidadePressao: raftData?.testeNAPUnidadePressao || 'hpa',
            napManometroId: raftData?.testeNAPManometroId || '',
            napHoraInicio: raftData?.testeNAPHoraInicio || '',
            napHoraFim: raftData?.testeNAPHoraFim || '',
            napTempInicio: raftData?.testeNAPTemperaturaInicial || '',
            napTempFim: raftData?.testeNAPTemperaturaFinal || '',
            napPressaoAtmInicio: raftData?.testeNAPPressaoAtmosfericaInicial || '',
            napPressaoAtmFim: raftData?.testeNAPPressaoAtmosfericaFinal || '',
            napCamaraSupInicio: raftData?.testeNAPCamaraSuperiorInicio || '',
            napCamaraSupFim: raftData?.testeNAPCamaraSuperiorFim || '',
            napCamaraInfInicio: raftData?.testeNAPCamaraInferiorInicio || '',
            napCamaraInfFim: raftData?.testeNAPCamaraInferiorFim || '',
          },
          
          // Checklist
          checklist: draftData?.checklistSnapshot || {},
          
          // Pack Substituído
          packItems: draftData?.artigosSubstituidos?.reduce((acc: any, item: any) => {
            if (item.referencia) {
               acc[item.referencia] = item;
            }
            return acc;
          }, {}) || {},

          // Orçamento (restaurado a partir do rascunho guardado)
          orcamento: draftData?.orcamento || undefined,
        };
        
        set({
          jangadaId: raftData?.id || null,
          shipId: draftData?.navioId || raftData?.shipId || null,
          inspecaoId: draftData?.id || null,
          inspecoes: raftData?.inspecoes || [],
          inspectionData: { ...initialData }
        });
      },
      
      isSaving: false,
      setIsSaving: (isSaving) => set({ isSaving }),
      
      lastSaved: null,
      setLastSaved: (date) => set({ lastSaved: date, isDirty: false }),
      isDirty: false,
      setIsDirty: (dirty) => set({ isDirty: dirty }),
    }),
    { name: 'JangadaWizardStore' }
  )
);

"use client";
import { useEffect, useState, useCallback } from "react";


type InspecaoResumo = {
  id: number;
  navioNome?: string;
  marca?: string;
  modelo?: string;
  serial?: string;
  dataInspecao?: string;
  responsavel?: string;
  artigos?: Array<{ name: string; quantidade: number; referencia?: string }>;
};

type Navio = {
  id: number;
  nome: string;
};

export default function Reports() {
  const [inspecoes, setInspecoes] = useState<InspecaoResumo[]>([]);
  const [navios, setNavios] = useState<Navio[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState({
    start: "",
    end: "",
    ship: "",
    brand: "",
  });

  // Carregar dados da API (em vez de localStorage)
  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const [inspecoesRes, naviosRes] = await Promise.all([
        fetch("/api/inspecoes"),
        fetch("/api/navios"),
      ]);

      if (inspecoesRes.ok) {
        const data = await inspecoesRes.json();
        setInspecoes(Array.isArray(data) ? data : []);
      }
      if (naviosRes.ok) {
        const data = await naviosRes.json();
        setNavios(Array.isArray(data) ? data : []);
      }
    } catch (error) {
      console.error("Erro ao carregar dados para relatórios:", error);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  // Filtro
  const filtered = inspecoes.filter((insp) => {
    const data = insp.dataInspecao || "";
    const afterStart = !filter.start || data >= filter.start;
    const beforeEnd = !filter.end || data <= filter.end;
    const byShip = !filter.ship || String(insp.navioNome ?? "").toLowerCase().includes(String(filter.ship ?? "").toLowerCase());
    const byBrand = !filter.brand || String(insp.marca ?? "").toLowerCase().includes(String(filter.brand ?? "").toLowerCase());
    return afterStart && beforeEnd && byShip && byBrand;
  });

  // Consumo de artigos
  const artigosConsumo: Record<string, { total: number; jangadas: number }> = {};
  filtered.forEach((insp) => {
    (insp.artigos || []).forEach((a) => {
      if (!artigosConsumo[a.name]) artigosConsumo[a.name] = { total: 0, jangadas: 0 };
      artigosConsumo[a.name].total += Number(a.quantidade || 0);
      artigosConsumo[a.name].jangadas += 1;
    });
  });

  async function exportarPDF() {
    const { default: jsPDF } = await import("jspdf");
    const { default: autoTable } = await import("jspdf-autotable");
    const doc = new jsPDF();
    doc.setFontSize(16);
    doc.text("Relatório de Consumo de Artigos", 14, 18);
    doc.setFontSize(11);
    doc.text(`Período: ${filter.start || '-'} a ${filter.end || '-'}`, 14, 28);
    doc.text(`Navio: ${filter.ship || 'Todos'}`, 14, 34);
    doc.text(`Marca: ${filter.brand || 'Todas'}`, 14, 40);
    doc.text(`Total inspeções no período: ${filtered.length}`, 14, 46);
    autoTable(doc, {
      head: [["Artigo", "Total Consumido", "Jangadas"]],
      body: Object.entries(artigosConsumo)
        .sort((a, b) => b[1].total - a[1].total)
        .map(([nome, info]) => [nome, info.total, info.jangadas]),
      startY: 54,
      styles: { fontSize: 9 },
      headStyles: { fillColor: [41, 128, 185] },
    });
    doc.save("relatorio_consumo_artigos.pdf");
  }

  const marcasUnicas = [...new Set(inspecoes.map(i => i.marca).filter(Boolean))];

  return (
    <div className="max-w-3xl mx-auto p-4">
      <h1 className="text-2xl font-bold mb-4">Relatório de Consumo de Artigos</h1>

      <div className="flex flex-wrap gap-3 mb-4">
        <label className="flex flex-col text-xs">Início
          <input type="date" value={filter.start} onChange={e => setFilter(f => ({ ...f, start: e.target.value }))} className="border rounded p-1" />
        </label>
        <label className="flex flex-col text-xs">Fim
          <input type="date" value={filter.end} onChange={e => setFilter(f => ({ ...f, end: e.target.value }))} className="border rounded p-1" />
        </label>
        <label className="flex flex-col text-xs">Navio
          <select value={filter.ship} onChange={e => setFilter(f => ({ ...f, ship: e.target.value }))} className="border rounded p-1">
            <option value="">Todos</option>
            {navios.map((s) => <option key={s.id} value={s.nome}>{s.nome}</option>)}
          </select>
        </label>
        <label className="flex flex-col text-xs">Marca
          <select value={filter.brand} onChange={e => setFilter(f => ({ ...f, brand: e.target.value }))} className="border rounded p-1">
            <option value="">Todas</option>
            {marcasUnicas.map((m) => <option key={m} value={m}>{m}</option>)}
          </select>
        </label>
        <button className="bg-blue-600 text-white px-3 py-1 rounded text-xs self-end hover:bg-blue-700 transition-colors" onClick={exportarPDF}>
          Exportar PDF
        </button>
      </div>

      {/* KPI cards */}
      <div className="grid grid-cols-3 gap-3 mb-4">
        <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 text-center">
          <div className="text-2xl font-bold text-blue-700">{filtered.length}</div>
          <div className="text-xs text-blue-600">Inspeções no Período</div>
        </div>
        <div className="bg-green-50 border border-green-200 rounded-lg p-3 text-center">
          <div className="text-2xl font-bold text-green-700">{Object.keys(artigosConsumo).length}</div>
          <div className="text-xs text-green-600">Artigos Distintos</div>
        </div>
        <div className="bg-amber-50 border border-amber-200 rounded-lg p-3 text-center">
          <div className="text-2xl font-bold text-amber-700">
            {Object.values(artigosConsumo).reduce((sum, info) => sum + info.total, 0)}
          </div>
          <div className="text-xs text-amber-600">Total Consumido</div>
        </div>
      </div>

      {loading ? (
        <div className="text-center text-gray-400 py-8">A carregar dados da base de dados...</div>
      ) : (
        <table className="min-w-full text-xs border mb-4">
          <thead>
            <tr className="bg-gray-100">
              <th className="p-2 text-left">Artigo</th>
              <th className="p-2 text-right">Total Consumido</th>
              <th className="p-2 text-right">Jangadas</th>
            </tr>
          </thead>
          <tbody>
            {Object.entries(artigosConsumo)
              .sort((a, b) => b[1].total - a[1].total)
              .map(([nome, info]) => (
              <tr key={nome} className="border-t hover:bg-gray-50">
                <td className="p-2">{nome}</td>
                <td className="p-2 text-right font-mono">{info.total}</td>
                <td className="p-2 text-right font-mono">{info.jangadas}</td>
              </tr>
            ))}
            {Object.keys(artigosConsumo).length === 0 && (
              <tr><td colSpan={3} className="text-center text-gray-400 p-2">Nenhum consumo encontrado.</td></tr>
            )}
          </tbody>
        </table>
      )}
    </div>
  );
}

"use client";
/**
 * LEGADO — não usar em fluxos novos.
 * Catálogo operacional: /stock + Prisma model Stock.
 * Este módulo mantém o modelo local `Artigo` apenas por compatibilidade.
 */
// Módulo de Estoque de Artigos (legacy)
import { useEffect, useState } from "react";
import { DRINKING_WATER_STOCK_REFERENCE } from "../lib/stock-reference-rules";
import { BELLOWS_STOCK_REFERENCE } from "../lib/stock-reference-rules";
import { uuidv4 } from "../utils/uuid";


// Corrigido: Padronização do tipo principal
export type ArtigoStock = {
  id?: string;
  name: string;
  descricao?: string;
  type?: string;
  code?: string;
  referencia?: string;
  precoVenda?: number;
  quantity?: number | string;
  unit?: string;
  stock: number;
  minStock: number;
};
const DEFAULT_ARTIGOS: ArtigoStock[] = [
  { name: "Fachos de Mão", stock: 0, minStock: 3, unit: "un", referencia: "", precoVenda: 0 },
  { name: "Foguetes Paraquedas", stock: 0, minStock: 2, unit: "un", referencia: "", precoVenda: 0 },
  { name: "Sinal Fumígeno Flutuante", stock: 0, minStock: 1, unit: "un", referencia: "", precoVenda: 0 },
  { name: "Fogos de Mão", stock: 0, minStock: 1, unit: "un", referencia: "", precoVenda: 0 },
  { name: "Lanterna Estanque", stock: 0, minStock: 1, unit: "un", referencia: "", precoVenda: 0 },
  { name: "Espelho de Sinalização", stock: 0, minStock: 1, unit: "un", referencia: "", precoVenda: 0 },
  { name: "Apito de Sobrevivência", stock: 0, minStock: 1, unit: "un", referencia: "", precoVenda: 0 },
  { name: "Pastilhas para Enjoo", stock: 0, minStock: 6, unit: "un/pax", referencia: "", precoVenda: 0 },
  { name: "Saco para Enjoo", stock: 0, minStock: 1, unit: "un/pax", referencia: "", precoVenda: 0 },
  { name: "Esponja", stock: 0, minStock: 2, unit: "un", referencia: "", precoVenda: 0 },
  { name: "Vertedouro (Bailer)", stock: 0, minStock: 1, unit: "un", referencia: "", precoVenda: 0 },
  { name: "Âncora Flutuante", stock: 0, minStock: 1, unit: "un", referencia: "", precoVenda: 0 },
  { name: "Remos Flutuantes", stock: 0, minStock: 2, unit: "un", referencia: "", precoVenda: 0 },
  { name: "Faca Flutuante", stock: 0, minStock: 1, unit: "un", referencia: "", precoVenda: 0 },
  { name: "Kit de Reparação", stock: 0, minStock: 1, unit: "kit", referencia: "", precoVenda: 0 },
  { name: "Bellows", stock: 0, minStock: 1, unit: "un", referencia: BELLOWS_STOCK_REFERENCE, precoVenda: 0 },
  { name: "Manta Térmica (TPA)", stock: 0, minStock: 1, unit: "un", referencia: "", precoVenda: 0 },
  { name: "Rações (2400 kcal)", stock: 0, minStock: 1, unit: "un/pax", referencia: "", precoVenda: 0 },
  { name: "Água potável", stock: 0, minStock: 1, unit: "lt/pax", referencia: DRINKING_WATER_STOCK_REFERENCE, precoVenda: 0 },
  { name: "Tubo de Identificação", stock: 0, minStock: 1, unit: "un", referencia: "", precoVenda: 0 },
];

export default function Stock() {
  const [articles, setArticles] = useState<ArtigoStock[]>(() => {
    try {
      const stored = localStorage.getItem("articles");
      if (stored && JSON.parse(stored).length > 0) {
        return JSON.parse(stored);
      }
      // Seed automático: artigos do checklist/quadro de inspeção
      let checklistArticles: string[] = [];
      try {
        const { inspectionChecklist } = require("./inspectionChecklist");
        type ChecklistSection = { title?: string; fields?: Array<{ label?: string }> };
        const sections: ChecklistSection[] = Array.isArray(inspectionChecklist) ? inspectionChecklist : [];
        // Extrai todos os labels da seção 'Equipamentos e Artigos'
        const eqSection = sections.find((s) => s.title === "Equipamentos e Artigos");
        if (eqSection) {
          checklistArticles = (eqSection.fields ?? [])
            .map((f) => f.label)
            .filter((label): label is string => Boolean(label));
        }
      } catch {}
      // Adiciona também os DEFAULT_ARTIGOS
      const allArticles = [
        ...DEFAULT_ARTIGOS,
        ...checklistArticles.map((name) => ({ name, stock: 0, minStock: 1, unit: "un", id: uuidv4() }))
      ];
      localStorage.setItem("articles", JSON.stringify(allArticles));
      return allArticles;
    } catch {
      return DEFAULT_ARTIGOS;
    }
  });
  const [form, setForm] = useState<ArtigoStock>({ name: "", descricao: "", stock: 0, minStock: 1, unit: "un" });
  const [search, setSearch] = useState("");
  const [filterType, setFilterType] = useState("");
  const [showModal, setShowModal] = useState(false);
  const [quickItem, setQuickItem] = useState<ArtigoStock>({ name: "", descricao: "", type: "", code: "", referencia: "", precoVenda: 0, quantity: "", unit: "un", stock: 0, minStock: 1 });
  // Estados de modais de ação (devem estar fora do useState do auditLog)
  const [editModal, setEditModal] = useState<{open: boolean, item?: ArtigoStock}>({open: false});
  const [viewModal, setViewModal] = useState<{open: boolean, item?: ArtigoStock}>({open: false});
  const [auditLog, setAuditLog] = useState<Array<{ action: string; item: ArtigoStock; timestamp: number }>>(() => {
    try {
      return JSON.parse(localStorage.getItem("auditStock") || "[]");
    } catch { return []; }
  });

  useEffect(() => {
    localStorage.setItem("articles", JSON.stringify(articles));
  }, [articles]);

  function addAudit(action: string, item: ArtigoStock) {
    const entry = { action, item, timestamp: Date.now() };
    setAuditLog((prev) => {
      const updated = [...prev, entry];
      localStorage.setItem("auditStock", JSON.stringify(updated));
      return updated;
    });
  }

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    const resolvedName = (form.name || form.descricao || form.referencia || "Sem nome").trim();
    const newItem = { ...form, name: resolvedName, id: uuidv4() };
    setArticles(prev => {
      const updated = [...prev, newItem];
      // Autosave no backend
      fetch("/api/artigos", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newItem),
      });
      return updated;
    });
    addAudit("Adicionado", newItem);
    setForm({ name: "", descricao: "", stock: 0, minStock: 1, unit: "un" });
  }

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    setForm(prev => ({
      ...prev,
      [name]: type === "number" ? Number(value) : value
    }));
  };

  const handleQuickItemChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    setQuickItem(prev => ({ ...prev, [name]: type === 'number' ? Number(value) : value }));
  };

  const handleQuickItemSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const resolvedName = (quickItem.name || quickItem.descricao || quickItem.referencia || "Sem nome").trim();
    const newItem: ArtigoStock = {
      id: uuidv4(),
      name: resolvedName,
      descricao: quickItem.descricao,
      type: quickItem.type,
      code: quickItem.code,
      referencia: quickItem.referencia,
      precoVenda: Number(quickItem.precoVenda) || 0,
      quantity: quickItem.quantity,
      unit: quickItem.unit || "un",
      stock: Number(quickItem.stock) || Number(quickItem.quantity) || 0,
      minStock: Number(quickItem.minStock) || 1,
    };
    const updatedArticles = [...articles, newItem];
    setArticles(updatedArticles);
    // Autosave no backend
    fetch("/api/artigos", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(newItem),
    });
    addAudit("Cadastro rápido", newItem);
    setShowModal(false);
    setQuickItem({ name: "", descricao: "", type: "", code: "", quantity: "", unit: "un", stock: 0, minStock: 1 });
  };

  // Backup/restauração
  const handleBackup = () => {
    const data = { articles, auditLog };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `backup_estoque_${Date.now()}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleRestore = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const data = JSON.parse(ev.target?.result as string);
        if (data.articles) {
          setArticles(data.articles);
          localStorage.setItem("articles", JSON.stringify(data.articles));
        }
        if (data.auditLog) {
          setAuditLog(data.auditLog);
          localStorage.setItem("auditStock", JSON.stringify(data.auditLog));
        }
      } catch {}
    };
    reader.readAsText(file);
  };

  // Importar CSV
  const handleImportCSV = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const XLSX = await import("xlsx");
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      const data = XLSX.read(ev.target?.result, { type: "binary" });
      const sheet = data.Sheets[data.SheetNames[0]];
      const rows = XLSX.utils.sheet_to_json<Record<string, unknown>>(sheet);
      const importedArticles: ArtigoStock[] = rows.map((r) => ({
        id: uuidv4(),
        descricao: String(r.descricao ?? r.Descricao ?? ""),
        name: String(r.name ?? r.Nome ?? r.descricao ?? r.Descricao ?? "Sem nome"),
        type: String(r.type ?? r.Tipo ?? ""),
        code: String(r.code ?? r.Codigo ?? ""),
        referencia: String(r.referencia ?? r.Referencia ?? ""),
        precoVenda: Number(r.precoVenda ?? r.Preco ?? 0) || 0,
        quantity: (r.quantity ?? r.Quantidade ?? "") as number | string,
        unit: String(r.unit ?? r.Unidade ?? "un"),
        stock: Number(r.stock ?? r.Estoque ?? r.quantity ?? r.Quantidade) || 0,
        minStock: Number(r.minStock ?? r.Minimo ?? 1),
      }));
      const updatedArticles = [...articles, ...importedArticles];
      setArticles(updatedArticles);
      localStorage.setItem("articles", JSON.stringify(updatedArticles));
    };
    reader.readAsBinaryString(file);
  };

  // Alerta visual para artigos abaixo do mínimo
  const lowStockArticles = articles.filter(a => a.stock < a.minStock);
  return (
    <div className="max-w-2xl mx-auto px-2 sm:px-4">
      <h2 className="text-2xl font-bold mb-4">Lista de Itens de Estoque</h2>
      {lowStockArticles.length > 0 && (
        <div className="mb-4 p-3 bg-red-100 border border-red-400 text-red-700 rounded">
          <strong>Alerta:</strong> Os seguintes artigos estão abaixo do estoque mínimo:
          <ul className="list-disc ml-6">
            {lowStockArticles.map(a => (
              <li key={a.id || a.name}>{a.name} (Estoque: {a.stock}, Mínimo: {a.minStock})</li>
            ))}
          </ul>
        </div>
      )}
      <form onSubmit={handleSubmit} className="flex flex-wrap gap-2 mb-4 items-center">
        <input name="descricao" value={form.descricao || ''} onChange={handleChange} placeholder="Descrição do artigo" className="border rounded p-2" />
        <input name="name" value={form.name} onChange={handleChange} placeholder="Nome (opcional)" className="border rounded p-2" />
        <input name="referencia" value={form.referencia || ''} onChange={handleChange} placeholder="Referência" className="border rounded p-2 w-36" />
        <input name="precoVenda" type="number" step="0.01" value={form.precoVenda || 0} onChange={handleChange} placeholder="Preço venda" className="border rounded p-2 w-32" />
        <input name="stock" type="number" value={form.stock} onChange={handleChange} placeholder="Estoque" className="border rounded p-2 w-24" required />
        <input name="minStock" type="number" value={form.minStock} onChange={handleChange} placeholder="Mínimo" className="border rounded p-2 w-24" required />
        <select name="unit" value={form.unit} onChange={handleChange} className="border rounded p-2">
          <option value="un">un</option>
          <option value="lt">lt</option>
          <option value="kit">kit</option>
        </select>
        <button type="submit" className="bg-blue-700 text-white rounded p-2">Adicionar</button>
      </form>
      <h3 className="text-xl font-semibold mb-2">Itens de Estoque</h3>
      <div className="overflow-x-auto">
        <table className="min-w-full bg-white rounded shadow mb-2 text-xs sm:text-sm">
          <thead>
            <tr className="bg-blue-100">
              <th className="p-2 whitespace-nowrap">Descrição</th>
              <th className="p-2 whitespace-nowrap">Tipo</th>
              <th className="p-2 whitespace-nowrap">Código</th>
              <th className="p-2 whitespace-nowrap">Referência</th>
              <th className="p-2 whitespace-nowrap">Preço</th>
              <th className="p-2 whitespace-nowrap">Quantidade</th>
              <th className="p-2 whitespace-nowrap">Unidade</th>
              <th className="p-2 whitespace-nowrap">Estoque</th>
              <th className="p-2 whitespace-nowrap">Mínimo</th>
            </tr>
          </thead>
          <tbody>
            {articles.filter(i =>
              (!filterType || i.type === filterType) &&
              (!search ||
                i.name.toLowerCase().includes(search.toLowerCase()) ||
                (i.descricao && i.descricao.toLowerCase().includes(search.toLowerCase())) ||
                (i.type && i.type.toLowerCase().includes(search.toLowerCase())) ||
                (i.code && i.code.toLowerCase().includes(search.toLowerCase()))
              )
            ).map((i) => (
              <tr key={i.id} className="border-t align-top">
                <td className="p-2 whitespace-nowrap">{i.descricao || i.name}</td>
                <td className="p-2 whitespace-nowrap">{i.type}</td>
                <td className="p-2 whitespace-nowrap">{i.code}</td>
                <td className="p-2 whitespace-nowrap">{i.referencia || ""}</td>
                <td className="p-2 whitespace-nowrap">{i.precoVenda ? Number(i.precoVenda).toFixed(2) : ''}</td>
                <td className="p-2 whitespace-nowrap">{i.quantity}</td>
                <td className="p-2 whitespace-nowrap">{i.unit}</td>
                <td className="p-2 whitespace-nowrap">{i.stock}</td>
                <td className="p-2 whitespace-nowrap">{i.minStock}</td>
                <td className="p-2 whitespace-nowrap">
                  <div className="flex gap-1">
                    <button className="bg-blue-500 hover:bg-blue-700 text-white px-2 py-1 rounded text-xs" title="Visualizar" onClick={() => setViewModal({open:true, item:i})}>👁️</button>
                    <button className="bg-yellow-500 hover:bg-yellow-600 text-white px-2 py-1 rounded text-xs" title="Editar" onClick={() => setEditModal({open:true, item:i})}>✏️</button>
                    <button className="bg-red-500 hover:bg-red-700 text-white px-2 py-1 rounded text-xs" title="Excluir" onClick={() => {
                      if(window.confirm('Confirma exclusão?')) {
                        setArticles(prev => prev.filter(a => a.id !== i.id));
                        addAudit('Excluído', i);
                        fetch(`/api/artigos/${i.id}`, {method:'DELETE'});
                      }
                    }}>🗑️</button>
                    <button className="bg-green-500 hover:bg-green-700 text-white px-2 py-1 rounded text-xs" title="Exportar" onClick={() => {
                      const blob = new Blob([JSON.stringify(i, null, 2)], {type:'application/json'});
                      const url = URL.createObjectURL(blob);
                      const a = document.createElement('a');
                      a.href = url;
                      a.download = `artigo_${i.id}.json`;
                      a.click();
                      URL.revokeObjectURL(url);
                    }}>⬇️</button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <button
        className="bg-blue-600 text-white px-4 py-2 rounded mb-4"
        onClick={() => setShowModal(true)}
      >
        Cadastro rápido
      </button>
      {showModal && (
        <>
              {/* Modal de Visualizar */}
              {viewModal.open && viewModal.item && (
                <div className="fixed inset-0 bg-black bg-opacity-40 flex items-center justify-center z-50">
                  <div className="bg-white p-6 rounded shadow-lg w-full max-w-md">
                    <h3 className="text-lg font-bold mb-4">Detalhes do Artigo</h3>
                    <ul className="mb-4">
                      <li><b>Nome:</b> {viewModal.item.name}</li>
                      <li><b>Descrição:</b> {viewModal.item.descricao || '-'}</li>
                      <li><b>Tipo:</b> {viewModal.item.type}</li>
                      <li><b>Código:</b> {viewModal.item.code}</li>
                      <li><b>Quantidade:</b> {viewModal.item.quantity}</li>
                      <li><b>Unidade:</b> {viewModal.item.unit}</li>
                      <li><b>Estoque:</b> {viewModal.item.stock}</li>
                      <li><b>Mínimo:</b> {viewModal.item.minStock}</li>
                    </ul>
                    <div className="flex gap-2 justify-end">
                      <button className="px-4 py-2 bg-gray-300 rounded" onClick={() => setViewModal({open:false})}>Fechar</button>
                    </div>
                  </div>
                </div>
              )}
              {/* Modal de Editar */}
              {editModal.open && editModal.item && (
                <div className="fixed inset-0 bg-black bg-opacity-40 flex items-center justify-center z-50">
                  <div className="bg-white p-6 rounded shadow-lg w-full max-w-md">
                    <h3 className="text-lg font-bold mb-4">Editar Artigo</h3>
                    <form onSubmit={e => {
                      e.preventDefault();
                      if (!editModal.item) return;
                      const updatedItem: ArtigoStock = {
                        ...editModal.item,
                        name: (editModal.item.name || editModal.item.descricao || editModal.item.referencia || "Sem nome").trim(),
                        type: editModal.item.type ?? "",
                        code: editModal.item.code ?? "",
                        quantity: editModal.item.quantity ?? "",
                        unit: editModal.item.unit ?? "un",
                        stock: Number(editModal.item.stock) || 0,
                        minStock: Number(editModal.item.minStock) || 1
                      };
                      setArticles(prev => prev.map(a => a.id === updatedItem.id ? updatedItem : a));
                      addAudit('Editado', updatedItem);
                      fetch(`/api/artigos/${updatedItem.id}`, {
                        method: 'PUT',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify(updatedItem),
                      });
                      setEditModal({open:false});
                    }} className="space-y-3">
                      <input name="descricao" value={editModal.item.descricao || ''} onChange={e => setEditModal(m => ({...m, item: {...m.item!, descricao: e.target.value}}))} className="border rounded px-2 py-1 w-full" placeholder="Descrição" />
                      <input name="name" value={editModal.item.name} onChange={e => setEditModal(m => ({...m, item: {...m.item!, name: e.target.value}}))} className="border rounded px-2 py-1 w-full" placeholder="Nome (opcional)" />
                      <input name="type" value={editModal.item.type || ''} onChange={e => setEditModal(m => ({...m, item: {...m.item!, type: e.target.value}}))} className="border rounded px-2 py-1 w-full" placeholder="Tipo" />
                      <input name="code" value={editModal.item.code || ''} onChange={e => setEditModal(m => ({...m, item: {...m.item!, code: e.target.value}}))} className="border rounded px-2 py-1 w-full" placeholder="Código" />
                      <input name="quantity" type="number" value={editModal.item.quantity || ''} onChange={e => setEditModal(m => ({...m, item: {...m.item!, quantity: e.target.value}}))} className="border rounded px-2 py-1 w-full" placeholder="Quantidade" />
                      <select name="unit" value={editModal.item.unit || 'un'} onChange={e => setEditModal(m => ({...m, item: {...m.item!, unit: e.target.value}}))} className="border rounded px-2 py-1 w-full">
                        <option value="un">un</option>
                        <option value="lt">lt</option>
                        <option value="kit">kit</option>
                      </select>
                      <input name="stock" type="number" value={editModal.item.stock} onChange={e => setEditModal(m => ({...m, item: {...m.item!, stock: Number(e.target.value)}}))} className="border rounded px-2 py-1 w-full" placeholder="Estoque" />
                      <input name="minStock" type="number" value={editModal.item.minStock} onChange={e => setEditModal(m => ({...m, item: {...m.item!, minStock: Number(e.target.value)}}))} className="border rounded px-2 py-1 w-full" placeholder="Mínimo" />
                      <div className="flex gap-2 justify-end">
                        <button type="button" className="px-4 py-2 bg-gray-300 rounded" onClick={() => setEditModal({open:false})}>Cancelar</button>
                        <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded">Salvar</button>
                      </div>
                    </form>
                  </div>
                </div>
              )}
        <div className="fixed inset-0 bg-black bg-opacity-40 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded shadow-lg w-full max-w-md">
            <h3 className="text-lg font-bold mb-4">Cadastro rápido de Item de Estoque</h3>
