"use client";
import { useState } from "react";

type Document = {
  id: string;
  type: string;
  name: string;
  entity: string;
  fileName: string;
  fileUrl: string;
};

export default function Documents() {
  const [docs, setDocs] = useState<Document[]>([]);
  const [type, setType] = useState("");
  const [name, setName] = useState("");
  const [entity, setEntity] = useState("");
  const [file, setFile] = useState<File | null>(null);

  // Simples persistência local
  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!type || !name || !entity || !file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      const url = ev.target?.result as string;
      const newDoc = {
        id: Date.now().toString(),
        type,
        name,
        entity,
        fileName: file.name,
        fileUrl: url,
      };
      const updated = [...docs, newDoc];
      setDocs(updated);
      localStorage.setItem("documents", JSON.stringify(updated));
      setType(""); setName(""); setEntity(""); setFile(null);
    };
    reader.readAsDataURL(file);
  };

  // Carregar do localStorage
  useState(() => {
    try {
      const saved = JSON.parse(localStorage.getItem("documents") || "[]");
      setDocs(saved);
    } catch {}
  });

  return (
    <div className="max-w-2xl mx-auto px-2 sm:px-4">
      <h2 className="text-2xl font-bold mb-4">Gestão de Documentos</h2>
      <form onSubmit={handleAdd} className="mb-4 flex flex-col gap-2">
        <select value={type} onChange={e => setType(e.target.value)} className="border rounded px-2 py-1">
          <option value="">Tipo</option>
          <option value="Certificado">Certificado</option>
          <option value="Licença">Licença</option>
          <option value="Contrato">Contrato</option>
        </select>
        <input value={name} onChange={e => setName(e.target.value)} placeholder="Nome do documento" className="border rounded px-2 py-1" />
        <input value={entity} onChange={e => setEntity(e.target.value)} placeholder="Navio/Jangada vinculada" className="border rounded px-2 py-1" />
        <input type="file" onChange={e => setFile(e.target.files?.[0] || null)} className="border rounded px-2 py-1" />
        <button type="submit" className="bg-blue-600 text-white px-4 py-2 rounded">Salvar</button>
      </form>
      <h3 className="text-lg font-bold mb-2">Documentos cadastrados</h3>
      <table className="min-w-full bg-white rounded shadow mb-2 text-xs sm:text-sm">
        <thead>
          <tr className="bg-blue-100">
            <th className="p-2">Tipo</th>
            <th className="p-2">Nome</th>
            <th className="p-2">Vinculado</th>
            <th className="p-2">Arquivo</th>
          </tr>
        </thead>
        <tbody>
          {docs.map((d: any) => (
            <tr key={d.id} className="border-t align-top">
              <td className="p-2">{d.type}</td>
              <td className="p-2">{d.name}</td>
              <td className="p-2">{d.entity}</td>
              <td className="p-2">
                <a href={d.fileUrl} target="_blank" rel="noopener noreferrer" className="underline text-blue-600">{d.fileName}</a>
              </td>
            </tr>
          ))}
          {docs.length === 0 && (
            <tr><td colSpan={4} className="p-2 text-gray-400">Nenhum documento cadastrado.</td></tr>
          )}
        </tbody>
      </table>
    </div>
  );
}

"use client";
import { useState, useEffect, useCallback } from "react";

type Custo = {
  id: string;
  tipo: string;
  descricao: string;
  valor: string;
  data: string;
  entidade: string;
};

export default function Custos() {
  const [custos, setCustos] = useState<Custo[]>([]);
  const [tipo, setTipo] = useState("");
  const [descricao, setDescricao] = useState("");
  const [valor, setValor] = useState("");
  const [data, setData] = useState("");
  const [entidade, setEntidade] = useState("");
  const [loading, setLoading] = useState(true);

  // Carregar custos da API (com fallback localStorage para migração)
  const fetchCustos = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch("/api/custos");
      if (res.ok) {
        const data = await res.json();
        setCustos(data);
      } else {
        // Fallback para localStorage durante migração
        const salvos = JSON.parse(localStorage.getItem("custos") || "[]");
        setCustos(salvos);
      }
    } catch {
      // Fallback offline
      try {
        const salvos = JSON.parse(localStorage.getItem("custos") || "[]");
        setCustos(salvos);
      } catch { /* empty */ }
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchCustos();
  }, [fetchCustos]);

  // Adicionar custo
  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!tipo || !descricao || !valor || !data || !entidade) return;
    const novo: Custo = {
      id: Date.now().toString(),
      tipo,
      descricao,
      valor,
      data,
      entidade,
    };

    // Optimistic update
    const atualizados = [...custos, novo];
    setCustos(atualizados);
    setTipo(""); setDescricao(""); setValor(""); setData(""); setEntidade("");

    // Persistir na API
    try {
      const res = await fetch("/api/custos", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(novo),
      });
      if (res.ok) {
        const saved = await res.json();
        setCustos(prev => prev.map(c => c.id === novo.id ? { ...saved, id: String(saved.id) } : c));
      } else {
        // Fallback localStorage
        localStorage.setItem("custos", JSON.stringify(atualizados));
      }
    } catch {
      // Fallback offline
      localStorage.setItem("custos", JSON.stringify(atualizados));
    }
  };

  // Eliminar custo
  const handleDelete = async (id: string) => {
    const atualizados = custos.filter(c => c.id !== id);
    setCustos(atualizados);
    try {
      await fetch(`/api/custos?id=${id}`, { method: "DELETE" });
    } catch {
      localStorage.setItem("custos", JSON.stringify(atualizados));
    }
  };

  // Calcular total
  const totalCustos = custos.reduce((acc, c) => acc + Number(c.valor || 0), 0);

  return (
    <div className="max-w-3xl mx-auto px-2 sm:px-4">
      <h2 className="text-2xl font-bold mb-4">Custos de Inspeção/Manutenção</h2>
      <form onSubmit={handleAdd} className="mb-4 flex flex-col gap-2">
        <select value={tipo} onChange={e => setTipo(e.target.value)} className="border rounded px-2 py-1">
          <option value="">Tipo</option>
          <option value="Inspeção">Inspeção</option>
          <option value="Manutenção">Manutenção</option>
          <option value="Material">Material</option>
          <option value="Transporte">Transporte</option>
          <option value="Certificação">Certificação</option>
          <option value="Outro">Outro</option>
        </select>
        <input value={descricao} onChange={e => setDescricao(e.target.value)} placeholder="Descrição" className="border rounded px-2 py-1" />
        <input value={valor} onChange={e => setValor(e.target.value)} placeholder="Valor (€)" className="border rounded px-2 py-1" type="number" min="0" step="0.01" />
        <input value={data} onChange={e => setData(e.target.value)} type="date" className="border rounded px-2 py-1" />
        <input value={entidade} onChange={e => setEntidade(e.target.value)} placeholder="Navio/Jangada vinculada" className="border rounded px-2 py-1" />
        <button type="submit" className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 transition-colors">Guardar</button>
      </form>

      <div className="flex items-center justify-between mb-2">
        <h3 className="text-lg font-bold">Custos registados</h3>
        {custos.length > 0 && (
          <span className="text-sm font-semibold bg-blue-100 text-blue-800 px-3 py-1 rounded-full">
            Total: {totalCustos.toFixed(2)} €
          </span>
        )}
      </div>

      {loading ? (
        <div className="text-center text-gray-400 py-8">A carregar...</div>
      ) : (
        <table className="min-w-full bg-white rounded shadow mb-2 text-xs sm:text-sm">
          <thead>
            <tr className="bg-blue-100">
              <th className="p-2">Tipo</th>
              <th className="p-2">Descrição</th>
              <th className="p-2">Valor</th>
              <th className="p-2">Data</th>
              <th className="p-2">Vinculado</th>
              <th className="p-2">Ações</th>
            </tr>
          </thead>
          <tbody>
            {custos.map((c: Custo) => (
              <tr key={c.id} className="border-t align-top hover:bg-gray-50">
                <td className="p-2">{c.tipo}</td>
                <td className="p-2">{c.descricao}</td>
                <td className="p-2 text-right font-mono">{Number(c.valor).toFixed(2)} €</td>
                <td className="p-2">{c.data}</td>
                <td className="p-2">{c.entidade}</td>
                <td className="p-2">
                  <button
                    onClick={() => handleDelete(c.id)}
                    className="text-red-500 hover:text-red-700 text-xs"
                    title="Eliminar"
                  >
                    ✕
                  </button>
                </td>
              </tr>
            ))}
            {custos.length === 0 && (
              <tr><td colSpan={6} className="p-2 text-gray-400 text-center">Nenhum custo registado.</td></tr>
            )}
          </tbody>
        </table>
      )}
    </div>
  );
}

import { lifejacketModelData, type LifejacketBrandCatalog, type LifejacketModel } from "@/modules/lifejackets/lifejacketModelData";
import { getManualLibraryUrl } from "@/lib/external-tech-docs";

export type LifejacketManualLink = {
  fileName: string;
  label: string;
  href: string;
};

export type ResolvedLifejacketManuals = {
  brandCatalog: LifejacketBrandCatalog | null;
  matchedModel: LifejacketModel | null;
  displayLabel: string;
  manuals: LifejacketManualLink[];
};

function normalizeText(value: string | null | undefined) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim()
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .replace(/\s+/g, " ");
}

function unique<T>(values: T[]) {
  return Array.from(new Set(values));
}

function buildManualHref(relativePath: string) {
  return getManualLibraryUrl();
}

function getManualCandidatePaths(brand: string | null | undefined, fileName: string) {
  const normalizedBrand = normalizeText(brand);

  const brandFolderMap: Record<string, string[]> = {
    crewsaver: ["coletes/crewsaver"],
  };

  const brandFolders = brandFolderMap[normalizedBrand] || [];

  return unique([
    ...brandFolders.map((folder) => `${folder}/${fileName}`),
    `coletes/${fileName}`,
    `${normalizedBrand ? `${normalizedBrand}/` : ""}${fileName}`,
  ].filter((value) => !value.startsWith("/")));
}

function findMatchingModel(models: LifejacketModel[], model: string | null | undefined) {
  const normalizedModel = normalizeText(model);
  if (!normalizedModel) return null;

  return models.find((entry) => {
    const candidate = normalizeText(entry.model);
    return candidate === normalizedModel || candidate.includes(normalizedModel) || normalizedModel.includes(candidate);
  }) || null;
}

export function resolveLifejacketManuals(brand: string | null | undefined, model: string | null | undefined): ResolvedLifejacketManuals {
  const normalizedBrand = normalizeText(brand);
  const brandCatalog = lifejacketModelData.find((entry) => normalizeText(entry.brand) === normalizedBrand) || null;

  if (!brandCatalog) {
    return { brandCatalog: null, matchedModel: null, displayLabel: "", manuals: [] };
  }

  const matchedModel = findMatchingModel(brandCatalog.models, model);
  const manualFiles = unique(
    (matchedModel?.manualFiles && matchedModel.manualFiles.length > 0
      ? matchedModel.manualFiles
      : brandCatalog.models.flatMap((entry) => entry.manualFiles || []))
      .filter(Boolean)
  );

  const manuals = manualFiles.map((fileName) => {
    const relativePath = getManualCandidatePaths(brandCatalog.brand, fileName)[0] || `coletes/${fileName}`;
    return {
      fileName,
      label: matchedModel ? `${brandCatalog.brand} · ${matchedModel.model}` : brandCatalog.brand,
      href: buildManualHref(relativePath),
    };
  });

  const displayLabel = matchedModel ? `${brandCatalog.brand} · ${matchedModel.model}` : brandCatalog.brand;

  return { brandCatalog, matchedModel, displayLabel, manuals };
}

"use client";

export const isRecreio = (shipDetails: any): boolean => {
  if (!shipDetails) return false;
  const haystack = `${shipDetails.tipoPesca || ""} ${shipDetails.tipoNavio || ""}`.toLowerCase();
  return haystack.includes("recreio");
};

export const getInspectionIntervalYears = (brand: string, model: string, shipDetails: any): number => {
  const brandNorm = (brand || "").toUpperCase().trim();
  const modelNorm = (model || "").toUpperCase().trim();
  if (brandNorm.includes("EUROVINIL") && modelNorm.includes("EASY")) return 4;
  if (!isRecreio(shipDetails)) return 1;
  if (brandNorm.includes("RFD") || brandNorm.includes("DSB") || brandNorm.includes("ZODIAC")) return 1;
  return 3;
};

export const getInspectionIntervalLabel = (brand: string, model: string, shipDetails: any): string => {
  const years = getInspectionIntervalYears(brand, model, shipDetails);
  return years === 1 ? "12 meses" : `${years} anos`;
};

export const getSubstitutionMaxValidityDays = (brand: string, model: string, shipDetails: any): number =>
  getInspectionIntervalYears(brand, model, shipDetails) * 365;

import { findRaftTechnicalModel } from "@/modules/rafts/raftModelData";
import { getBoletinsLibraryUrl } from "@/lib/external-tech-docs";
import type {
  ApplicableTechnicalBulletin,
  TechnicalBulletin,
  TechnicalBulletinRule,
} from "@/modules/rafts/types";

const EV_BULLETIN_FILE = "EV Leisure rafts – Replacement of PRV valve type VSP-EV_08.pdf";
const RFD_OTS65_BULLETIN_FILE = "RFD Marine - Liferafts_ Replace all OTS-65 PRV's after 10 year life.pdf";
const SURVITEC_MKIV_CANOPY_ZIPS_FILE = "Marine Mk IV liferafts — Canopy _ Inspect the canopy doorway zip sliders.pdf";
const SURVITEC_MULTI_LABEL_SHEETS_FILE = "Marine — Liferaft Container _  Introduction of multi-label sheets.pdf";
const SURVITEC_RL6_INTERNAL_LAMP_FILE = "Marine Surviva Mk IV & ISO 9650 — Liferaft _ Installation of RL6 internal lamp.pdf";
const SURVITEC_MK16_DRAIN_HOLES_FILE = "84_16 Marine Make drain holes in Mk 16 flat-pack containers (1).pdf";
const SURVITEC_MKIV_SERVICING_OPTIMISATION_FILE = "Marine Mk IV liferafts — Servicing _ Servicing optimisation (gasket seal, pyrotechnics valises, bellows valise, canopy zips).pdf";
const SURVITEC_SPARES_CONSOLIDATION_FILE = "Marine liferafts — Spare parts _ Consolidation of multiple branded part numbers.pdf";
const SURVITEC_EMERGENCY_PACK_PROTECTIVE_FOAM_FILE = "Marine liferafts — Emergency pack_ Position of protective foam.pdf";
const SURVITEC_DK99_OPERATING_HEAD_FILE = "Marine liferafts and MES — Inflation system _ Replace the Thanner DK99 operating head.pdf";

function normalizeToken(value: unknown): string {
  return String(value ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, " ")
    .trim();
}

function buildComparableTokens(value: unknown): string[] {
  const normalized = normalizeToken(value);
  if (!normalized) return [];
  const compact = normalized.replace(/\s+/g, "");
  return Array.from(new Set([normalized, compact]));
}

function includesComparable(haystack: string, needle: string): boolean {
  const hayTokens = buildComparableTokens(haystack);
  const needleTokens = buildComparableTokens(needle);
  return needleTokens.some((needleToken) => hayTokens.some((hayToken) => hayToken.includes(needleToken) || needleToken.includes(hayToken)));
}

function canonicalizeBrand(value: unknown): string {
  const normalized = normalizeToken(value);
  if (!normalized) return "";
  if (normalized === "EV" || normalized.includes("EUROVINIL")) return "EUROVINIL";
  if (normalized.includes("SURVITEC")) return "SURVITEC";
  if (normalized.includes("SEA SAFE")) return "SEA-SAFE";
  return normalized;
}

function extractMkFamilyAliases(model: string): string[] {
  const normalized = normalizeToken(model);
  if (!normalized) return [];

  const aliases: string[] = [];
  const mapping: Array<{ patterns: RegExp[]; canonical: string; technical?: string }> = [
    { patterns: [/\bMK\s*IV\b/, /\bMK4\b/], canonical: "SURVIVA MKIV", technical: "SURVIVA MKIV TO" },
    { patterns: [/\bMK\s*III\b/, /\bMK3\b/], canonical: "SURVIVA MKIII" },
    { patterns: [/\bMK\s*II\b/, /\bMK2\b/], canonical: "SURVIVA MKII" },
    { patterns: [/\bMK\s*I\b/, /\bMK1\b/], canonical: "SURVIVA MKIV TO", technical: "SURVIVA MKIV TO" },
  ];

  for (const entry of mapping) {
    if (entry.patterns.some((pattern) => pattern.test(normalized))) {
      aliases.push(entry.canonical);
      if (entry.technical) aliases.push(entry.technical);
    }
  }

  return aliases;
}

function getDerivedModelAliases(brand: string, model: string): string[] {
  const normalizedBrand = canonicalizeBrand(brand);
  const normalizedModel = normalizeToken(model);
  const aliases: string[] = [];

  if (normalizedBrand === "EUROVINIL") {
    if (normalizedModel === "STD" || normalizedModel.startsWith("STD ") || normalizedModel.includes("ST INTL") || normalizedModel.includes("INTERNACIONAL") || normalizedModel.includes("INTERNATIONAL")) {
      aliases.push("SYNTESY INTERNACIONAL", "SYTETESY INTERNACIONAL", "ST-INTL", "STD");
    }
    if (normalizedModel.includes("ISO 9650 1") || normalizedModel.includes("ISO9650 1")) {
      aliases.push("SYNTESY ISO 9650-1 MK2", "EV ISO 9650-1");
    }
    if (normalizedModel.includes("ISO 9650 2") || normalizedModel.includes("ISO9650 2")) {
      aliases.push("SYNTESY ISO 9650-2 MK2", "EV ISO 9650-2");
    }
    if (normalizedModel.includes("SPAIN")) {
      aliases.push("EV ISO9650 (SPAIN)");
    }
    if (normalizedModel.includes("GREEK")) {
      aliases.push("ST-GREEK");
    }
    if (normalizedModel.includes("DM77") || normalizedModel.includes("ITA")) {
      aliases.push("ST-ITA DM77");
    }
    if (normalizedModel.includes("DM219")) {
      aliases.push("EV ISO 9650-1 (DM219)");
    }
  }

  if (normalizedBrand === "RFD") {
    aliases.push(...extractMkFamilyAliases(model));
  }

  return aliases;
}

function getModelCandidates(brand: unknown, model: unknown): string[] {
  const brandText = String(brand ?? "");
  const modelText = String(model ?? "");
  const candidates = new Set<string>();

  const technicalModel = findRaftTechnicalModel(brandText, modelText);
  [
    modelText,
    technicalModel?.name,
    ...(technicalModel?.aliases || []),
    ...getDerivedModelAliases(brandText, modelText),
  ]
    .filter(Boolean)
    .forEach((value) => candidates.add(String(value)));

  return Array.from(candidates);
}

export function parseManufactureYear(value: unknown): number | null {
  const raw = String(value ?? "").trim();
  if (!raw) return null;

  const directYear = raw.match(/(?:19|20)\d{2}/);
  if (directYear) return Number(directYear[0]);

  const mmYyyy = raw.match(/^(\d{1,2})\/(\d{4})$/);
  if (mmYyyy) return Number(mmYyyy[2]);

  const parsed = Date.parse(raw);
  if (!Number.isNaN(parsed)) return new Date(parsed).getFullYear();

  return null;
}

function parseManufactureDateInfo(value: unknown): { date: Date; label: string; precision: "year" | "month" | "date" } | null {
  const raw = String(value ?? "").trim();
  if (!raw) return null;

  const mmYyyy = raw.match(/^(\d{1,2})\/(\d{4})$/);
  if (mmYyyy) {
    const month = Number(mmYyyy[1]);
    const year = Number(mmYyyy[2]);
    if (month >= 1 && month <= 12) {
      return {
        date: new Date(year, month - 1, 1),
        label: `${String(month).padStart(2, "0")}/${year}`,
        precision: "month",
      };
    }
  }

  const directYear = raw.match(/^(?:19|20)\d{2}$/);
  if (directYear) {
    const year = Number(directYear[0]);
    return {
      date: new Date(year, 0, 1),
      label: directYear[0],
      precision: "year",
    };
  }

  const parsed = Date.parse(raw);
  if (!Number.isNaN(parsed)) {
    const date = new Date(parsed);
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    return {
      date,
      label: `${day}/${month}/${year}`,
      precision: "date",
    };
  }

  const yearFromText = raw.match(/(?:19|20)\d{2}/);
  if (yearFromText) {
    const year = Number(yearFromText[0]);
    return {
      date: new Date(year, 0, 1),
      label: yearFromText[0],
      precision: "year",
    };
  }

  return null;
}

function addMonths(date: Date, months: number): Date {
  const result = new Date(date);
  result.setMonth(result.getMonth() + months);
  return result;
}

function addYears(date: Date, years: number): Date {
  const result = new Date(date);
  result.setFullYear(result.getFullYear() + years);
  return result;
}

function formatMonthYear(date: Date): string {
  return `${String(date.getMonth() + 1).padStart(2, "0")}/${date.getFullYear()}`;
}

function parseCapacityValue(value: unknown): number | null {
  if (typeof value === "number" && Number.isFinite(value)) return value;

  const raw = String(value ?? "").trim();
  if (!raw) return null;

  const direct = raw.match(/\b(\d{1,3})\b/);
  if (direct) return Number(direct[1]);

  return null;
}

function resolveRaftCapacity(raft: { capacity?: unknown; model?: unknown }): number | null {
  const directCapacity = parseCapacityValue(raft.capacity);
  if (directCapacity !== null) return directCapacity;

  const modelText = String(raft.model ?? "");
  const embeddedCapacity = modelText.match(/\b(4|6|8|10|12|16|20|25|37|50)\s*P\b/i);
  if (embeddedCapacity) return Number(embeddedCapacity[1]);

  return null;
}

function parseMetersValue(value: unknown): number | null {
  if (typeof value === "number" && Number.isFinite(value)) return value;

  const raw = String(value ?? "").trim();
  if (!raw) return null;

  const normalized = raw.replace(/,/g, ".");
  const match = normalized.match(/(\d+(?:\.\d+)?)/);
  if (!match) return null;

  return Number(match[1]);
}

